INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r6c8b', 'r6c8b', 'Extensão universitária na UFFS: trajetórias, alcances e desafios', NULL, '["Émerson Neves da Silva","Solange Todero Von Onçay"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A discussão acerca da importância formativa da extensão universitária intensificou-se, nos últimos dez anos, na academia e no Conselho Nacional de Educação (CNE), culminando com a Resolução Nº 7, de 18/12/ 2018/CNE, que estabeleceu as Diretrizes para a Extensão na Educação Superior Brasileira e a curricularização da extensão. Impulsionado por essa movimentação, com o objetivo de produzir reflexões e socializar compreensões, o livro Extensão Universitária na UFFS: trajetórias, alcances e desafios é fruto de trabalho coletivo de docentes, discentes, técnicos administrativos e comunidade regional, desenvolvido ao longo do I Seminário Integrador de Extensão da UFFS, realizado em 2016. O foco central é a sistematização de experiências de projetos e programas desenvolvidos na UFFS, advindos das ações extensionistas, considerando a relação indissociável com o ensino e a pesquisa, num revigor mútuo, contribuindo e gerando reflexões para a discussão vindoura da curricularização na UFFS. Assim, a essência da obra não pode ser apreendida fora deste movimento que implica a relação práxica, desde a concepção de extensão produzida e defendida pela UFFS, uma instituição pública e democrática que nasceu no seio das lutas sociais e se substancia das relações comunitárias e extensionistas.', '["university extension","curricularization of extension","teaching-research-extension integration","university-community relations"]', '10.7476/9786586545067', '9786586545050', 'https://books.scielo.org/id/r6c8b', 'https://books.scielo.org/id/r6c8b/pdf/silva-9786586545067.pdf', 'https://books.scielo.org/id/r6c8b/epub/silva-9786586545067.epub', 'https://books.scielo.org/id/r6c8b/cover/cover_thumbnail.jpeg', 166, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r6nm4', 'r6nm4', 'Dimensões teóricas e empíricas do turismo: perspectivas comparadas', 'perspectivas comparadas', '["Guzmán, Sócrates Jacobo Moquete","Pinto, Roque"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Esta coletânea apresenta reflexões teóricas e investigações empíricas sobre o turismo, destacando suas interfaces com cultura, hospitalidade, desenvolvimento e políticas públicas. Com contribuições de autores de diferentes países, a obra ferece um panorama comparado de experiências e desafios do setor em múltiplos contextos, unindo abordagens inter e multidisciplinares. Destinada a estudantes, professores, profissionais e gestores interessados na complexidade do fenômeno turístico.', '["tourism theory","tourism research","culture and tourism","hospitality","tourism and development","tourism policy","interdisciplinary approach"]', '10.7476/9788574556406', '9788574556277', 'https://books.scielo.org/id/r6nm4', 'https://books.scielo.org/id/r6nm4/pdf/guzman-9788574556406.pdf', NULL, 'https://books.scielo.org/id/r6nm4/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r6q5k', 'r6q5k', 'Uma trajetória da Arquivística a partir da Análise do Discurso: inflexões histórico-conceituais', NULL, '["Thiago Henrique Bragato Barros"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro considerou-se a Análise do Discurso uma disciplina que apresenta princípios metodológicos capazes de contribuir para a compreensão e delimitação de campos científicos e sociais, pois é por meio do jogo de enunciados, permeado por posições ideológicas colocadas em jogo no processo histórico social, que o texto (oral e escrito) é produzido, ou seja, a Arquivística relaciona-se com formações discursivas e formações ideológicas e estão relacionadas ao seu processo de construção histórica. Assim, propõe-se a apresentação de elementos histórico-conceituais que ressaltem as diferenças e semelhanças entre a esfera teórica e a esfera institucional na Arquivística. O problema configurou-se em buscar sistematizar e identificar o discurso institucional e a teoria Arquivística, construindo um paralelo histórico entre o percurso da área em tradições cruciais para a prática e a teoria Arquivística na atualidade. Por meio da análise das práticas teóricas e profissionais a respeito da representação Arquivística na atualidade pelos autores de três correntes selecionadas (brasileira, canadense e espanhola) e como os mesmos são trabalhados nas instituições Arquivísticas federais destes países. Deste modo, objetivou-se por meio do quadro teórico-metodológico da Análise do Discurso compreender como se comportam, se constroem e se desenvolvem esses conceitos na Arquivística, visando a uma possível sistematização conceitual e discursiva da disciplina. Esta análise acorreu em primeira instância a partir de uma análise teórico-histórica das tradições e em segunda instância atores específicos e fundamentais, no caso teórico e das instituições Arquivísticas que centralizam e demarcam o campo de atuação dos arquivistas no caso, os Arquivos Nacionais ou gerais. Chegou-se a delimitação de possíveis formações discursivas na Arquivística uma relacionada ao “tradicionalismo” e outra ao “reformismo”. Conclui-se que a Arquivística possui formações discursivas complexas construídas ao longo de sua trajetória institucional e teórica', '["archival science","discourse analysis","history of archival science","archival theory","archives","national archives","discursive formations","traditionalism","reformism","institutional discourse","conceptual systematization"]', '10.7476/9788579836619', '9788579836619', 'https://books.scielo.org/id/r6q5k', 'https://books.scielo.org/id/r6q5k/pdf/barros-9788579836619.pdf', NULL, 'https://books.scielo.org/id/r6q5k/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r6vrx', 'r6vrx', 'O modelo de desenvolvimento brasileiro das primeiras décadas do século XXI: aportes para o debate', NULL, '["Edemar Rotta","Herton Castiglioni Lopes","Neusa Rossini"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'O modelo de desenvolvimento implantado no Brasil a partir do início do século XXI situa-se em um contexto de crise do ideário neoliberal e retomada do pensamento desenvolvimentista. O ideário neoliberal, hegemônico no contexto mundial a partir da década de 1980, apresentou, no final dos anos 90, sinais claros de esgotamento: altas taxas de desemprego, ampliação das desigualdades, concentração de renda, baixos índices de crescimento econômico, entre outros. A construção de alternativas exigiu repensar as relações entre o mercado, o Estado e as diferentes organizações da sociedade civil. No caso brasileiro, a proposta que se tornou hegemônica retomou princípios desenvolvimentistas de uma ação mais incisiva do Estado, tanto como planejador e articulador, quanto como financiador e agente direto em processos econômicos e sociais com vistas ao desenvolvimento. Este novo modelo incita muitas reflexões para compreender suas características e repercussões nos cenários locais e regionais.', '["development models","neoliberalism","developmentalism","state intervention","state-market relations","civil society organizations","unemployment","income inequality","economic growth","Brazilian development","21st century"]', '10.7476/9788564905832', '9788564905832', 'https://books.scielo.org/id/r6vrx', 'https://books.scielo.org/id/r6vrx/pdf/rotta-9788564905832.pdf', NULL, 'https://books.scielo.org/id/r6vrx/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r76hr', 'r76hr', 'Ciência e saúde pela vida: 125 anos de história da Fiocruz', NULL, '["Sá, Dominichi Miranda de","Silva, André Felipe Cândido da","Vieira, Tamara Rangel","Mello, Vanessa Pereira da Silva e","El-Dine, Lorenna Ribeiro Zem"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2025, '2025-05-28', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Ciência e Saúde pela Vida: 125 anos de história da Fiocruz propõe uma abordagem interdisciplinar e não linear da história da Fiocruz, apresentando-a como protagonista permanente da história da ciência e da saúde pública no Brasil. Da fundação como Instituto Soroterápico Federal em 1900 à atuação internacional durante a pandemia de covid-19, o livro traça um panorama das transformações científicas, políticas e sociais que moldaram o país, e das quais a Fiocruz sempre fez parte. O livro é composto por textos introdutórios e reúne 121 verbetes escritos por 83 autores, em sua maioria historiadores da ciência e da saúde, e oferece ao público uma leitura acessível, crítica e profundamente conectada com os desafios do país.', '["Fiocruz","history of science","history of public health","history of medicine","COVID-19 pandemic","research institutions","Brazil"]', '10.7476/9786557082355', '9786557082041', 'https://books.scielo.org/id/r76hr', NULL, NULL, 'https://books.scielo.org/id/r76hr/cover/cover_thumbnail.jpeg', 658, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r7md6', 'r7md6', 'El amparo de tierras: la acción, el proceso y el juez de restitución', NULL, '["Manuel Ramírez","Rocío del Pilar Peña Huertas","María Mónica Parada Hernández","Ruiz González","Álvarez Morales Ricardo"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra es resultado de una revisión de los fallos de restitución proferidos desde el último trimestre del 2012 hasta las últimas que fueron publicadas del año 2014, que se hicieron públicos a través de los sitios de internet de la Unidad de Restitución de Tierras y del Consejo Superior de la Judicatura. Todos los fallos fueron organizados y sistematizados en una matriz que permitiera identificar los hechos principales expuestos en cada fallo, los asuntos que serían desarrollados en el mismo y los problemas jurídicos que abordó cada uno. El libro se desarrolla de la siguiente manera: en el primer capítulo se enmarca la tesis que se defiende, es decir, que los jueces de restitución son jueces constitucionales y pueden de acuerdo con López construir precedente horizontal. En el capítulo 2 se abordarán las decisiones judiciales sobre acumulación de procesos a la restitución de tierras. Luego, se tratará el tema de la titulación conyugal en el marco de los fallos de restitución. En el capítulo 4 nos referimos a las decisiones relevantes sobre la aplicación del enfoque diferencial en el proceso de restitución. Posteriormente se analizará la cuestión de la buena fe exenta de culpa y los opositores en las sentencias de restitución. En seguida, en el capítulo 6 se abordarán los fallos de restitución relevantes sobre el tema de la adjudicación de baldíos a través del proceso de restitución. Muy relacionado con este tema, en el siguiente capítulo se trata la relación de la restitución de tierras con la Unidad Agrícola Familiar (UAF) como figura particular de la legislación agraria. A continuación, en el capítulo 8 se analizarán las decisiones judiciales más relevantes sobre la restitución en Zonas de Reserva Forestal (ZRF). Finalmente el capítulo 9 se encargará de analizar los procesos de restitución en las zonas en las que hay labores de exploración y explotación de recursos minero-energéticos.', '["land restitution","amparo","differential approach","agricultural law","Colombian case law"]', '10.7476/9789587386752', '9789587386745', 'https://books.scielo.org/id/r7md6', NULL, NULL, 'https://books.scielo.org/id/r7md6/cover/cover_thumbnail.jpeg', 147, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r7pjf', 'r7pjf', 'Frágeis deuses: profissionais da emergência entre os danos da violência e a recriação da vida', NULL, '["Suely Ferreira Deslandes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A autora demonstra o potencial da aplicação do que se poderia chamar de métodos ''clássicos'' da pesquisa antropológica para além dos contextos sociais mais comumente explorados. A ''comunidade'' estudada por Deslandes, cujos atores vêem-se interligados pela questão da violência, mescla uma composição ímpar, incluindo médicos, baleados, enfermeiros, esfaqueados, bombeiros, atropelados, entre outros. É uma ''comunidade'' com características bastante particulares, como o intenso fluxo, a imensa tensão e a vivência de experiências-limite, mas ainda assim profundamente informadora sobre a realidade contemporânea brasileira.', '["violence","victims of violence","trauma (physical injury)","emergency services","life reconstruction","anthropological fieldwork"]', '10.7476/9788575415283', '9788575415283', 'https://books.scielo.org/id/r7pjf', 'https://books.scielo.org/id/r7pjf/pdf/deslandes-9788575415283.pdf', NULL, 'https://books.scielo.org/id/r7pjf/cover/cover_thumbnail.jpeg', NULL, 32, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r7syv', 'r7syv', 'Cultura do silêncio e democracia no Brasil: ensaios em defesa da liberdade de expressão (1980-2015)', NULL, '["Venício A. de Lima"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra traz o conceito de comunicação articulado por Paulo Freire, a sua atualidade e sua vinculação à noção republicana de liberdade. Aborda ainda o conceito seminal de cultura do silêncio desde suas raízes em Vieira até sua apropriação criativa em Freire. Em Stuart Hall, o autor foi buscar a sua contribuição para os estudos de mídia.', '["culture of silence","freedom of expression","democracy","Paulo Freire","communication","republican liberty","Stuart Hall","media studies"]', '10.7476/9788523013394', '9788523011536', 'https://books.scielo.org/id/r7syv', NULL, NULL, 'https://books.scielo.org/id/r7syv/cover/cover_thumbnail.jpeg', 424, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r7wwf', 'r7wwf', 'Redes regionalizadas de atenção à saúde: desafios à integração assistencial e à coordenação do cuidado', NULL, '["Adriano Maia dos Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'A busca por um sistema único de saúde público e universal de qualidade, fundado na atenção primária como coordenadora do cuidado integral, é o que norteia a pesquisa elaborada por Adriano Maia dos Santos em Redes regionalizadas de atenção à saúde. Ao longo de 4 capítulos, o autor demonstra que uma Atenção Primária à Saúde (APS) robusta e consistente é crucial para a manutenção do SUS, pois é a resposta mais adequada às mudanças no perfil demográfico e epidemiológico, com envelhecimento populacional e prevalência de enfermidades crônicas que necessitam cuidado integral, coordenado e longitudinal', '["primary care","integrated care","care coordination","Unified Health System (SUS)","universal health care","chronic disease","population aging","longitudinal care"]', '10.7476/9788523220266', '9788523220266', 'https://books.scielo.org/id/r7wwf', 'https://books.scielo.org/id/r7wwf/pdf/santos-9788523220266.pdf', NULL, 'https://books.scielo.org/id/r7wwf/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r8sxy', 'r8sxy', 'Controles e autonomia: as Forças Armadas e o sistema político brasileiro (1974-1999)', NULL, '["Samuel Alves Soares"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O objetivo central deste livro é verificar de que maneira a relação entre o aparelho militar e o sistema político no período de 1974 a 1999 afetou a consolidação da democracia do país. Este aspecto-chave foi desdobrado analiticamente em dois planos: o legal-institucional e a conjuntura política. No primeiro plano, a referência básica é a função das Forças Armadas na Carta Magna e as missões definidas nos textos infraconstitucionais, conferindo-se as principais posições defendidas pelos atores políticos relevantes - partidos, militares, empresários e sindicatos - na configuração legal da função e das missões atribuídas ao aparelho militar. O segundo plano focaliza a conjuntura do período indicado. Neste caso, trata-se de uma análise pontual de momentos cruciais da conjuntura política, pinçando os elementos diretamente vinculados àquela relação entre militares e sistema político.', '["military personnel","military autonomy","military control","Brazilian military dictatorship","democratization","military missions","political situation","military and politics"]', '10.7476/9788539302918', '9788571396258', 'https://books.scielo.org/id/r8sxy', NULL, NULL, 'https://books.scielo.org/id/r8sxy/cover/cover_thumbnail.jpeg', 224, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r9', 'r9', 'Transas na cena em transe: teatro e contracultura na Bahia', NULL, '["Raimundo Matos de Leão"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra é fruto de tese defendida no Programa de Pós-Graduação em Artes Cênicas da UFBA, em 2007. Aborda questões relativas ao teatro em meio ao ideário contracultural, investindo sua argumentação contra a afirmação de que a produção teatral que se dá de 1968 a 1974 é destituída de criticidade. Propondo outro ponto de vista, o livro apresenta e analisa a produção teatral para afirmar que não houve um "vazio cultural" durante o período em que o governo civil-militar esteve no poder e utilizou a censura e a repressão para calar os artistas.', '["theatre","counterculture","Bahia","military dictatorship","censorship","cultural criticism"]', '10.7476/9788523209414', '9788523209414', 'https://books.scielo.org/id/r9', 'https://books.scielo.org/id/r9/pdf/leao-9788523209414.pdf', NULL, 'https://books.scielo.org/id/r9/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r9b6b', 'r9b6b', 'Michel Foucault: crítico-esteta-cínico mitigado', NULL, '["Jorge Alberto Rocha"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A partir de uma sugestão de Gilles Deleuze e Félix Guattari – a de que todos os filósofos ocidentais terminaram construindo, no interregno do seu pensamento, personagens conceituais, uma espécie de assinatura do filósofo – este livro objetiva identificar esse traço a partir da obra de Michel Foucault. A tese em questão é que este autor não se enquadra em uma imagem única, como a do Juiz em Kant, ou a do sedutor em Kierkegaard, mas em uma imagem híbrida e triádica, fazendo coro com muitos filósofos chamados de transversais e que se instalaram no horizonte de filosofias chamadas de pós-estruturalistas, como Deleuze.', '["Michel Foucault","Gilles Deleuze","Félix Guattari","philosophical character","poststructuralism","Immanuel Kant","Søren Kierkegaard","aesthetic criticism","cynicism"]', '10.7476/9788578791841', '9788578791841', 'https://books.scielo.org/id/r9b6b', 'https://books.scielo.org/id/r9b6b/pdf/rocha-9788578791841.pdf', NULL, 'https://books.scielo.org/id/r9b6b/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r9m2g', 'r9m2g', 'Governança multiescalar dos recursos hídricos transfronteiriços na Amazônia', NULL, '["Fernanda Mello Sant’Anna"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A Bacia Amazônica é compartilhada por Bolívia, Brasil, Colômbia, Equador, Guiana, Peru e Venezuela, e seus recursos hídricos transfronteiriços são foco de vários projetos de infraestrutura e de exploração econômica. Essas atividades causam contaminação e degradação dessa bacia, revelando a necessidade de governança multiescalar para regular o uso internacional, nacional e local desses recursos hídricos. Em escala internacional, foram analisadas instituições como a Organização do Tratado de Cooperação Amazônica (OTCA) e as relações entre os Estados que compartilham as Bacia do rio Acre e do rio Napo. Em escala nacional, buscou-se compreender o arcabouço institucional para gestão dos recursos hídricos na Bolívia, no Brasil, no Equador e no Peru, países que compartilham essas duas bacias. Em escala local, estudou-se a governança das regiões de fronteira das bacias daqueles rios. Nas análises da cooperação entre esses atores sociais, verificou-se que, apesar da cooperação nas bacias analisadas, a governança ainda é incipiente, e os conflitos socioambientais tendem a se agravar.', '["multi-scalar governance","transboundary water resources","Amazon basin","Napo River basin","Amazon Cooperation Treaty Organization","interstate relations","water institutions","borderlands","socio-environmental conflicts","water pollution","water infrastructure projects","Brazil"]', '10.7476/9788595461802', '9788595461802', 'https://books.scielo.org/id/r9m2g', 'https://books.scielo.org/id/r9m2g/pdf/santanna-9788595461802.pdf', NULL, 'https://books.scielo.org/id/r9m2g/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r9qy6', 'r9qy6', 'Mulheres negras em perspectiva', 'identidades e experiências de escravidão e liberdade no espaço atlântico (séculos XVII-XIX)', '["Faria, Sheila de Castro","Reis, Adriana Dantas"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'humanities', 'Humanidades y Artes', NULL, 'Este livro traz, a partir do trabalho de historiadoras e historiadores, ma visão plural e diversa de trajetórias de mulheres negras em tempos de escravidão e de conquista da liberdade. Com caminhos que passam pelo continente africano, circulam pelo Oceano Atlântico e transitam por diferentes partes do Brasil, estas mulheres negras são apresentadas com as histórias que protagonizam, visíveis por estudos realizados sobre fontes primárias de variada procedência, analisadas criteriosamente e sob perspectivas distintas. Suas ideias, suas dores, as estratégias que criam, sua inquietude e as relações que estabelecem em sociedades que em geral lhes são hostis revelam o quanto e como lutaram e teceram alianças para sobreviver e ampliar espaços de liberdade e direitos. Os estudos das representações que sobre elas foram construídas permitem observar, por meio de olhares de outros, aspectos das suas próprias interferências no que se escrevia a seu respeito. Não são histórias de sucesso, nem tampouco de eterna subalternização, mas de afirmação, acompanhada muitas vezes por perdas e silêncios. Mulheres negras em perspectiva combate simplificações e distorções e coloca no centro do debate a profunda humanidade de suas personagens centrais', '[]', '10.7476/9788555921155', '9786589524069', 'https://books.scielo.org/id/r9qy6', NULL, NULL, 'https://books.scielo.org/id/r9qy6/cover/cover_thumbnail.jpeg', 438, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r9y7f', 'r9y7f', 'Agonia da fome', NULL, '["Maria do Carmo Soares de Freitas"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Tendo como tema central o fato de que a fome crônica não se manifesta apenas como problema social ou biomédico, esta obra se dedica ao estudo etnográfico da fome e sua relevância histórica e cada vez mais atual no contexto nacional. Sob uma ótica diferenciada, a autora denuncia os modos extremos de viver e de morrer dos famintos em uma comunidade pobre de Salvador. Formulado a partir de pesquisa de campo, com narrativas reveladoras de um universo repleto de alegorias da miséria, constitui trabalho pioneiro no que tange à fenomenologia da fome, onde se descortinam, minuciosamente, os diferentes significados atribuídos a ela por aqueles que vivem sob constante ameaça de não ter o que comer. Para além de um trabalho de simples denúncia, este livro é certamente uma importante contribuição à análise sociocultural do fenômeno da fome no País.', '["chronic hunger","famine","poverty","Salvador, Bahia","misery","food insecurity"]', '10.7476/9788575412497', '9788575412497', 'https://books.scielo.org/id/r9y7f', 'https://books.scielo.org/id/r9y7f/pdf/freitas-9788575412497.pdf', NULL, 'https://books.scielo.org/id/r9y7f/cover/cover_thumbnail.jpeg', NULL, 31, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rbp35', 'rbp35', 'Sociedade movediça: economia, cultura e relações sociais em São Paulo, 1808-1850', NULL, '["Denise Aparecida Soares de Moura"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta pesquisa sobre a sociedade paulista da primeira metade do oitocentos é tributária e também faz parte de um esforço para ampliar os estudos, investigações e interpretações deste amplo e diversificado painel historiográfico, literário e memorialístico. Retomando uma gama diversificada de documentos - jornais, como o Farol Paulistano, ofícios escritos por autoridades policiais, autos-cíveis, autos-crimes, atas, papéis avulsos e registros da Câmara, aquarelas, relatos de viajantes - e problematizando-os através da experiência da micro-análise, a autora procura infiltrar- se no tecido social urbano da cidade de São Paulo, entre os anos 1808-1850 e compreender outros contextos simultâneos ao da transmigração da família real para o Brasil, da implantação da Corte joanina, do processo de independência, das lutas regenciais e da implantação do Estado.', '["urban social relations","19th-century Brazil","colonial Brazil","Brazilian independence","regency","culture and economy","police records","criminal cases","travel accounts","microhistory"]', '10.7476/9788539304516', '9788571396173', 'https://books.scielo.org/id/rbp35', NULL, NULL, 'https://books.scielo.org/id/rbp35/cover/cover_thumbnail.jpeg', 328, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rbtvb', 'rbtvb', 'Vidas ao léu: trajetórias de exclusão social', NULL, '["Sarah Escorel"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Obra voltada para aqueles que estão realmente empenhados em solucionar, na teoria e na prática, os problemas da exclusão social institucionalizada. Ao voltar-se para a realidade dos moradores de rua, a autora fala e escuta. Fala quando busca, em alicerces teóricos, as causas e definições para a exclusão social. Escuta quando abre espaço, em seu trabalho, para as declarações daqueles que não ''têm um lugar no mundo''. O resultado é um relato sensível, por vezes impressionante, de um dos fenômenos mais cruéis da atualidade. Torna-se, deste modo, reflexão, avaliação e alerta: até quando seremos cúmplices na fabricação de excluídos da condição de cidadãos?', '["social exclusion","homeless people","life trajectories","citizenship","causes of social exclusion"]', '10.7476/9788575416051', '9788575416051', 'https://books.scielo.org/id/rbtvb', 'https://books.scielo.org/id/rbtvb/pdf/escorel-9788575416051.pdf', NULL, 'https://books.scielo.org/id/rbtvb/cover/cover_thumbnail.jpeg', NULL, 74, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rbvsb', 'rbvsb', 'Fanfiction e mercado editorial: relações entre Fandom e polissistema literário', NULL, '["Ingrid Lara de Araújo Utzig"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A fanfiction A Lenda de Fausto, de Samila Lages, foi transformada em romance pela Editora Multifoco em 2011. A partir das considerações de Henry Jenkins, Anne Jamison, Néstor Canclini, Régis Debray, Giselle Beiguelman e outros teóricos, buscou-se discutir a mobilidade da obra de Samila, entre quatro plataformas: o Nyah!, o zine, o blog da produtora e o livro físico. Intentou-se compreender os trajetos que precederam a publicação, perpassando processos de criação, produção, reprodução, circulação, recepção, difusão e editoração d’A Lenda de Fausto. Em tal percurso, percebeu-se que a fanfiction possui (im)possibilidades estéticas específicas do meio digital, uma vez que explora algumas potencialidades/limitações impostas pela interface do Nyah! e se desdobra em spin-offs, pois além d’A Lenda de Fausto, há a pré-sequência Relatos da Queda e a sequência O Trilo do Diabo. Pretendeu-se observar poética(s) da construção desse objeto e como Samila se apropria de diferentes estratégias a fim de estabelecer-se enquanto produtora (re)conhecida dentro e fora do microcosmo otaku. Os objetivos do trabalho se concentraram em investigar se o(s) fandom(s), comunidade(s) virtual(is) organizada(s) na ressignificação do conteúdo das franquias e da indústria cultural, com regras reunida(s) em torno de uma recepção não-passiva, em um modelo de consumo produtivo, constituem-se como sistema de cultura. Para debater essas dinâmicas, utilizou-se a teoria dos polissistemas, de Even-Zohar (2017). Desenhou-se como segundo objetivo propor que A Lenda de Fausto, em sua materialidade disposta no Nyah!, estabelece-se como literatura digital, apesar de não ser uma premissa comum ao gênero fanfiction, e como a prática empreendida na plataforma foi descontinuada e até mesmo apagada do contexto exordial na transição para mídiuns ulteriores. O terceiro objetivo foi notar como os fatores literários do fandom agregaram Samila ao polissistema literário por meio da transição ao mercado editorial impresso, o que gerou uma metamorfose de status – de produtora de fics a autora –. Por fim, buscou-se entender como se dá essa dupla existência de Samila/Ryoko, em ambientes com funcionamentos distintos. A tese defendida foi de que A Lenda de Fausto evidencia a intersecção de diferentes polissistemas por meio da mudança da materialidade: enquanto fic, uma série de fatores levou à legitimação no fandom. Enquanto romance publicado em livro, passou a ter outras formas de circulação e públicos mais amplos, gerando uma dupla camada de consagração: na comunidade fã e na literatura amapaense.', '["fan fiction","zines","digital literature","Even-Zohar","otaku culture","book trade","cultural industries","spin-offs","productive consumption","Brazilian literature","Henry Jenkins"]', '10.7476/9786559543755', '9786559543755', 'https://books.scielo.org/id/rbvsb', 'https://books.scielo.org/id/rbvsb/pdf/utzig-9786559543755.pdf', NULL, 'https://books.scielo.org/id/rbvsb/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rc48z', 'rc48z', 'Processo de trabalho em saúde: a produção do cuidado', NULL, '["Coelho, Thereza Christina Bahia","Teles, Milla Pauline da Silva Ferreira"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Os processos de produção do cuidado no âmbito do Sistema Único de Saúde (SUS), estão sendo constantemente remodelados desde sua criação, pari passu com o desenvolvimento teórico que os inspiram e o arcabouço estrutural que os sustentam, a partir da problematização e reflexão das realidades de trabalho enfrentadas. Esta obra apresenta à comunidade acadêmica, aos trabalhadores de saúde, aos gestores e aos demais envolvidos no cuidado em saúde, resultados de pesquisas envolvendo aspectos conceituas, históricos, metodológicos e práticas do campo do processo de trabalho em saúde, contemplando discussões aprofundadas no que tange à forma e às circunstâncias em que é organizado e realizado, com todas as implicações que representam para a vida e saúde daqueles inseridos nesses processos.', '["health work process","care production","Unified Health System (SUS)","healthcare workers","health care organization","health care delivery","health management","history of health care"]', '10.7476/9786589524885', '9786589524311', 'https://books.scielo.org/id/rc48z', NULL, NULL, 'https://books.scielo.org/id/rc48z/cover/cover_thumbnail.jpeg', 481, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rc5py', 'rc5py', 'Para além da praça: a Batalha do Vale e a educação das juventudes na cidade de Presidente Prudente (SP)', 'a Batalha do Vale e a educação das juventudes na cidade de Presidente Prudente (SP)', '["Bruno Fantin Salvi"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O presente livro objetiva debater como o envolvimento de jovens, negros e periféricos com coletivos juvenis, especialmente a Batalha do Vale (Hip Hop), influencia positivamente nas trajetórias espaciais e educacionais destes jovens. Ao se envolverem com o Hip Hop as juventudes periféricas tendem a se conscientizar a respeito das dinâmicas desiguais e excludentes que produzem a cidade e os espaços urbanos, passando então a buscar estratégias de superação, muitas vezes reencontrando nos estudos uma possibilidade de elaborar projetos e realiza-los.', '["hip hop","youth education","youth collectives","peripheral youth","Black youth","urban inequality","urban space","youth participation","educational trajectories","Presidente Prudente"]', '10.7476/9786559544462', '9786559544462', 'https://books.scielo.org/id/rc5py', 'https://books.scielo.org/id/rc5py/pdf/salvi-9786559544462.pdf', NULL, 'https://books.scielo.org/id/rc5py/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rd2qp', 'rd2qp', 'Um rei em três versões: a construção da história de D. Afonso Henriques pelos cronistas medievais portugueses', NULL, '["Kátia Brasilino Michelan"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, Kátia Brasilino Michelan busca trabalhar sob uma perspectiva historiográfica atual, tomando a questão das práticas de escrita e de memória na cultura ocidental, analisando o fazer histórico cronístico português do século XIV até o início do século XVI, com a narração da história do reinado de D. Afonso Henriques (1109?-1185), o primeiro rei português. Para isso, a autora selecionou três crônicas em língua ver­nácula que contam a história do monarca, procurando pôr em evidência três versões de séculos diferentes de uma mesma história, para assim perceber as atualizações do passado que cada cronista realizou. O leitor tem em mãos um livro de consistência indiscutível, relevante para os estudos sobre as crônicas e a memória da monarquia na época da formação do Estado lusitano.', '["Afonso Henriques","vernacular chronicles","historiography","representation of the past","Kingdom of Portugal","14th-16th centuries"]', '10.7476/9786557145395', '9786557145395', 'https://books.scielo.org/id/rd2qp', 'https://books.scielo.org/id/rd2qp/pdf/michelan-9786557145395.pdf', NULL, 'https://books.scielo.org/id/rd2qp/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rdfpk', 'rdfpk', 'Nas raias de um gênero: a fábula e o efeito fábula na obra infantil de Monteiro Lobato', NULL, '["Loide Nascimento de Souza"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O trabalho de Loide Nascimento de Souza transcende o anunciado no subtítulo deste livro: a fábula e o efeito fábula na obra de Monteiro Lobato. Suas conclusões, amparadas em competente manuseio da crítica da fábula, revelam que Lobato, apesar de não simpatizante do Modernismo de 22, escolhei o mais popular e tradicional dos gêneros – a fábula – como suporte para bem-sucedidos experimentos antropofágicos.', '["Monteiro Lobato","fables","children''s literature","literary genre","cannibalism","Brazilian literature"]', '10.7476/9786557144855', '9786557144855', 'https://books.scielo.org/id/rdfpk', 'https://books.scielo.org/id/rdfpk/pdf/souza-9786557144855.pdf', NULL, 'https://books.scielo.org/id/rdfpk/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rdfwg', 'rdfwg', 'Diálogos sobre diversidade, relações raciais e desigualdade no Brasil', NULL, '["Amanda Palomo Alves","Eronildo José da Silva","Marivânia Conceição Araujo"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O Núcleo de Estudos Interdisciplinares Afro-Brasileiros – NEIAB começou suas atividades na Universidade Estadual de Maringá há onze anos, a partir da iniciativa de professores do Departamento de Ciências Sociais e envolveu docentes de outros departamentos, alunos e comunidade externa. Desde então seus participantes têm produzido pesquisas acadêmicas, debates, palestras, artigos, simpósios, exposições e conteúdo para internet com o objetivo de contribuir para o conhecimento sobre a história e a cultura afro-brasileira e os problemas impostos à população negra no Brasil. Nesta publicação, o segundo livro do NEIAB, persistimos com o mesmo objetivo, apresentando o resultado de pesquisas produzidas em diferentes áreas do conhecimento, fato que mantém o caráter interdisciplinar do Núcleo, por professores da UEM, discentes da graduação e pós-graduação e pesquisadores de outras instituições. Ela é fruto de trabalho acadêmico, da militância no movimento social negro, da luta anti-racista e do desejo de cooperar para que a sociedade brasileira alcance a verdadeira igualdade racial. É preciso registrar que a publicação desse livro não seria possível sem o apoio da Editora da Universidade Estadual de Maringá – EDUEM, do Departamento de Ciências Sociais – DCS, do Programa de Pós-Graduação em Ciências Sociais – PGC e do Centro de Ciências Humanas, Artes e Letras – CCH e dos autores dos artigos que doaram seu tempo e parte do seu conhecimento para colaborar de forma voluntária com essa publicação. Nós, como organizadores desse trabalho, gostaríamos de agradecer a todas as pessoas que participaram de forma direta e indireta para a realização desse livro, que, temos certeza, vai colaborar com os estudos sobre as relações raciais estabelecidas em Maringá e no Brasil. Por fim, gostaríamos de desejar uma ótima leitura a todos e todas.', '["race relations","racial inequality","racial diversity","Afro-Brazilian history and culture","Black population in Brazil","anti-racism","Black social movements","racial equality","Maringá"]', '10.7476/9786586383027', '9788576287292', 'https://books.scielo.org/id/rdfwg', NULL, NULL, 'https://books.scielo.org/id/rdfwg/cover/cover_thumbnail.jpeg', 351, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rdhmv', 'rdhmv', 'Novos mitos e velhas realidades', NULL, '["Caiuby Alves da Costa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro apresenta, de forma sintética e linguagem simples, os 500 anos de história do Brasil: da “nação em construção” às ameaças atuais à nação brasileira (nação em desmonte), propondo, um exemplo para o desenvolvimento que leve à saída do pântano em que a nação adentrou. Caminhando em meio a vários períodos da história brasileira Brasil Colônia, Brasil Império e Brasil República, o livro busca evidenciar o quão recorrente é o domínio da elite encastelada no poder, interrompido por curtos períodos de avanço libertário. Nesse percurso, salienta a ação de brasileiros notáveis, como: José Bonifácio de Andrade e Silva, André Rebouças, Irineu Evangelista de Sousa e outros. Além disso, explicita as lutas constantes travadas ao longo da história do Brasil e a forte contribuição do negro brasileiro. Por fim, analisa as ameaças que pairam sobre a nação em busca da sua construção e apresenta uma proposta exemplo para a retomada do desenvolvimento.', '["Brazilian history","nation-building","colonial Brazil","Brazilian Empire","Brazilian Republic","political power","national development"]', '10.7476/9786556301952', '9786556301952', 'https://books.scielo.org/id/rdhmv', 'https://books.scielo.org/id/rdhmv/pdf/costa-9786556301952.pdf', NULL, 'https://books.scielo.org/id/rdhmv/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rdm32', 'rdm32', 'Amamentação: um híbrido natureza-cultura', NULL, '["João Aprígio Guerra de Almeida"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Amamentar é ''da natureza da mulher''? Então, por que profissionais de saúde, frequentemente, ouvem queixas como ''a mama empedrou'', ''o leite secou''? Este livro tenta responder a todas estas perguntas. O autor vai buscar na história e na sociedade as origens para o paradigma atual da amamentação. Ao considerar a amamentação como um híbrido produzido pela natureza e pela cultura, sugere uma abordagem mais completa do fenômeno. Traz, ainda, um histórico dos bancos de leite humano, ''as amas-de-leite do século XX'', destacando sua importância.', '["breastfeeding","history of breastfeeding","human milk banks","breastfeeding myths","women''s health"]', '10.7476/9788575412503', '9788575412503', 'https://books.scielo.org/id/rdm32', 'https://books.scielo.org/id/rdm32/pdf/almeida-9788575412503.pdf', NULL, 'https://books.scielo.org/id/rdm32/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rdvhy', 'rdvhy', 'Sociedad civil y democracia en América Latina: crisis y reinvención de la política', NULL, '["Bernardo Sorj","Miguel Darcy de Oliveira"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Sociedad Civil y Democracia en América Latina: crisis y reinvención de la política abre un debate urgente y necesa-rio sobre los desafíos que afectan a la gobernabilidad y la consolidación de la democracia en nuestro continente.', '["civil society","democracy","democratic consolidation","governability","political crisis","Latin America","political reinvention"]', '10.7476/9788599662205', '9788599662205', 'https://books.scielo.org/id/rdvhy', 'https://books.scielo.org/id/rdvhy/pdf/sorj-9788599662205.pdf', NULL, 'https://books.scielo.org/id/rdvhy/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rdzxn', 'rdzxn', 'Política de controle do tabaco no Brasil', NULL, '["Leonardo Henriques Pontes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', '(Prêmio Capes de Tese 2018, Área Saúde Coletiva) O livro trata de uma política de saúde considerada uma das mais bem-sucedidas dos últimos trinta anos no Brasil: a Política Nacional de Controle do Tabaco. Nascida no processo de redemocratização do país, nos anos 1980, ela se firmou sobre o arcabouço da Seguridade Social nos anos seguintes. O autor Leonardo Henriques Portes analisa a trajetória e faz um balanço dessa política ao longo de três décadas (1986-2016), marcadas pela implementação e pela consolidação do Sistema Único de Saúde (SUS). Fruto de extenso trabalho de pesquisa, o volume representa uma versão adaptada e atualizada da tese de doutorado do pesquisador, defendida no Programa de Pós-Graduação em Saúde Pública da Escola Nacional de Saúde Pública Sergio Arouca (Ensp/Fiocruz). Em 2018, o trabalho foi o vencedor do Prêmio Capes de Tese, área de Saúde Coletiva.', '["tobacco control","Brazil","health policy history","Unified Health System (SUS)","social security","redemocratization","tobacco control legislation","public health policy"]', '10.7476/9786557080153', '9786557080047', 'https://books.scielo.org/id/rdzxn', NULL, NULL, 'https://books.scielo.org/id/rdzxn/cover/cover_thumbnail.jpeg', 161, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rfdq6', 'rfdq6', 'Obesidade e saúde pública', NULL, '["Luiz Antônio dos Anjos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'APRESENTAÇÃOApesar de aceita sem muita discussão, a obesidade é definida, segundo a Organização Mundial da Saúde (OMS), como uma doença caracterizada pelo excesso de gordura corporal que traz prejuízos à saúde.Na prática clínica e em estudos epidemiológicos, porém, não se mede a gordura corporal e nem se sabe, para todos os efeitos, qual seria o limite de aceitabilidade da quantidade de gordura corporal antes que haja repercussões na saúde.De qualquer forma, a obesidade ocorre num quadro prolongado de ingestão energética maior do que o gasto energético, ou seja, balanço energético positivo.Este livro aborda a obesidade dentro da perspectiva da saúde pública enfocando aspectos do diagnóstico, etiologia, agravos à saúde, epidemiologia e medidas de prevenção, tendo como base, sempre que possível, os dados disponíveis na população brasileira.Inicialmente, discutem-se os métodos usados para o diagnóstico da obesidade, as suas limitações e qual são as alternativas pensadas hoje para a área.Os achados dos principais estudos nacionais e regionais que avaliaram a situação epidemiológica da obesidade no Brasil são discutidos a seguir.As possíveis causas que ajudaram na construção do quadro epidemiológico no Brasil são apresentadas com a integração de dados oriundos de diversas fontes que contribuem para o entendimento da situação de balanço energético positivo na população brasileira.Por fim, discutem-se as alternativas recomenda-', '["obesity","public health","energy balance","obesity diagnosis","obesity epidemiology","obesity etiology","obesity prevention","excess body fat","Brazilian population"]', '10.7476/9788575413449', '9788575413449', 'https://books.scielo.org/id/rfdq6', 'https://books.scielo.org/id/rfdq6/pdf/anjos-9788575413449.pdf', NULL, 'https://books.scielo.org/id/rfdq6/cover/cover_thumbnail.jpeg', NULL, 24, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rfkqk', 'rfkqk', 'Avaliação nos processos educacionais', NULL, '["Rosana Ap. Salvador Rossit","Karin Storani"]', 'Editora Fap-Unifesp', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] A fim de atuar com eficiência e eficácia, é imprescindível que o processo educacional, principalmente o que se realiza na universidade, seja avaliado permanentemente quanto ao desempenho da instituição, bem como quanto ao desenvolvimento da aprendizagem do aluno. Os autores traçam uma retrospectiva da avaliação, percorrendo um longo caminho que vai dos anos de 1930 até hoje. Estabelecem clara distinção entre avaliação formativa e avaliação somativa, explicando seus limites e alcances com exemplos elucidativos. Ressalte-se a contribuição dos autores para enfrentar um fenômeno bastante novo: como avaliar os estudantes quando se trabalha com Educação a Distância? O que dizer sobre o recurso à informática ao longo do processo educacional? Os textos abrangem diferentes áreas do conhecimento: das ciências exatas às ciências da saúde, das ciências humanas às ciências sociais aplicadas.', '["educational assessment","formative assessment","summative assessment","history of assessment","computer-based testing","student learning evaluation","university performance evaluation"]', '10.7476/9788561673550', '9788561673550', 'https://books.scielo.org/id/rfkqk', NULL, NULL, 'https://books.scielo.org/id/rfkqk/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rfv9p', 'rfv9p', 'A política social na América do Sul: perspectivas e desafios no século XXI', NULL, '["Lúcia Cortês da Costa","Vera Maria Ribeiro Nogueira","Vini Rabassa da Silva"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta é uma obra coletiva construída por pesquisadores da área do Serviço Social, Sociologia, Direito e Administração, integrantes de universidades do Brasil, Argentina e Uruguai.Resulta de pesquisas apresentadas e debatidas em dois eventos acadêmicos realizados em 2011, na Universidade Católica de Pelotas: o III SEPOME -Seminário de Política Social no Mercosul 1 e o DIPROSUL -. O direito à saúde e à proteção social em faixas de fronteiras: um debate acadêmico no sul da América do Sul 2 .Após a realização destes eventos, uma profícua continuidade de parceria entre o Mestrado em Política Social/UCPel e o Mestrado em Ciências Sociais Aplicadas/UEPG possibilitou organizar a presente coletânea.Os capítulos que integram essa coletânea abordam, com diferentes perspectivas, o tema da política social no atual contexto de crise do capitalismo.Essa publicação tem o objetivo de contribuir para o debate e socializar o conhecimento produzido a partir das pesquisas acadêmicas sobre a proteção social nos países da América do Sul.', '["social policy","social protection","right to health","Mercosur","crisis of capitalism","South America","social rights"]', '10.7476/9788577982318', '9788577982318', 'https://books.scielo.org/id/rfv9p', 'https://books.scielo.org/id/rfv9p/pdf/costa-9788577982318.pdf', NULL, 'https://books.scielo.org/id/rfv9p/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rfw5c', 'rfw5c', 'Percussão orquestral brasileira: problemas editoriais e interpretativos', NULL, '["Eduardo Flores Gianesella"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Com domínio de conhecimento, Eduardo Flores Gianesella nos oferece, de início, um panorama claro, fidedgno e detalhado do atual campo da percussão orquestral internacional e nacional. Nesse sentido, prepara o leitor para o entendimento das questões e análises que serão propostas nos capítulos seguintes. A partir do tema central – a percussão orquestral brasileira –, o autor analisa as fragilidades de editoração das obras sinfônicas brasileiras, seus problemas interpretativos e as peculiaridades dos instrumentos brasileiros de percussão – em especial do pandeiro. Com uma excelente escolha de registros de partituras (manuscritas ou editadas) dos compositores brasileiros mais expressivos dos século XIX e XX, o autor apresenta soluções para aqueles problemas de editoração e sugestões para as questões interpretativas. Com isso, Gianesella reabre o imenso campo da educação e da pesquisa em musicologia, etnomusicologia e história da música.', '["orchestral percussion","music editing","performance practice","pandeiro","19th-century composers","20th-century composers","percussion instruments","music manuscripts"]', '10.7476/9786557144930', '9786557144930', 'https://books.scielo.org/id/rfw5c', 'https://books.scielo.org/id/rfw5c/pdf/gianesella-9786557144930.pdf', NULL, 'https://books.scielo.org/id/rfw5c/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rg6wf', 'rg6wf', 'Nos domínios do corpo: o saber médico luso-brasileiro no século XVIII', NULL, '["Jean Luiz Neves Abreu"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O corpo, sua anatomia e funções não são algo ‘natural’, mas uma construção do saber médico; e as concepções médicas, por sua vez, estão atreladas ao universo cultural. É a partir desta constatação inicial que o autor desenvolve suas análises. Ele se debruçou sobre antigos tratados de medicina e manuais de prática médica escritos por médicos luso-brasileiros e estrangeiros. A pesquisa revela, entre outros aspectos, as diferentes vertentes do saber médico luso-brasileiro do período: o livro mostra como uma medicina recheada de aspectos mágicos e religiosos passou, sobretudo nas últimas décadas do século XVIII, a ser confrontada por conhecimentos fundamentados no experimentalismo e no racionalismo.', '["medical knowledge","18th century","history of medicine","body","human anatomy","medical treatises","medical manuals","experimentalism","rationalism","cultural construction of the body"]', '10.7476/9788575413401', '9788575412060', 'https://books.scielo.org/id/rg6wf', NULL, NULL, 'https://books.scielo.org/id/rg6wf/cover/cover_thumbnail.jpeg', 220, 23, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rggft', 'rggft', 'Nem pátria, nem patrão! Memória operária, cultura e literatura no Brasil', NULL, '["Francisco Foot Hardman"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Terceira edição revista e ampliada de um livro fundamental para pesquisas na área de história do trabalho e no campo das culturas entre operários. Desenvolve uma discussão crítica das contradições e problemas da existência de uma política cultural anarquista no Brasil. Estuda ainda a presença cultural do proletariado e das correntes libertárias no panorama literário pré-modernista da sociedade brasileira, mostrando os laços orgânicos entre a literatura social e o anarquismo.', '["working-class memory","anarchism","proletarian culture","libertarian movement","social literature","labor history","workers'' literature","Brazil"]', '10.7476/9788539303298', '9788571394308', 'https://books.scielo.org/id/rggft', NULL, NULL, 'https://books.scielo.org/id/rggft/cover/cover_thumbnail.jpeg', 398, 23, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rh4qx', 'rh4qx', 'Reinventando o Estado de bem-estar: plataformas digitais e políticas públicas', NULL, '["Ursula Huws"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '“Desde 2016, fissuras preocupantes abriram-se na classe trabalhadora britânica e entre os partidos políticos que pretendem representar seus interesses. Muitos responderam a essa situação recuando para posições polarizadas ou sucumbindo a formas profundas e paralisantes de depressão que os tornam desesperados ou inativos. Este livro foi escrito para tentar contrariar tais reações, na crença de que, apesar dessas divisões dolorosas, há muito mais coisas que unem as pessoas do que coisas que as dividem.” (Da Introdução)', '["welfare state","digital platforms","public policy","British working class","political polarization","social cohesion"]', '10.7476/9788526816664', '9788526815506', 'https://books.scielo.org/id/rh4qx', NULL, NULL, 'https://books.scielo.org/id/rh4qx/cover/cover_thumbnail.jpeg', 180, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rh9vs', 'rh9vs', 'Regulação econômica no mercado de capitais e na indústria do petróleo e gás natural: assimetrias de informação, cooperação institucional e proteção do investidor', NULL, '["Luiz Felipe Monteiro Seixas"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A presente obra tem como propósito examinar determinados aspectos regulatórios inerentes ao mercado de capitais e à indústria do petróleo e gás brasileira, com especial ênfase na regulação da informação. A principal problemática diz respeito aos desequilíbrios ou assimetrias informacionais existentes entre ambos os mercados (o de capitais e o petrolífero) e como tais assimetrias afetam o desempenho dos órgãos reguladores dos referidos mercados. Para tanto, a obra examina, inicialmente, o regime jurídico do mercado de capitais brasileiro; na sequência, analisa os principais aspectos relacionados à regulação do mercado de capitais; logo após, investiga o regime de divulgação da informação no mercado de capitais, bem como suas consequências para a indústria do petróleo e gás natural; por fim, propõe um modelo de cooperação institucional entre os órgãos reguladores do mercado de capitais (a Comissão da Valores Mobiliários) e da indústria petrolífera (a Agência Nacional do Petróleo, Gás Natural e Biocombustíveis), com a finalidade de reduzir as assimetrias informacionais entre os entes reguladores e aperfeiçoar a regulação entre os referidos mercados.', '["economic regulation","capital markets","oil and gas industry","information asymmetry","investor protection","information disclosure","institutional cooperation","Comissão de Valores Mobiliários","atrial natriuretic peptide","regulatory agencies"]', '10.7476/9786587108650', '9786587108650', 'https://books.scielo.org/id/rh9vs', 'https://books.scielo.org/id/rh9vs/pdf/seixas-9786587108650.pdf', NULL, 'https://books.scielo.org/id/rh9vs/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rj575', 'rj575', 'Identidades políticas porosas: estudios sobre las reivindicaciones sociales nacionales y transnacionales. Movilización legal, discursos políticos y repertorios de acción de las organizaciones indígenas y la lucha contra el racismo en Colombia', NULL, '["Pedro Rojas Oliveros","Monica Natalia Acosta Garcia","Édgar Ricardo Naranjo Peña","Ana Catalina Rodríguez Moreno","Ángela del Pilar Santamaría Chavarro"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2012, '2012-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este libro busca presentar a la comunidad académica nacional e internacional uno de los productos del trabajo de investigación del Observatorio de Redes y Acción Colectiva (ORAC), línea de Acción Colectiva Indígena, donde se plantean diversas tesis y preguntas sobre la (re)definición de identidades políticas y culturales de organizaciones indígenas, de mujeres y de afrocolombianos respecto a temáticas puntuales como el bloqueo del Estado, la instrumentalización del Derecho, los discursos políticos y su relación con contextos de violencia, conflicto, desplazamiento forzado y marginalización. Cada capítulo presenta enfoques, metodologías y construcciones contextuales diferentes; sin embargo, existe un diálogo y unas equivalencias, partiendo de categorías conceptuales, de marcos jurídicos y de la transversalidad de la acción colectiva. Temas como el racismo, el machismo, la violación de los Derechos Humanos y la ejecución autoritaria de políticas por parte del Estado, entre otros, dan cuenta de la complejidad de la (re)significación identitaria y las diversas herramientas emancipatorias (discursos, movilización de recursos, repertorios, alianzas, campañas, etc.) instrumentalizadas por las comunidades, las organizaciones y sus líderes.', '["political identity","indigenous organizations","transnational social movements","legal mobilization","political discourse","repertoires of action","anti-racism","racism","machismo","forced displacement","human rights violations","state repression"]', '10.7476/9789585003958', '9789585003958', 'https://books.scielo.org/id/rj575', 'https://books.scielo.org/id/rj575/pdf/rojas-oliveros-9789585003958.pdf', NULL, 'https://books.scielo.org/id/rj575/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rjfv9', 'rjfv9', 'Economia e movimentos sociais na América Latina', NULL, '["Bernardo Sorj","Fernando Henríque Cardoso","Maurício Front"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro se divide em duas seções. Elas tratam [...] das perspectivas teóricas e metodológicas e de estudos de caso sobre a consolidação sociopolítica do setor exportador. [trecho retirado da Introdução do livro]', '["social movements","economic development","export sector","Latin America","economic theory","case studies"]', '10.7476/9788599662595', '9788599662595', 'https://books.scielo.org/id/rjfv9', 'https://books.scielo.org/id/rjfv9/pdf/sorj-9788599662595.pdf', NULL, 'https://books.scielo.org/id/rjfv9/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rjm72', 'rjm72', 'Teoria da Literatura e História da Crítica: momentos decisivos', NULL, '["Nabil Araújo"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Propõe um olhar sobre temas centrais dos estudos de Teoria da Literatura e da crítica literária, ao mesmo tempo em que permite uma compreensão do desenvolvimento dessas ideias dentro de um contexto historiográfico. Na primeira parte, o autor analisa o clássico Theory of Literature, de René Wellek e Austin Warren, que associou, internacionalmente, o termo “teoria da literatura” à investigação e determinação dos “princípios de crítica”, instituindo a disciplina que leva seu nome como um domínio eminentemente metacrítico. Na segunda parte, iluminam-se questões relativas à historiografia da crítica literária, culminando no advento daquilo que se entende hoje como Theory. As reflexões apresentadas mantém um diálogo com o pensamento filosófico de autores como Kant, Derrida, Nietzsche e Foucault.', '["literary theory","history of literary criticism","metacriticism","historiography of literary criticism","Immanuel Kant","Jacques Derrida","Friedrich Nietzsche","Michel Foucault","philosophy of literature"]', '10.7476/9786500030310', '9786500030266', 'https://books.scielo.org/id/rjm72', NULL, NULL, 'https://books.scielo.org/id/rjm72/cover/cover_thumbnail.jpeg', 390, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rjvhk', 'rjvhk', 'Ciência e Saúde na Terra dos Bandeirantes: a trajetória do Instituto Pasteur de São Paulo no período de 1903-1916', 'a trajetória do Instituto Pasteur de São Paulo no período de 1903-1916', '["Luiz Antônio Teixeira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1995, '1995-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Fundamental contribuição para a história da ciência e das instituições biomédicas no Brasil - apresenta ao leitor cientistas que marcaram época como, por exemplo, o pesquisador Antonio Carini, a quem se deve a descoberta de um parasita causador da pneumonia, denominado Pneumocystis carinii, bastante citado como um microorganismo ''oportunista'' em portadores de HIV. O autor constrói seu objeto a partir de fontes praticamente inexploradas: os arquivos do Instituto Pasteur paulista. Além disso, partindo do objeto empírico, talentosamente formula uma interpretação sedutora e convincente, ao discutir questões de sua pesquisa com base em competentes coleta de dados e manipulação de conceitos.', '["history of science","Pneumocystis carinii","opportunistic infections","HIV","history of medicine"]', '10.7476/9788575412862', '9788585676148', 'https://books.scielo.org/id/rjvhk', 'https://books.scielo.org/id/rjvhk/pdf/teixeira-9788575412862.pdf', NULL, 'https://books.scielo.org/id/rjvhk/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rk6rq', 'rk6rq', 'Colecionismos, práticas de campo e representações', NULL, '["María Margaret Lopes","Alda Heizer"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'As coleções científicas, as práticas de campo, suas representações artístico/científicas, suas relações comerciais ocupam cada vez mais um lugar privilegiado na produção historiográfica internacional. Por toda a América Latina, muitas de suas coleções de objetos, imagens, fotografias, catálogos, textos, periódicos, correspondências reunidas há séculos permanecem a espera das necessárias análises contextuais, temporais, locais que esse livro pretende discutir.', '["scientific collections","field practicum","representation of science","history of science","science exhibitions","science communication","art and science"]', '10.7476/9788578791179', '9788578791179', 'https://books.scielo.org/id/rk6rq', 'https://books.scielo.org/id/rk6rq/pdf/lopes-9788578791179.pdf', NULL, 'https://books.scielo.org/id/rk6rq/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rkfq3', 'rkfq3', 'Ficções do ser: o entre-lugar de bichas pretas na escola', NULL, '["Kauan Almeida"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Partindo da convicção de que é através da educação, que começa no lar e continua na escola, que se forma indivíduos racistas, sexistas e machistas, o autor se debruça em romper esse ciclo. Por meio de questionamentos, reflexões e discussão de conceitos, visando a sensibilização, a conscientização e a politização, de trabalhar a questão dos preconceitos contra homossexuais negros, mostra como executou uma série de aulas-oficina, algumas até sob formas de festas de confraternização entre os semelhantes e os diferentes em um ambiente de ensino formal.', '["Black gay men","prejudice against homosexuals","racism","sexism","machismo","school education","workshops","political education"]', '10.7476/9786586213300', '9786586213300', 'https://books.scielo.org/id/rkfq3', 'https://books.scielo.org/id/rkfq3/pdf/almeida-9786586213300.pdf', NULL, 'https://books.scielo.org/id/rkfq3/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rkr5d', 'rkr5d', 'Linguagem e mente: estudo sobre identidade e percepção', 'estudo sobre identidade e percepção', '["Derócio Felipe Perondi Meotti","Flávio Miguel de Oliveira Zimmermann","Newton M. Peron","Bruno Ramos Mendonça","Arturo Fatturi"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro trata de temas relacionados tanto à filosofia da linguagem quanto à filosofia da mente. Com relação à linguagem, alguns capítulos tratarão das relações entre os conceitos de identidade, necessidade, definições, descrições definidas, assim como sobre o modo como podemos pensar esses e outros problemas por meio de noções como designadores rígidos e seguir regras. Do lado da filosofia da mente, por sua vez, o leque também se desdobra em discussões relativas à mente, percepção e identidade pessoal. Nesses capítulos, o leitor encontrará discussões acerca de temas relacionados à intencionalidade, atitudes proposicionais, percepção e conteúdo proposicional, além de reflexões sobre o modo como podemos conceber as relações entre a mente e a constituição de objetos. Apesar da grande diversidade de perspectivas sobre esses temas, é possível notar a recorrência de algumas teses entre os capítulos, que por vezes possuem pontos de partida filosóficos e metodológicos completamente diferentes. "Linguagem e mente: estudos sobre identidade e percepção" resulta de pesquisas dos membros do Grupo de Pesquisa em Lógica, Linguagem e Conhecimento da UFFS, tendo participantes do PPGFIL da UFFS e da UFSC.', '["philosophy of language","philosophy of mind","identity","perception","personal identity","rigid designation","rule-following","necessity","definitions","description","intentionality","propositional attitudes"]', '10.7476/9786550191115', '9786550191122', 'https://books.scielo.org/id/rkr5d', 'https://books.scielo.org/id/rkr5d/pdf/meotti-9786550191115.pdf', NULL, 'https://books.scielo.org/id/rkr5d/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rm5gc', 'rm5gc', 'Implementación del acuerdo de paz en Colombia 2016-2017: desafíos, avances y propuestas', NULL, '["Londoño Toro, Beatriz","Peralta González, Laly Catalina"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2018, '2018-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este Boletín presenta la sistematización de las conclusiones más relevantes del Simposio Alianzas y Redes Regionales en la Implementación del Acuerdo Final, evento propuesto por la Universidad del Rosario y la Fundación Hanns Seidel para permitir el debate y diálogo constructivo entre actores institucionales, sociales y académicos de diversas regiones del país. La metodología utilizada en las mesas de trabajo, permitió sintetizar los aportes y publicarlos como insumo para futuros trabajos de investigación y seguimiento del Acuerdo de Paz con las FARC. El trabajo aborda cuatro temas: i) las voces de las víctimas, ii) reforma de tierras, iii) participación política para construir la paz, y iv) reincorporación y fin del conflicto. Las conclusiones del trabajo coinciden con los informes internacionales, al señalar como prioritarias las medidas para la protección y seguridad en los territorios, el proceso de reincorporación de los excombatientes, y la operación exitosa de la Jurisdicción Especial para la Paz (JEP).', '["Colombian peace agreement","FARC","peace agreement implementation","victims'' voices","land reform","Special Jurisdiction for Peace","victim protection","Colombian armed conflict"]', '10.7476/9789587840582', '9789587840582', 'https://books.scielo.org/id/rm5gc', 'https://books.scielo.org/id/rm5gc/pdf/londono-9789587840582.pdf', NULL, 'https://books.scielo.org/id/rm5gc/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rmgfg', 'rmgfg', 'O romance policial místico-religioso: um subgênero de sucesso', NULL, '["Fernanda Massi"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"Desde o século XIX, com o célebre detetive Auguste Dupin, de Edgar Allan Poe, e a extensa cadeia de personagens e narrativas de mistério que em maior ou menor medida descenderam dali – passamos, nesse prolífico percurso, por Conan Doyle, Agatha Christie, Raymond Chandler, só para citar alguns autores –, o gênero policial foi se consolidando e, enquanto expandia progressivamente seu público, matizava-se e assumia novas formas.Este estudo, fruto de longa pesquisa a partir dos livros mais vendidos no Brasil no início do século XXI, debruça-se sobre o romance policial “místico-religioso”, subgênero definido por Fernanda Massi que se distancia um pouco das características tradicionais do romance policial: nessas tramas, o crime se conecta a um segredo ligado a um núcleo místico-religioso, em geral protegido por uma sociedade fechada e secreta às voltas com o que ela supõe ser um inimigo ameaçador. O repórter/investigador (que em tais obras nunca é chamado de detetive) busca uma verdade que supera a identificação do criminoso, tendo como alvo principal o segredo motivador dos crimes. Outra característica singular é a tentativa, quase frequente, de desmoralização da Igreja Católica. Isto ocorre através da oposição /ocultação/ vs. /revelação/ de um segredo, fazendo que esse subgênero tenha grande sucesso de público, uma vez que promete revelações surpreendentes sobre essa poderosa instituição."', '["police fiction","subgenres","bestsellers","secret societies","Catholic Church","mystery fiction","Brazilian literature","21st century"]', '10.7476/9788568334560', '9788568334560', 'https://books.scielo.org/id/rmgfg', 'https://books.scielo.org/id/rmgfg/pdf/massi-9788568334560.pdf', NULL, 'https://books.scielo.org/id/rmgfg/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rmjnz', 'rmjnz', 'Linguística e ensino de línguas', NULL, '["Lúcia Maria Pinheiro Lobato"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Sem mistificar o papel da linguística, Lúcia Lobato argumenta a favor das contribuições efetivas que a ciência que estuda a linguagem pode prestar ao ensino. Seguindo orientações modernas dessa ciência, o ensino de língua portuguesa- para Lobato – tem de deixar de ser prescritivo ser descritivo e produtivo.', '["linguistics and language teaching","Portuguese language teaching"]', '10.7476/9788523013462', '9788523011635', 'https://books.scielo.org/id/rmjnz', NULL, NULL, 'https://books.scielo.org/id/rmjnz/cover/cover_thumbnail.jpeg', 56, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rmmbk', 'rmmbk', 'Salud y equidad: una mirada desde las ciencias sociales', NULL, '["Roberto Briceño‐León","Maria Cecília de Souza Minayo","Carlos Ε. A. Coimbra"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A saúde da população mundial tem melhorado, porém, apesar do impressionante avanço tecnológico, ainda há graves problemas a superar - entre estes, o maior talvez seja a desigualdade. Diante de tal realidade, o tema da ''eqüidade em saúde'' mostra-se de extrema relevância, uma vez que trata-se de assunto que merece os enfoques político, econômico, social e cultural. Esta coletânea é produto de diversas investigações levadas a cabo por seus autores (reunidos durante o V Congresso Latino-Americano de Ciências Sociais e Medicina, na Venezuela) e pretende, sobretudo, ser uma contribuição para o sonho de construir uma sociedade mais eqüitativa, a partir da melhor compreensão dos determinantes sociais da saúde.', '["health equity","social determinants of health","health disparities","social justice","social sciences and health","health policy"]', '10.7476/9788575415122', '9788575415122', 'https://books.scielo.org/id/rmmbk', 'https://books.scielo.org/id/rmmbk/pdf/briceno-9788575415122.pdf', NULL, 'https://books.scielo.org/id/rmmbk/cover/cover_thumbnail.jpeg', NULL, 63, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rmyd2', 'rmyd2', 'Comentários sobre a primeira década de Tito Lívio', NULL, '["Nicolau Maquiavel"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Em ‘Comentários sobre a primeira década de Tito Lívio’, Maquiavel brinda o leitor com a história de Roma, discorrendo sobre a sua política, suas divergências e seus conflitos. A obra escrita entre 1513 e 1517, cujo título original é Discorsi, é uma digressão sobre os dez primeiros livros do historiador romano Tito Lívio. Maquiavel não se preocupa em fundamentar afirmativas ou documentar suas referências. Em vez disso, identifica no passado acontecimentos ou sequências de eventos que ilustrem e confirmem suas convicções acerca do presente, em especial a política a ser seguida pelas cidades italianas.', '["Niccolò Machiavelli","Discourses on Livy","Livy''s Ab Urbe Condita","Roman history","Roman political institutions","Italian city-states","political philosophy"]', '10.7476/9786558461609', '9788523012380', 'https://books.scielo.org/id/rmyd2', NULL, NULL, 'https://books.scielo.org/id/rmyd2/cover/cover_thumbnail.jpeg', 440, 25, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rnn6q', 'rnn6q', 'Filosofia, história e sociologia das ciências I: abordagens contemporâneas', 'abordagens contemporâneas', '["Vera Portocarrero"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1994, '1994-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Coletânea preciosa não somente para os especialistas, mas para todo aquele que pretende se iniciar na pesquisa e se interrogar sobre a natureza da ciência, seus desafios e seus problemas fundamentais. A obra reúne diversos especialistas do Brasil e da França na busca de contemplar as "diversas vertentes de pensamento que constituem a fundamentação do atual debate sobre as ciências", em artigos que questionam as relações das ciências, das técnicas e da sociedade, não de um ponto de vista estritamente "positivista" ou "dogmático", mas com enfoque histórico-crítico. E mais: são respeitadas as diferentes perspectivas dos autores, mesmo as conflitantes, por considerar esta ótica não uma contradição, mas uma riqueza a ser oferecida aos leitores.', '["philosophy of science","history of science","sociology of science","nature of science","science and society","science and technology","positivism"]', '10.7476/9788575414095', '9788585676025', 'https://books.scielo.org/id/rnn6q', 'https://books.scielo.org/id/rnn6q/pdf/portocarrero-9788575414095.pdf', NULL, 'https://books.scielo.org/id/rnn6q/cover/cover_thumbnail.jpeg', NULL, 17, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rnr64', 'rnr64', 'As experiências de República no município de Franca (1880-1906)', NULL, '["Anderson Luis Camelucci"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, Anderson Luis Camelucci procura caracterizar as especificidades da propaganda republicana no município de Franca, procurando evidenciar como as características do repu­blicanismo local contribuíram para moldar as experiências de República nesse período. O autor realiza uma discussão sobre as relações e/ou as linhas de ação política traçadas pelos partidos políticos constituídos no município e esboça o perfil político da elite dirigente de Franca na última década do Império, a fim de avaliar tanto o “terreno” político em que a propaganda republicana se desenvolveu no município, como a adesão dos políticos locais ao novo regime. Camelucci demonstra também como grupos “marginalizados” e “dissidentes” da política local, por intermédio dos jornais Tribuna da Franca e Cidade da Franca, criticaram o “modelo” de República então vigente, e em quais momentos a imprensa local, principal­mente o jornal O Francano, saiu em “defesa” desse regime.', '["republican propaganda","republicanism","Franca, São Paulo","Brazilian Empire","local political parties","political elites","local newspapers","political dissent","transition to republic"]', '10.7476/9786557145166', '9786557145166', 'https://books.scielo.org/id/rnr64', 'https://books.scielo.org/id/rnr64/pdf/camelucci-9786557145166.pdf', NULL, 'https://books.scielo.org/id/rnr64/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rnvj3', 'rnvj3', 'A reforma psiquiátrica', NULL, '["Manuel Desviat"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Versão atualizada da edição espanhola, apresenta e analisa alguns dos mais significativos processos de transformação internacionais em saúde mental, entre os quais está o processo brasileiro. O atual contexto, afirma o autor, tem acentuado medidas políticas e econômicas que enchem de incerteza o futuro dos serviços sanitários e sociais: a globalização da economia, as mudanças nos modos de produção, a precaridade do emprego e o aumento planetário da exclusão social, o que faz interrogar sobre a continuidade dos movimentos solidários iniciados depois da devastação da Segunda Guerra Mundial. Assim, na edição brasileira, além de atualizar temas, Manuel Desviat procura dar conta das repercussões dessas políticas na saúde mental e em suas instituições. "Esta segunda edição incorpora novas reflexões que Desviat vem recolhendo nos últimos anos em suas recorrentes viagens a todos os cantos da Espanha, assim como a vários países do mundo. A partir dessas reflexões e advertências, nas quais podemos tomar conhecimento da importância da sustentabilidade do modelo psiquiátrico contra-hegemônico, temos acesso a elementos importantes que podem nos ajudar a evitar os mesmos problemas pelos quais a Espanha e outros países passam. Se este livro já era atual, o é ainda mais com o novo posfácio sobre a resitência à contrarreforma e sobre novas estratégias para o futuro", avalia Paulo Amarante, editor responsável pela coleção Loucura & Civilização.', '["psychiatric reform","mental health policy","deinstitutionalization","social exclusion","precarity","globalization","health and social services","Brazil"]', '10.7476/9788575415436', '9788575414675', 'https://books.scielo.org/id/rnvj3', 'https://books.scielo.org/id/rnvj3/pdf/desviat-9788575415436.pdf', NULL, 'https://books.scielo.org/id/rnvj3/cover/cover_thumbnail.jpeg', NULL, 64, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rp5kq', 'rp5kq', 'Ensaios fora do tubo: a saúde e seus paradoxos', NULL, '["Luís David Castiel"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-12-06', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Tempos distópicos pedem textos corajosos e muitas vezes academicamente inconvenientes. Se seu livro pode fazer surgir um sorriso de canto de boca nos pares, ele também serve como uma escrita-molotov a ser usada na guerrilha científica. Isso porque ele aposta que a melhor proposição, a melhor solução, é o exercício da crítica. Sabe a mania que temos de construir nossos artigos com aquele trecho que precisa responder à pergunta: “Ah, tá! Mas o que você propõe no lugar disso que você está criticando?”. Esta obra nos põe a pensar se o ponto de partida epistemológico dessa pergunta talvez devesse ser outro...', '["health","critique","scientific writing","epistemology","health paradox"]', '10.7476/9786557081556', '9786557080474', 'https://books.scielo.org/id/rp5kq', NULL, NULL, 'https://books.scielo.org/id/rp5kq/cover/cover_thumbnail.jpeg', 309, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rp6gk', 'rp6gk', 'Educação Inclusiva, deficiência e contexto social: questões contemporâneas', NULL, '["Félix Díaz","Miguel Ángel García Bordas","Nelma de Cássia Silva Sandes Galvão","Theresinha Guimarães Miranda"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O enfoque desta obra decorre da relevância que o contexto sociocultural em que a pessoa está inserida serve de parâmetro para classificá-la como normal e anormal, além de enfatizar o ensino e a escola, bem como as formas e condições de aprendizado. Esta perspectiva, ao invés de procurar no aluno a origem de um problema, define o tipo de resposta educativa e de recursos e apoios que a escola deve proporcionar a esse aluno para que ele obtenha o sucesso escolar.', '["inclusive education","disability","sociocultural context","school success","learning conditions","educational support","students with disabilities"]', '10.7476/9788523209285', '9788523209285', 'https://books.scielo.org/id/rp6gk', 'https://books.scielo.org/id/rp6gk/pdf/diaz-9788523209285.pdf', NULL, 'https://books.scielo.org/id/rp6gk/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rpcd9', 'rpcd9', 'Pensamentos selvagens: montagem de uma outra herança v. 2', NULL, '["Paola Berenstein Jacques"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'O livro recebeu MENÇÃO HONROSA na modalidade LIVRO AUTORAL do Prêmio ANPATQ 2022. No primeiro volume da Montagem de uma outra herança foi evocado o esboço de uma outra herança moderna, em particular no campo do urbanismo, como um caleidoscópio montado por fragmentos e ruínas. Evidenciou-se que uma herança, qualquer herança, é sempre uma construção, uma montagem. Dando continuidade a este sentido, o segundo volume faz apologia ao movimento, às viagens, ao nomadismo entendido como deslocamentos sucessivos de variações do tema, de tempos coexistentes, heterogêneos ou anacrônicos. Reivindica-se também outra herança “vencida”, mas ainda latente, nossa herança selvagem ou antropófaga, buscando mostrar que esta herança do pensamento em estado selvagem está diretamente relacionada com a outra herança moderna, crítica e impura, já explorada anteriormente.', '["urbanism","heritage","montage","nomadism","travel","movement","anachronism","cannibalism","wild thought","modernity","ruins"]', '10.7476/9786556304267', '9786556304267', 'https://books.scielo.org/id/rpcd9', 'https://books.scielo.org/id/rpcd9/pdf/jacques-9786556304267.pdf', NULL, 'https://books.scielo.org/id/rpcd9/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rpnxv', 'rpnxv', 'A revolução das mochilas: contracultura e viagens no Brasil ditatorial', NULL, '["Leon Kaminski"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro assinala a resistência contracultural de jovens brasileiros da década de 1970, durante os anos de chumbo da ditadura civil-militar brasileira, cuja revolução consistia em sair Brasil afora com uma mochila às costas. Pelos caminhos e descaminhos de uma jornada sem rumo estabelecido, tais sujeitos – alguns, hippies – criaram uma maneira própria de se opor ao sistema repressivo tanto comportamental quanto politicamente. Fruto de uma densa e elaborada pesquisa historiográfica, este livro consiste em importante contribuição para os estudos sobre o período ditatorial brasileiro, recuperando experiências, memórias e narrativas até então ausentes nas pesquisas sobre esse traumático passado.', '["counterculture","Brazilian military dictatorship","1970s","youth resistance","backpacking","travel","hippies","political repression","memory","personal narrative","Brazil"]', '10.7476/9786558581123', '9786558580775', 'https://books.scielo.org/id/rpnxv', NULL, NULL, 'https://books.scielo.org/id/rpnxv/cover/cover_thumbnail.jpeg', 361, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rpy48', 'rpy48', 'Educação do campo: políticas e práticas', NULL, '["Arlete Ramos dos Santos","Silva, Geovani de Jesus","Júlia Maria da Silva Oliveira","Lívia Andrade Coelho"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Nesse volume, foram selecionados textos, cujo objetivo principal é promover e aprofundar o debate das temáticas que se entrecruzam nas relações dos movimentos sociais do campo e da cidade com a educação, oferecendo aos professores do ensino superior, gestores, estudantes, militantes de movimentos sociais e profissionais da educação básica uma opção de leitura sobre a temática.', '["rural education","education policy","social movements","urban-rural relations","social movements and education","education practice"]', '10.7476/9786586213201', '9786586213201', 'https://books.scielo.org/id/rpy48', 'https://books.scielo.org/id/rpy48/pdf/santos-9786586213201.pdf', NULL, 'https://books.scielo.org/id/rpy48/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rq', 'rq', 'O tutu da Bahia: transição conservadora e formação da nação, 1838-1850', NULL, '["Dilton Oliveira de Araújo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Desvendar aspectos obscuros da história política da bahia e do brasil, entre 1838 e 1850, período em que a nação brasileira adquiria seus contornos definitivos, baldados os esforços dos rebeldes para fazer valer as suas propostas de organização política e de reformas econômicas e sociais. ao final da década de 1830, os rebeldes baianos sofreram uma grave derrota das forças oficiais, tendo início uma fase que, apesar de não ter sido marcada pela ocorrência de novas rebeliões, caracterizou-se pela atuação continuada de uma imprensa democrática e republicana, e pelas constantes ameaças de conflagração que, diversamente do período anterior, não encontraram o ambiente político propício para a sua plena manifestação, mas provocaram temores que se constituíram em componente importante da realidade política, social e cultural do período.', '["Bahia","nation-building","Brazilian political history","democratic press","republican press","political reform","economic and social reform","political crisis"]', '10.7476/9788523208769', '9788523208769', 'https://books.scielo.org/id/rq', 'https://books.scielo.org/id/rq/pdf/araujo-9788523208769.pdf', NULL, 'https://books.scielo.org/id/rq/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rqhtt', 'rqhtt', 'Quando a vida começa diferente: o bebê e sua família na UTI neonatal', NULL, '["Maria Elisabeth Lopes Moreira","Nina de Almeida Braga","Denise Streit Morsch"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'inteligíveis e, por conseguinte, menos ameaçadores.É muito provável que não tenhamos respondido a todas as dúvidas, mesmo porque algumas delas são singulares, próprias da história de cada criança e de seu grupo familiar.A par disso, optamos por uma escrita sem muitas referências às teorias a partir das quais foram e são construídas nossas práticas profissionais.A adoção de uma forma de comunicação mais coloquial tem o intuito de facilitar aos usuários dos serviços intensivistas neonatais a assimilação deste livro como se ele fosse um guia de viagem: capaz de orientar os que se aventuram -ainda que a contragosto -por um universo pouco conhecido.Pode ser que alguns leitores considerem essa escolha uma falha.Porém, antes de tudo, queríamos transformar este texto em ferramenta a ser manuseada de acordo com as necessidades de quem sofreu ou sofre o dissabor de ter de enfrentar um período pleno de obstáculos como o da internação de um bebê em uma UTI.Pretendemos, assim, preencher uma lacuna, uma vez que se trata da primeira publicação em nosso país com esse propósito.Este livro contém informações específicas da assistência oferecida no Brasil, seja a disponível em hospitais públicos, seja a encontrada em clínicas particulares.Esperamos que, ao término da leitura destas páginas, nosso público experimente alguma sensação de alívio, transformando as informações apresentadas em sinais aptos a orientá-lo nesta travessia.', '["neonatal intensive care unit","preterm infants","neonatal intensive care","neonatal care","parental guidance"]', '10.7476/9788575413579', '9788575413579', 'https://books.scielo.org/id/rqhtt', 'https://books.scielo.org/id/rqhtt/pdf/moreira-9788575413579.pdf', NULL, 'https://books.scielo.org/id/rqhtt/cover/cover_thumbnail.jpeg', NULL, 46, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rqm7z', 'rqm7z', 'Formação interprofissional em saúde: caminhos possíveis', 'caminhos possíveis', '["Tatiane de Oliveira Silva Alencar","Jamilly de Oliveira Musse","Claudia Cerqueira Graça Carneiro"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Desejamos que as experiências, pesquisas e relatos sistematizados neste livro, a partir do trabalho desenvolvido no PET-Saúde Inter-profissionalidade (2019-2021), sejam úteis para novas investigações e para fomentar reflexões e questionamentos que venham qualificar a formação dos futuros profissionais e a prática nos serviços de saúde. Ademais, esperamos que este livro reitere o papel da universidade enquanto protagonista dos processos de mudança na sociedade e da constituição de novos sujeitos.', '["interprofessional education","health professions education","professional training"]', '10.7476/9788555921711', '9786589524557', 'https://books.scielo.org/id/rqm7z', NULL, NULL, 'https://books.scielo.org/id/rqm7z/cover/cover_thumbnail.jpeg', 184, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rqvz2', 'rqvz2', 'El turismo gastronómico sostenible. Ruta Bochica: potencialidades y modelo pedagógico para su desarrollo en Colombia', NULL, '["Royer Gutiérrez-Quecano"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Recordando las palabras de uno de los personajes más internacionales en cuanto a gastronomía se refiere, Ferrán Adriá “No puedes tener una influencia de la cocina de un país si no la entiendes. Y para entenderla, tienes que estudiarla”. Y eso, es lo que han hecho los autores analizando con detalle un modelo de turismo gastronómico sostenible para la región Andina colombiana (subregión cundiboyacense) manifestado principalmente en un producto turístico (ruta gastronómica) compuesta a su vez por tours, anillos y recorridos turísticos en el eje vial que pasa por los municipios de Ventaquemada, Tunja, Sotáquira, Villa de Leyva y Sutamarchán', '["gastronomic routes","tourism product development","teaching model","Andean region","Cundinamarca","Ventaquemada","Villa de Leyva","Tunja","culinary heritage","rural tourism"]', '10.7476/9786289558272', '9786289558272', 'https://books.scielo.org/id/rqvz2', 'https://books.scielo.org/id/rqvz2/pdf/gutierrez-9786289558272.pdf', NULL, 'https://books.scielo.org/id/rqvz2/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rqx5f', 'rqx5f', 'Ordem, poder e conflito no séc. XXI: esse mesmo mundo é possível', NULL, '["Luís Fernando Ayerbe"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro tem por "abordar o processo de configuração da hegemonia dos Estados Unidos no âmbito internacional e na América Latina em particular, estabelecendo um contraponto com as possibilidades de construção de alternativas originárias de setores subalternos na estrutura social ou de países periféricos no sistema internacional". "A preocupação é buscar respostas ao desafio colocado por essa visão determinista da realidade, confrontando diversas perspectivas sobre a viabilidade estratégica da unipolaridade nas relações internacionais e do capitalismo nas relações sociais. Nossa conclusão é cautelosa no que se refere à grande questão que aviva os movimentos críticos do sistema: a continuidade dos fundamentos essenciais da atual estrutura de poder apresenta-se como cenário provável. Não por um destino manifesto que se impõe a nenhum desejo de transformação, mas pela cristalização de um consenso sobre os alcances e limites da mudança possível, que se denomina social-democratização do ordenamento mundial, para o qual confluem os atores principais da cena política e econômica governamental e não-governamental, incluindo boa parte dos descontentes com a chamada globalização neoliberal".', '["US hegemony","unipolarity","Latin America","subaltern groups","peripheral countries","international system","social democracy","neoliberal globalization","power structures","social conflict","alternatives to capitalism","21st century"]', '10.7476/9788539303328', '9788571396937', 'https://books.scielo.org/id/rqx5f', NULL, NULL, 'https://books.scielo.org/id/rqx5f/cover/cover_thumbnail.jpeg', 312, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rr42h', 'rr42h', 'O corpo das mulheres em Chiquinha Gonzaga: entre regularidades, rupturas e discursos de resistência', NULL, '["Eliane Regina Crestani Tortola"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro apresenta análises da construção discursiva acerca do corpo das mulheres em obras musicais de Chiquinha Gonzaga e identifica regularidades, rupturas e discursos de resistência resultantes de objetivações do feminino. A imersão em suas obra provoca o retorno ao passado para reatualizar, a partir dos estudos discursivos foucaultianos, o discurso acerca do entendimento do que é ser mulher hoje e de como seu corpo foi e é objetivado em tempos históricos diferentes.', '["Chiquinha Gonzaga","female body","representation of women in music","objectification of the female body","resistance discourse","discursive construction","Foucauldian discourse analysis","gender and music","women composers"]', '10.7476/9786587626154', '9786586383720', 'https://books.scielo.org/id/rr42h', NULL, NULL, 'https://books.scielo.org/id/rr42h/cover/cover_thumbnail.jpeg', 206, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rr6s4', 'rr6s4', 'A Liberdade na República dos modernos: teoria e história do liberalismo político francês (1789-1848)', NULL, '["Paulo Henrique Paschoeto Cassimiro"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Estuda o pensamento político na França, em um período crucial para a sociedade, compreendido entre a revolução de 1789 e a restauração, concluída em 1848 com a revolução de 22 de fevereiro. O autor discute a constituição de uma linguagem política liberal e de conceitos como república, democracia, soberania, liberdade, opinião pública e sociedade civil. Com este objetivo, analisa o pensamento político vigente, de intelectuais como Madame de Staël, Benjamin Constant, François Guizot, Visconde de Chateaubriand e Alexis de Tocqueville. O livro explicita pontos de consenso ou desacordo desses intérpretes da vida política e suscita reflexões sobre uma grande transformação operada na modernidade, com o aprofundamento do protagonismo do indivíduo na lógica de constituição do corpo político. É no interior desse conflito entre o social e o político que se distinguirá a experiência política que começa a tomar forma com a Revolução Francesa.', '["French liberalism","political thought","French Revolution","1848 revolution","republicanism","democracy","sovereignty","freedom","public opinion","civil society","Madame de Staël","Benjamin Constant"]', '10.7476/9788575115077', '9788575115060', 'https://books.scielo.org/id/rr6s4', NULL, NULL, 'https://books.scielo.org/id/rr6s4/cover/cover_thumbnail.jpeg', 372, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rrm7q', 'rrm7q', 'Uma ecologia política dos riscos: princípios para integrarmos o local e o global na promoção da saúde e da justiça ambiental', NULL, '["Marcelo Firpo de Souza Porto"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro tem por objetivo integrar as discussões sobre sustentabilidade, promoção da saúde e justiça ambiental, apresentando uma proposta de análise integrada e contextualizada dos riscos ambientais decorrentes do desenvolvimento econômico e tecnológico, particularmente em países e territórios com desigualdades e vulnerabilidades sociais.', '["political ecology","environmental risk","health promotion","environmental justice","sustainability","global-local integration","social inequality","social vulnerability","economic and technological development"]', '10.7476/9788575413777', '9788575411308', 'https://books.scielo.org/id/rrm7q', NULL, NULL, 'https://books.scielo.org/id/rrm7q/cover/cover_thumbnail.jpeg', 248, 46, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rrr8x', 'rrr8x', 'Poesia e pensamento em Hölderlin e Heidegger', NULL, '["Marco Aurélio Werle"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Leitura fundamental para todos os que se interessam pelo diálogo e convívio entre filosofia e poesia, este ensaio examina as relações entre o pensamento do filósofo Martin Heidegger e a poesia de Friedrich Hölderlin. O autor apresenta a noção de poesia nos textos do filósofo e como a noção de linguagem e de poesia são entendidas como lugar privilegiado de manifestação do ser.', '["Friedrich Hölderlin","Martin Heidegger","poetry and philosophy","concept of poetry","language","Hölderlin''s poetry","Heidegger''s philosophy"]', '10.7476/9788539303373', '9788571395855', 'https://books.scielo.org/id/rrr8x', NULL, NULL, 'https://books.scielo.org/id/rrr8x/cover/cover_thumbnail.jpeg', 212, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rrtr9', 'rrtr9', 'Favelados e pobladores nas ciências sociais: a construção teórica de um movimento social', NULL, '["Alexis Cortés"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Favelados e pobaldores nas ciências sociais : a construção teórica de um movimento social / Alexis Cortés.', '["favela residents","social movements","theoretical construction","social sciences","urban periphery"]', '10.7476/9788575114773', '9788575114773', 'https://books.scielo.org/id/rrtr9', 'https://books.scielo.org/id/rrtr9/pdf/cortes-9788575114773.pdf', NULL, 'https://books.scielo.org/id/rrtr9/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rrw5w', 'rrw5w', 'Epidemiologia nutricional', NULL, '["Gilberto Kac","Rosely Sichieri","Denise Petrucci Gigante"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Nesta coletânea de fôlego, os organizadores e autores oferecem uma poderosa ferramenta de trabalho aos pesquisadores e interessados na epidemiologia nutricional brasileira. Ampliando os horizontes tradicionais desse campo de estudo, o livro vai além de avaliação de dietas e da relação entre alimentação e doenças crônicas não transmissíveis. Os 38 capítulos desta segunda edição revista e ampliada contemplam métodos e análises que abrangem antigos e atuais problemas nutricionais brasileiros, com engajamento propositivo na solução de problemas. Simultaneamente, manual técnico da complexa área da avaliação nutricional e rigorosa enciclopédia nutricional brasileira, este compêndio de enfoque amplo e multidisciplinar reúne os principais investigadores na área de nutrição e saúde pública no Brasil e surge como leitura fundamental para os estudos de nutrição e saúde coletiva.', '["nutritional epidemiology","public health nutrition","malnutrition","early weaning","micronutrient deficiency","nutritional assessment","nutrition and health"]', '10.7476/9788575413203', '9788575413203', 'https://books.scielo.org/id/rrw5w', 'https://books.scielo.org/id/rrw5w/pdf/kac-9788575413203.pdf', NULL, 'https://books.scielo.org/id/rrw5w/cover/cover_thumbnail.jpeg', NULL, 54, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rrwrz', 'rrwrz', 'Justiça e cidadania no Brasil', NULL, '["Maria Tereza Sadek","Alvino Sanches Filho","Guita Grin Debert","Luciana Gross Cunha","Rogério Bastos Arantes","Rosângela Batista Cavalcanti"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[...] primeiramente descreveremos o perfil da instituição; em seguida, relataremos algumas experiências e, por fim, serão discutidas algumas questões relacionadas à relação entre o Ministério Público e a cidadania.', '["public prosecutor''s office","Public Ministry","citizenship","justice","Brazil"]', '10.7476/9788579820175', '9788579820175', 'https://books.scielo.org/id/rrwrz', 'https://books.scielo.org/id/rrwrz/pdf/sanches-9788579820175.pdf', NULL, 'https://books.scielo.org/id/rrwrz/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rs684', 'rs684', 'Brasil Saúde Amanhã: dimensões para o planejamento da atenção à saúde', NULL, '["José Carvalho de Noronha","Lima, Luciana Dias de","Adolfo H Chorny","Mário Roberto Dal Poz","Paulo Elson Fernandes Gadelha"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', '“Este livro reúne trabalhos desenvolvidos sobre os temas relacionados às projeções do perfil epidemiológico do país e a organização e gestão dos serviços de saúde, com o objetivo de apoiar o planejamento e a prospecção estratégica do sistema de saúde em âmbito nacional. A abordagem de prospecção estratégica adotada pela iniciativa Brasil Saúde Amanhã pretende expandir a capacidade de compreensão em relação a temas e situações emergentes fundamentais para o planejamento em saúde de médio e longo prazo. Para tanto, integra perspectivas, procedimentos e ferramentas das pesquisas de tendências e dos estudos de futuro. […] Em síntese, o livro oferece um conjunto diversificado de informações, todas de suma relevância para o planejamento nacional em saúde. Esperamos que ele possa contribuir para o debate acerca das mudanças, tendências e desafios para as políticas de saúde nas próximas décadas e para a proposição de alternativas que busquem o fortalecimento do sistema público de saúde no Brasil.”', '["health system planning","strategic foresight","epidemic projection","health care organization","health management","public health policy","health system strengthening","Brazil"]', '10.7476/9786557080900', '9786557080900', 'https://books.scielo.org/id/rs684', 'https://books.scielo.org/id/rs684/pdf/noronha-9786557080900.pdf', NULL, 'https://books.scielo.org/id/rs684/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rsjcq', 'rsjcq', 'O Brasil entre a américa e a europa: o império e o interamericanismo (do congresso do Panamá à conferência de Washington)', NULL, '["Luís Cláudio Villafañe G. Santos"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Obra que, sem dúvida, fornece elementos para a definição da identidade brasileira e exibe os precedentes da crítica agenda estratégica e comercial do Brasil contemporâneo com a América e a Europa. Aborda a política do Império brasileiro ante os sucessivos encontros interamericanos realizados no século XIX, desde o primeiro, no Panamá, em 1826, até o de Washington, em 1889/1890 (chamado de Primeira Conferência Internacional Americana, convocada pelos Estados Unidos, já sob a bandeira do pan-americanismo) - o único do qual o Brasil participou. A política externa do Império somente se consolida a partir de 1850, quando posições nos principais temas da agenda brasileira passam a ser definidas por políticas coerentes. Isolado nas Américas como único defensor do princípio monárquico, o Estado brasileiro sente-se desvinculado dos países vizinhos na construção de um discurso legitimador para a constituição do que acreditava ser um bastião da civilização européia no continente.', '["Brazilian Empire","inter-Americanism","Pan-Americanism","Brazilian foreign policy","Washington Conference","Brazilian national identity","monarchy","European civilization","19th-century international relations","Brazil–Europe relations","Brazil–Latin America relations"]', '10.7476/9788539302864', '9788571395299', 'https://books.scielo.org/id/rsjcq', NULL, NULL, 'https://books.scielo.org/id/rsjcq/cover/cover_thumbnail.jpeg', 159, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rsxsr', 'rsxsr', 'Questões sociocientíficas sob o enfoque: ciência, tecnologia, sociedade e ambiente e a pedagogia freiriana: diálogos na formação de professores', 'ciência, tecnologia, sociedade e ambiente e a pedagogia freiriana: diálogos na formação de professores', '["Maria Aparecida da Silva Andrade"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Ao discutir os desafios contemporâneos da formação docente, este livro propõe uma reflexão crítica sobre o ensino de Ciências nos anos iniciais a partir da articulação entre questões sociocientíficas, educação CTSA e a pedagogia de Paulo Freire. Com base em uma pesquisa desenvolvida no curso de Pedagogia, a obra evidencia como práticas pedagógicas dialógicas e contextualizadas podem contribuir para a formação de professores e professoras mais críticos, investigativos e comprometidos com a transformação social. Ao aproximar ciência, tecnologia, sociedade e ambiente das realidades vividas pelos estudantes, o estudo apresenta os “Temas Geradores Sociocientíficos” como uma proposta inovadora para uma educação humanista, interdisciplinar e socialmente engajada, alinhada às demandas formativas da contemporaneidade e da BNCC.', '["socioscientific issues","science, technology, society and environment","Freirean pedagogy","teacher professional development","dialogic teaching","critical pedagogy","humanistic education","interdisciplinarity","Base Nacional Comum Curricular","social change"]', '10.7476/9786556309903', '9786556308159', 'https://books.scielo.org/id/rsxsr', 'https://books.scielo.org/id/rsxsr/pdf/andrade-9786556309903.pdf', NULL, 'https://books.scielo.org/id/rsxsr/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rt85r', 'rt85r', 'Nascer não é igual para todas as pessoas', NULL, '["Vívian Volkmer Pontes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O livro reúne estudos realizados, durante 15 anos, por um grupo de pesquisa, em torno da mais universal e partilhada das realidades humanas: o nascer. A obra é dividida em quatro seções temáticas e cada uma possui capítulos-comentários feitos por pesquisadoras convidadas. Os comentários, além de romperem com a tendência endógena, representam a abertura para outras perspectivas e questões e contemplam uma função avaliativa. Assim, o livro interessa a leitoras e leitores que lidam com o nascer, a maternidade e a paternidade. Interessa a quem pesquisa, a quem atua na atenção à saúde e no cuidado de famílias e a quem pensa a questão da mulher, cuja voz fala mais alto ao longo dos estudos.', '["childbirth","births","motherhood","fatherhood","women''s health","family care","health care"]', '10.7476/9786556301938', '9786556301938', 'https://books.scielo.org/id/rt85r', 'https://books.scielo.org/id/rt85r/pdf/bastos-9786556301938.pdf', NULL, 'https://books.scielo.org/id/rt85r/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rtwp3', 'rtwp3', 'Literatura brasileira em foco VIII: outras formas de escrita', NULL, '["Andréa Sirihal Werkema","Rocha, Fátima Cristina Dias","Oliveira, Leonardo Davino de"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Apresentação 9 Outras formas de escrita Com esta edição, chega ao oitavo volume a série Literatura brasileira em foco, que, inaugurada em 2003, reúne a produção intelectual da equipe de professores que atuam no Curso de Pós-Graduação lato sensu em Literatura Brasileira.Criado no início dos anos 1980, o Curso de Especialização em Literatura Brasileira permanece vivo e atuante, contando com professores do Instituto de Letras da UERJ e com professores convidados, oriundos de outras instituições de ensino superior.Procurando abordar conteúdos relevantes e atuais, o Curso de Especialização em Literatura Brasileira desenvolve-se em torno de um tema, examinando-o sob os mais diversos ângulos.', '["Brazilian literature","literary genre"]', '10.7476/9788575114872', '9788575114872', 'https://books.scielo.org/id/rtwp3', 'https://books.scielo.org/id/rtwp3/pdf/werkema-9788575114872.pdf', NULL, 'https://books.scielo.org/id/rtwp3/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rw3nj', 'rw3nj', 'Mulheres inquietas: a bigamia feminina no Atlântico português (séculos XVI-XIX)', 'a bigamia feminina no Atlântico português (séculos XVI-XIX)', '["Emily de Jesus Machado"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Fruto de uma pesquisa de mestrado realizada no âmbito do Programa de Pós-Graduação em História da Universidade Federal da Bahia (PPGH/UFBA), este livro é uma contribuição importante para o conhecimento da história das mulheres em Portugal e no Atlântico Português da Época Moderna. A maior contribuição aportada pela obra é, justamente, o modo como a autora insere suas narrativas e análises sobre as diversas personagens e situações tratadas ao longo do estudo, num contexto amplo, com olhar atento às questões de natureza religiosa, social, econômica e cultural do período estudado.', '["women''s history","early modern period","marriage","gender and religion","women''s cultural status","Portugal"]', '10.7476/9786556308876', '9786556304694', 'https://books.scielo.org/id/rw3nj', NULL, NULL, 'https://books.scielo.org/id/rw3nj/cover/cover_thumbnail.jpeg', 271, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rwcyd', 'rwcyd', 'Política e direito na suprema corte norte-americana: debates teóricos e estudos de caso', NULL, '["Andrei Koerner"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A Suprema Corte: modelo institucional e problema político O modelo constitucional norte-americano teve repercussões internacionais, desde a sua adoção no final do século XVIII.Seus elementos, como a Constituição escrita, os freios e contrapesos entre os poderes do Estado, o federalismo e a declaração de direitos, eram inovações que se integravam ao repertório de artefatos para a organização do poder político.A difusão ocorreu antes de os Estados Unidos terem se tornado potência hegemônica no plano internacional e, desde então, passou a ser posto como modelo ou condicionalidade pelos seus dirigentes.O modelo representa, pois, um dos elementos incontornáveis nos debates políticos e processos de mudança de organização constitucional dos diferentes países.Em mais de duzentos anos, ocorreu nesses países um processo mais complexo do que a simples oposição entre cópia ou rejeição das instituições norte-americanas, pois os constituintes criaram, selecionaram ou combinaram aquele modelo com outros 1 .Verifica-se um processo de longa duração de circulação de modelos, de trocas transfronteiriças e de inovação institucional.Em grande medida, a importância e a difusão do modelo constitucional norte-americano resultaram do papel desempenhado por sua principal instituição, a Suprema Corte.', '["United States Supreme Court","separation of powers","federalism","Bill of Rights","institutional innovation","comparative constitutionalism"]', '10.7476/9788577982332', '9788577982332', 'https://books.scielo.org/id/rwcyd', 'https://books.scielo.org/id/rwcyd/pdf/koerner-9788577982332.pdf', NULL, 'https://books.scielo.org/id/rwcyd/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rwjyq', 'rwjyq', 'O instrumento do “Diabo”: música, imaginação e marginalidade', NULL, '["Carlos Stasi"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro traz um compositor-percussionista na condição de autor-escritor que realiza um ensaio teórico a partir de um fazer expressivo-artístico. O autor, especializado em instrumentos de percussão, traz reflexões a partir de seus experimentos com o instrumento denominado reco-reco, que não tem reconhecimento na música erudita. A partir de suas realizações criadoras envolvendo esse e outros instrumentos sem “nobreza”, o músico iniciou um processo reflexivo que inclui atividades como músico e compositor, suas experiências com a sonoridade daquele instrumento, seu uso, e sua posição no contexto da música. Outros aspectos foram se ampliando e se entrecruzando com diversidade de enfoques e por meio de metáforas. Os pensamentos, assim, atingem dimensões da política, filosofia, sociologia, antropologia a estética. São questionados valores estabelecidos, relações de poder na música e no cotidiano e experiências humanas. O pesquisador surpreende, portanto, pela capacidade de expandir sempre as possibilidades de pensamento sobre temas diversos, mesmo partindo, por exemplo, de uma experiência aparentemente restrita em torno de um instrumento de percussão tido como inexpressivo.', '["percussion instruments","musical improvisation","musical imagination","aesthetics","metaphor"]', '10.7476/9786557145340', '9786557145340', 'https://books.scielo.org/id/rwjyq', 'https://books.scielo.org/id/rwjyq/pdf/stasi-9786557145340.pdf', NULL, 'https://books.scielo.org/id/rwjyq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rwp2p', 'rwp2p', 'Música, educação e indústria cultural: o loteamento do espaço sonoro', NULL, '["Anamaria Brandi Curtú"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra permite compreender como entrelaçar da música, da educação e da tecnologia é explorado pela indústria cultural contemporânea, constituindo-se em desafio para os processos artístico-musicais e para a Educação Musical. Para nomear a analisar esse fenômeno – também encontrado no espaço escolar –, Anamaria Brandi Curtú tece o conceito de loteamento do espaço sonoro.', '["music education","cultural industries","acoustic space","school music","music technology","artistic process","commodification of music"]', '10.7476/9786557144848', '9786557144848', 'https://books.scielo.org/id/rwp2p', 'https://books.scielo.org/id/rwp2p/pdf/curt%C3%BA-9786557144848.pdf', NULL, 'https://books.scielo.org/id/rwp2p/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rws72', 'rws72', 'Saussure e a tradução', NULL, '["Valdir do Nascimento Flores"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '“Saussure e a Tradução objetiva derivar da linguística de Saussure uma refl exão acerca da tradução. Há vários motivos para propô-la: a) a necessidade de reler Saussure a partir de novas bases, levando em conta a especializada filologia saussuriana e a crescente divulgação de manuscritos que, hoje, permitem rever o destino dado a esse pensamento no século XX; b) a pertinência da teoria para a abordagem da tradução, considerando a amplitude que tem uma visão de conjunto da língua – articulada à diversidade das línguas – para tratar o fenômeno tradutório; c) finalmente, a prática tradutória de Saussure, tendo em vista que recentes documentos atestam que Saussure era um tradutor e, ainda mais, que essa atividade se coaduna com o seu pensamento acerca da linguagem, da língua e das línguas. O livro também reúne reflexões comparativas ao filósofo-linguista alemão Wilhelm von Humboldt que, como se sabe, legou importantes ideias sobre o fazer tradutório a partir da tradução da peça teatral Agamêmnon, de Ésquilo. Recentes manuscritos saussurianos comprovam que a mesma peça foi também traduzida por Saussure. Nesse caso, uma contraposição entre as duas traduções é feita a partir das discussões que ensejam os comentários feitos pelos tradutores. Tudo isso é pensado no quadro de uma antropologia da enunciação, ou seja, de uma reflexão que coloca o Homoloquens, o falante, no centro da reflexão. No caso em questão, o falante é nada mais nada menos que o tradutor Ferdinand de Saussure.', '["Ferdinand de Saussure","translation theory","Wilhelm von Humboldt","Agamemnon","Aeschylus","comparative translation analysis","language and translation"]', '10.7476/9786558460558', '9786558460244', 'https://books.scielo.org/id/rws72', NULL, NULL, 'https://books.scielo.org/id/rws72/cover/cover_thumbnail.jpeg', 180, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rxbj9', 'rxbj9', 'Dilemas do pós-modernismo na cultura de massa', NULL, '["Lilian Victorino"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro discute três obras cinematográficas de ficção científica – O homem bicentenário (1999), Inteligência artificial (2002) e Eu, Robô (2005) – unidas pelo discurso comum sobre a transformação técnico-científica do corpo humano. Esses filmes apresentam ao público questões bioéticas ligadas às pesquisas nas áreas de robótica, sistemas operacionais, criogenia, eugenia, bioengenharia, biotecnologia e seus usos em seres humanos. Lilian Victorino analisa de que modo esses filmes levam discursos científicos ao conhecimento popular e quais valores ou ideologias norteiam o pensamento social nas narrativas: importa entender não apenas qual história o filme conta, mas, sobretudo, como essa história é apresentada. Ver e refletir sobre essas obras são pontos de partida para recontar as histórias apresentadas; problematizar o que pode parecer natural para os espectadores é a intenção deste livro.', '["postmodernism","mass culture","science fiction film","The Matrix","I, Robot","bioethics","robotics","cryogenics","eugenics","bioengineering","biotechnology","popularization of science"]', '10.7476/9786557144992', '9786557144992', 'https://books.scielo.org/id/rxbj9', 'https://books.scielo.org/id/rxbj9/pdf/victorino-9786557144992.pdf', NULL, 'https://books.scielo.org/id/rxbj9/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rxw94', 'rxw94', 'Dicionário histórico-social do Oeste catarinense', NULL, '["José Carlos Radin","Gentil Corazza"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'IntroduçãoEste Dicionário histórico-social contém pequenos ensaios sobre temas relevantes do Oeste de Santa Catarina.Entre tais temas, destacam-se a história, a sociedade, a economia, a política e a cultura, além de outros assuntos relacionados a estes grandes temas.A escolha temática não foi aleatória, mas feita a partir de estudos anteriores, que ressaltam sua importância para compreender a região em análise.Também não são temas isolados uns dos outros, mas estreitamente relacionados e, algumas vezes, até parcialmente repetidos e superpostos uns aos outros.Preferiu-se incorrer nesse tipo de problema a deixar de abordar tais aspectos, que se mostram essenciais para a compreensão de cada tema.Julgou-se preferível, portanto, a superposição de temas e de análises a deixar lacunas entre eles, pois isso certamente limitaria a abrangência e a qualidade do trabalho.Do ponto de vista temporal, abordam-se questões históricas que envolveram personagens e questões relevantes desta região durante um longo período, que vai principalmente do final do século XIX até a atualidade.Os verbetes foram produzidos a partir de trabalhos existentes, bem como de outras fontes.Em futuras ampliações e atualizações deste Dicionário, pretende-se que eles sejam ilustrados, em especial com fotografias.Pode-se perguntar, também, por que apresentar a análise desses temas na forma de um dicionário de pequenos ensaios e não como estudos mais longos e aprofundados?Duas razões nos levaram a optar pelo formato de dicionário.Em primeiro lugar, porque praticamente todos os temas, aqui apresentados como pequenos ensaios, já foram objeto de inúmeros estudos mais longos e aprofundados, na forma de artigos, livros e trabalhos acadêmicos, os quais compõem uma ampla bibliografia sobre a história e a sociedade desta região.Uma segunda razão que motivou a apresentação dos estudos na forma de um dicionário, não de definições, mas de verbetes ou pequenos ensaios, se expressa na própria natureza e no objetivo de um dicionário, que é servir de introdução e guia para outros estudos de maior envergadura, sempre necessários para alargar e aprofundar a compreensão dos temas Dicionário Histórico-social Do oeste catarinense | 6 abordados.Dessa forma, um dicionário não pretende substituir esses estudos, mas sim estimulá-los.É nesse sentido, também, que este Dicionário não é apresentado como uma obra acabada e sim de um trabalho introdutório, em construção, que possa motivar estudantes e pesquisadores interessados em aprofundar seus conhecimentos sobre os temas analisados.', '["western Santa Catarina","regional history","social history","regional economy","regional politics","regional culture","historical dictionary entries","regional identity","regional development","regionalism"]', '10.7476/9788564905658', '9788564905658', 'https://books.scielo.org/id/rxw94', 'https://books.scielo.org/id/rxw94/pdf/radin-9788564905658.pdf', NULL, 'https://books.scielo.org/id/rxw94/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rxwst', 'rxwst', 'O uso do inglês em contexto comercial no Brasil e em Portugal: questões linguísticas e culturais', NULL, '["Natália Cristine Prado"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"Este livro analisa a formação de nomes comerciais com elementos do inglês no português brasileiro e no português europeu, observando como os empréstimos se comportam, em termos linguísticos e culturais, nessas duas variedades da língua portuguesa. Verificou-se como falantes do português brasileiro e europeu pronunciam nomes comerciais criados a partir de palavras do inglês, enfocando o estudo das adaptações nos níveis fonético e fonológico e observando o tipo de estrutura morfossintática desses nomes e sua ortografia."', '["English loanwords","trade names","brand names","Brazilian Portuguese","European Portuguese","language contact","pronunciation adaptation","phonetic adaptation","phonological adaptation","morphosyntactic structure","spelling"]', '10.7476/9788579836541', NULL, 'https://books.scielo.org/id/rxwst', 'https://books.scielo.org/id/rxwst/pdf/prado-9788579836541.pdf', NULL, 'https://books.scielo.org/id/rxwst/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ry4j6', 'ry4j6', 'O método Anticartesiano de C. S. Peirce', NULL, '["Lucia Santaella-Braga"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Livro que relaciona o pensamento de Peirce ao de Descartes, é a demonstração, por C. S. Peirce, de que a investigação científica é sempre gratificante, pois é a maneira que o intelectual tem de conversar com a natureza em suas diversas escalas, a microscópica, a inorgânica, a biológica, a humana e a macroscópica. Uma das maiores especialistas no país sobre as teorias de Peirce, a autora traz a oportunidade de reflexão de como Peirce tomou Descartes por seu primeiro interlocutor, apontando deficiências do pensamento cartesiano com a convicção de que os novos tempos demandavam um raciocínio que transcendesse o legado do intelectual francês. (co-edição: FAPESP)', '["Charles Sanders Peirce","René Descartes","scientific inquiry","nature of science","philosophy of science","history of philosophy"]', '10.7476/9788539303236', '9788571395275', 'https://books.scielo.org/id/ry4j6', NULL, NULL, 'https://books.scielo.org/id/ry4j6/cover/cover_thumbnail.jpeg', 277, 27, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rybxj', 'rybxj', 'Prosa de Nagô: educando pela cultura', NULL, '["Vanda Machado"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '“Prosa de Nagô” é um texto dramatizado nascido da escuta e registro de conversas de gente da comunidade Afonjá. Transformados em personagens, todos os envolvidos no projeto Irê Ayó dialogam entre si, entrelaçando aspectos de educação, tradição, religião, ciências, filosofia africana e aspectos da história da África que dão origem a essa família de santo. Abrem-se, com esse livro, possibilidades de efetivar as leis nº 10.639/03 e 11.645/08, que possibilitam caminhos para a compreensão da ancestralidade negra, questão importante na formação de educadoras e educadores para o ensino fundamental com a perspectiva de outros estudos epistemológicos, outras metodologias e outros paradigmas para a construção de um currículo descolonizado, emancipatório e transdisciplinar.', '["Afro-Brazilian culture","African American education","transdisciplinary curriculum","emancipatory education","African philosophy","African history","religious traditions","primary education"]', '10.7476/9786556304021', '9786556300528', 'https://books.scielo.org/id/rybxj', NULL, NULL, 'https://books.scielo.org/id/rybxj/cover/cover_thumbnail.jpeg', 216, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ryhtg', 'ryhtg', 'A política externa brasileira: a busca da autonomia, de Sarney a Lula', NULL, '["Tullo Vigevani","Gabriel Cepaluni"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Quando, em 1985, José Sarney tomou posse como o primeiro governo civil após longos anos de regime militar, o país enfrentava uma grave crise econômica, e o modelo econômico de substituição de importações então vigente – que perdurava desde a década de 1930 –, além de criticado pelo FMI e pelo Banco Mundial, apresentava problemas. Esse contexto, aliado a outros fatores, como a ineficácia das medidas adotadas para controlar a inflação e manter o crescimento do PIB, provocava instabilidade e evidenciava a necessidade de mudanças na política econômica externa brasileira. Essas mudanças aconteceram gradualmente, traçando um novo desenho que buscava o fortalecimento da soberania do país. Neste livro, originalmente publicado em inglês pela Lexington Books (2009) e que agora ganha sua segunda edição em português, Tullo Vigevani e Gabriel Cepaluni delineiam, de maneira clara e encadeada, o caminho histórico que o Brasil percorreu desde então em sua política externa: Sarney e as pressões para a mudança; Collor/Itamar Franco e o turbulento governo que deu início às transformações liberais; Fernando Henrique Cardoso e a absorção e consolidação de mudanças resultantes da globalização, levando à autonomia pela participação; e Lula, com sua ênfase nas negociações comerciais internacionais e na busca de aprofundamento da coordenação política com países em desenvolvimento. Os autores descrevem e analisam empiricamente essa trajetória, demonstrando como a procura por desenvolvimento e autonomia política – que perpassa níveis que vão do distanciamento dos países dominantes à diversificação de parceiros – esteve constantemente presente na política externa do Brasil. A política externa brasileira questiona quais são os principais elementos de continuidade e de mudança e orienta a análise, partindo do pressuposto de que “a autonomia de um país confere a ele condições de construir uma política externa livre de constrangimentos internacionais impostos pelos países mais poderosos”.', '["Brazilian foreign policy","economic sovereignty","import substitution","José Sarney","Fernando Collor","Fernando Henrique Cardoso","Luiz Inácio Lula da Silva","economic liberalization","globalization","international trade negotiations","developing countries","political autonomy"]', '10.7476/9788595460621', '9788539306572', 'https://books.scielo.org/id/ryhtg', NULL, NULL, 'https://books.scielo.org/id/ryhtg/cover/cover_thumbnail.jpeg', 180, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rykxr', 'rykxr', 'Planejamento da produção de cana-de-açúcar no contexto das mudanças climáticas globais', NULL, '["Jurandir Zullo","André Tosi Furtado","Cláudia Regina Castellanos Pfeiffer"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', '"As mudanças climáticas deixaram de ser um assunto restrito à área acadêmica e começaram a fazer parte do cotidiano das pessoas e das pautas de discussões das políticas de desenvolvimento nacional e internacional. Cabe à academia realizar pesquisas e tornar público seu conhecimento, fornecendo instrumentos e análises que auxiliem os tomadores de decisões – poder público e iniciativa privada – a formular estratégias para lidar com as mudanças climáticas, levando em consideração as dimensões sociais e ambientais. Este livro apresenta algumas das análises realizadas no interior de um projeto interdisciplinar em que se colocaram em questão as possibilidades de expansão das áreas de plantio da cana-de-açúcar, elaborando cenários que incorporaram elementos advindos dos estudos ambientais, sobre dinâmica populacional, segurança alimentar e economia. Ao lado dessa questão, encontram-se reflexões sobre a importância da divulgação científica e sobre as possibilidades de alcançar resultados no caso específico das mudanças climáticas. É esse conjunto de ideias que se pretende fazer circular."', '["climate change","scenario analysis","food security","population dynamics","economic analysis","science communication","climate policy"]', '10.7476/9788526814998', '9788526813618', 'https://books.scielo.org/id/rykxr', NULL, NULL, 'https://books.scielo.org/id/rykxr/cover/cover_thumbnail.jpeg', 392, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ryvp9', 'ryvp9', 'O som do silêncio da Hepatite C', NULL, '["Francisco Inácio Bastos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Abordar a hepatite C – grave epidemia contemporânea – não só em seus aspectos biomédicos, mas destacando ainda questões psicológicas, sociais e históricas relativas à doença: este é o objetivo desse livro, escrito pelo médico, com pós-doutorado no exterior, Francisco Inácio Bastos. Também pesquisador titular do Instituto de Comunicação e Informação Científica e Tecnológica em Saúde (Icict/Fiocruz), o autor é experiente no trabalho junto a usuários de drogas e portadores do HIV. Muitos de seus pacientes com Aids, atendidos em instituição voltada à população necessitada, têm falecido em decorrência da dupla infecção pelo HIV e pelo vírus da hepatite C. Testemunha das dificuldades enfrentadas pelos pacientes com hepatite C crônica para conseguirem tratamento, Bastos destaca a necessidade de se melhorar a prevenção e a assistência prestada a quem vive com essa doença.', '["hepatitis C","HIV/HCV coinfection","AIDS","chronic hepatitis C","access to treatment","prevention","stigma","drug users"]', '10.7476/9788575413715', '9788575413715', 'https://books.scielo.org/id/ryvp9', 'https://books.scielo.org/id/ryvp9/pdf/bastos-9788575413715.pdf', NULL, 'https://books.scielo.org/id/ryvp9/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-rzt8g', 'rzt8g', 'A ação mímica: princípios e poéticas da mímica corporal dramática de Étienne Decroux', NULL, '["George Mascarenhas"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O que é mímica corporal dramática? Quais os seus princípios e fundamentos técnicos? Qual a sua aplicabilidade em projetos artísticos contemporâneos? Para discutir essas e outras questões, o livro apresenta alguns aspectos históricos, técnicos e poéticos dessa arte e aborda as controvertidas afirmações acerca das restrições de sua aplicação na contemporaneidade. A obra pretende fornecer um guia de estudos prático-teóricos para os interessados na Mímica Corporal Dramática de Étienne Decroux, como elemento complementar à prática nas salas de ensaio e no exercício cotidiano de artistas da cena.', '["Étienne Decroux","mimesis","actor training","acting technique","contemporary theatre","theatre practice","history of acting"]', '10.7476/9786556303727', '9786556303727', 'https://books.scielo.org/id/rzt8g', 'https://books.scielo.org/id/rzt8g/pdf/mascarenhas-9786556303727.pdf', NULL, 'https://books.scielo.org/id/rzt8g/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s2hwx', 's2hwx', 'Burocracia e ideologia', NULL, '["Maurício Tragtenberg"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Este livro se destina, principalmente, a examinar o surgimento e o perecimento das teorias administrativas através do tempo, conforme as determinações econômico-sociais existentes. Com isto, se pretende estudar a Teoria Geral da Administração como ideologia, dentro do plano traçado e fundamentando-se em textos relevantes ao assunto. Tal análise será desenvolvida em perspectiva estritamente sociológica, no nível de sociologia do conhecimento, isto é, do estudo da causa social das teorias de administração ideológicas.', '["bureaucracy","ideology","general theory of administration","sociology of knowledge"]', '10.7476/9788539302871', '9788571396562', 'https://books.scielo.org/id/s2hwx', NULL, NULL, 'https://books.scielo.org/id/s2hwx/cover/cover_thumbnail.jpeg', 288, 292, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s2q96', 's2q96', 'Interação pais e filhos com Síndrome de Williams: relatos sobre avaliação e intervenção', NULL, '["Lucia Cunha Lee","Luiz Renato Rodrigues Carreiro"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Neuroscience', '[RETIRADO/WITHDRAWN] A concepção de díades como sustentação do processo de desenvolvimento do indivíduo pode apontar para a análise da relação dual como recurso da avaliação e intervenção da relação entre pais e filhos. Nesse sentido, a linha condutora de Interação pais e filhos com Síndrome de Williams: relatos sobre avaliação e intervenção apoiou‑se na apreciação da interação de díades mães‑filhas com Síndrome de Williams. As situações de observação, autoavaliação e reflexão dessas mães nos encontros com suas filhas revelam um recurso fecundo e ampliam a compreensão das relações familiares, tornando‑se um importante norteador em procedimentos de intervenção de crianças na área dos transtornos do desenvolvimento. Dessa maneira, este livro pode inspirar nos pais e nos profissionais das áreas da psicologia, saúde e educação a observação tanto da dimensão objetiva como da profunda comunicação intersubjetiva de diversos pares que se formam e sustentam as intermitentes transformações familiares.', '["Williams syndrome","parent-child interaction","mother-child dyads","dyadic interaction","family relationships","developmental disorders","family intervention","intersubjectivity"]', '10.7476/9788582937259', '9788582937259', 'https://books.scielo.org/id/s2q96', NULL, NULL, 'https://books.scielo.org/id/s2q96/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s2qcq', 's2qcq', 'Educação escolar indígena: resistência ativa e diálogos interculturais', 'resistência ativa e diálogos interculturais', '["Clelia Neri Côrtes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro traz a consistência dos longos e significativos processos vividos, aliados à ousadia que sustenta qualquer experiência relacionada a Paulo Freire. A autora começa seu percurso ancorando o tema em seus contextos epistemológicos e históricos para, em seguida, “mirar outros 500”, ou seja, propor caminhos para a conquista de uma educação escolar feita por e para indígenas.', '["indigenous education","school education","active resistance","intercultural dialogue","Paulo Freire","indigenous peoples","epistemology of education","history of education"]', '10.7476/9786556308845', '9786556304717', 'https://books.scielo.org/id/s2qcq', 'https://books.scielo.org/id/s2qcq/pdf/cortes-9786556308845.pdf', NULL, 'https://books.scielo.org/id/s2qcq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s2rwx', 's2rwx', 'Reinventar un héroe. Narrativas sobre los soldados rasos de la guerra de Corea', NULL, '["Sebastián Quiroga Cubides"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'reinventar un héroe veteranos de la guerra y la institución castrense dominaban sobre los relatos de los soldados rasos, quienes conformaron la mayoría del cuerpo militar que participó en la guerra.Este fue el punto de partida de la investigación: preguntarse sobre cuál fue la experiencia de estos soldados durante la guerra de Corea.¿Quién es el soldado raso?Es aquel que ingresa a las Fuerzas Armadas, ya sea por reclutamiento, o bien porque se presenta como voluntario.Dentro del esquema militar, tiene el rango más bajo.Sin embargo, pese a constituir la mayoría de los efectivos que conforman un contingente militar, la historiografía no suele mencionarlos: son muy pocos los ejemplos de soldados rasos que aparecen en las obras de historia.Los modelos clásicos de historia hasta el siglo xix privilegiaron una narración de los acontecimientos bélicos anteponiendo a los grandes personajes como los actores principales.2 Fue 2 Por ejemplo, José Manuel Restrepo los menciona brevemente en Historia de la Revolución de la República de Colombia como actores ocasionales, donde se conoce su sueldo o como tropo -metonimia-, como sinónimo de humildad o el estrato social más bajo : "comiendo carne sin sal desde el jefe supremo hasta el último soldado" (tomo I, 159-160); "vosotros me habéis visto elevarme", dice el general José Antonio Páez, "de la triste esfera de un soldado al eminente rango que ocupo" (tomo IV, 158).Jesús María Henao y Gerardo Arrubla, en Historia de Colombia para la enseñanza secundaria, muestran en estos términos al soldado.Uno de los pocos que salen referidos por su nombre es Juan Gordo, un soldado español que fue ejecutado por su general, Gonzalo Jiménez de Quesada (80), u otros con historias anecdóticas muy breves.El caso más notable es el soldado Pedro Martínez, que junto a otro apodado Negro José, capturó a José María Barreiro en la Batalla de Boyacá, y adquirieron cierto grado marginal de heroísmo.Este militar, en 1880, recibió una pensión de 25 pesos que solo pudo cobrar una vez (384).Esta narración es anecdótica en estos autores, puesto que aparece en un pie de página y no como parte de la narrativa principal.El 7 de agosto de 1999 se erigió un monumento en honor de ambos en el Puente de Boyacá.13 sebastián quiroga cubides ya en el siglo xx que los historiadores comenzaron a mostrar una mayor preocupación por los soldados y, en general, por los subalternos.Al indagar sobre las vivencias de estos soldados rasos, se encontró que las experiencias se iban transformando y ajustando a una serie de intereses que dependían del lugar de producción del relato.Cada tipo de narrativa encerraba un cúmulo de significados y símbolos diferentes.El pasado se convirtió en un campo de batalla para reafirmar un papel en el espacio social.Por ello, esta investigación buscó responder a cómo en los últimos sesenta años las narrativas sobre la guerra de Corea han asignado un papel diferente al soldado raso y cuáles son las implicaciones de ello en la manera como entendemos dicha guerra.Es un análisis sobre la historicidad y la producción histórica, entendiendo que esta no se limita a la academia, sino que además es construida en los relatos de prensa, las memorias, la literatura, las obras de teatro, la música y, principalmente, por parte de los mismos protagonistas, desde la historia oral.Este trabajo gira en torno a diversas discusiones historiográficas: primero, dentro de los estudios subalternos, que han buscado reivindicar la voz de los grupos sociales no reconocidos en los grandes relatos nacionales; segundo, la historia oral, ya que desde sus raíces ha buscado entender las dinámicas sociales de la forma en que los protagonistas reconstruyen su pasado; finalmente, el papel que tiene la estructura narrativa en la reconstrucción del pasado y cuál es el papel de la historia dentro de la sociedad.No obstante, el problema de fondo en el cual se ubica esta investigación es 14 reinventar un héroe sobre la memoria: ¿Por qué recordamos de forma diferente un hecho?, ¿qué papel tienen los soldados rasos, normalmente silenciados en las narrativas hegemónicas de la guerra, en la construcción del pasado? El ascenso del subalternoEl interés por las experiencias de los subalternos puede rastrearse en diferentes plumas como Baudelaire, Michelet o Brecht.Este tipo de preocupaciones animaron a los investigadores a explorar nuevas fuentes.Un ejemplo claro en la historia militar es Letters of Private Wheeler, 1809-1828, editado por B. H. Liddell Hart (1951).Este texto es una recopilación de cartas que escribía a su esposa el soldado raso William Wheeler, del 51 Regimiento de la infantería británica.3 En la década de 1960, Edward Thomson introdujo formalmente el estudio de las clases populares en lo que denominó "historia desde abajo".4 Este tipo de historia en principio se concentró en la clase obrera y pobre, y posteriormente en grupos considerados marginados, como las mujeres.Estas nuevas preocupaciones atrajeron el interés de los historiadores, quienes comenzaron a explorar nuevos temas, desde la historia de los movimientos estudiantiles hasta el papel de los soldados en la guerra.En palabras de Jim Sharpe, "mostrar que la batalla de Waterloo comprometió tanto al 3 Jim Sharpe."Historia desde abajo", en Formas de hacer Historia [Peter Burke, editor].', '["Korean War","enlisted personnel","military narratives","heroism","historiography of military history","soldiers'' experiences","Colombian military history","military education","military technology","military organization","military strategy","military tactics"]', '10.7476/9789587385939', '9789587385939', 'https://books.scielo.org/id/s2rwx', 'https://books.scielo.org/id/s2rwx/pdf/quiroga-9789587385939.pdf', NULL, 'https://books.scielo.org/id/s2rwx/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s2vbm', 's2vbm', 'Sobre dizer: ensaio fenomenológico em torno da linguagem', NULL, '["Sanqueilo de Lima Santos"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Ensaio filosófico, declaradamente especulativo e hermenêutico divinatório, levanta o problema da voz própria da filosofia, ou seja, da sua discursividade. A título de interlocutores, são revisitados pensadores como Castoriadis, Benjamin, Merleau-Ponty, Heidegger, Wittgenstein e Platão, elegendo, como fio condutor, as respectivas concepções de linguagem.', '["language","discursivity","phenomenology of language","hermeneutics","Cornelius Castoriadis","Benjamin","Merleau-Ponty","Martin Heidegger","Wittgenstein","Plato","philosophy of language"]', '10.7476/9788574555522', '9786586213942', 'https://books.scielo.org/id/s2vbm', NULL, NULL, 'https://books.scielo.org/id/s2vbm/cover/cover_thumbnail.jpeg', 119, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s2xwj', 's2xwj', 'Loucos pela vida: a trajetória da reforma psiquiátrica no Brasil', 'a trajetória da reforma psiquiátrica no Brasil', '["Paulo Amarante"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1998, '1998-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este valioso livro analisa cuidadosamente a evolução conceitual que orientou os movimentos antimanicomiais no Brasil nas décadas de 70/80. Nele, o leitor terá acesso a informações preciosas dos bastidores desta luta, as movimentações internas, tensões, divergências das diretrizes que marcaram a história destes movimentos. Este estudo mostra que refletir sobre o passado é um exercício para aconstrução do futuro.', '["anti-psychiatry movement","mental health activism","history of psychiatry","conceptual evolution","psychiatric deinstitutionalization","Brazil","1970s-1980s"]', '10.7476/9788575413357', '9788585676513', 'https://books.scielo.org/id/s2xwj', 'https://books.scielo.org/id/s2xwj/pdf/amarante-9788575413357.pdf', NULL, 'https://books.scielo.org/id/s2xwj/cover/cover_thumbnail.jpeg', NULL, 210, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s2y2y', 's2y2y', 'Capitalismo e colapso ambiental', NULL, '["Luiz Marques"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"A perspectiva de um colapso ambiental vem sendo evidenciada pelas ciências e pelas humanidades desde os anos 1960. Hoje, ela impõe sua urgência. Achim Steiner, subsecretário-geral da ONU, adverte incessantemente: “se nada for feito, o colapso dos serviços prestados pelos ecossistemas é uma clara possibilidade”. Esse colapso difere dos das civilizações passadas por não ser nem local, nem apenas civilizacional. Ele é global e ocorre no nível mais amplo da biosfera, da qual as sociedades humanas dependem existencialmente. Evitar a falência das estruturas de sustentação dos ecossistemas, voltar a “caber” na biosfera, só será possível se desmontarmos a engrenagem socioeconômica expansiva que moldou nossas sociedades desde o século XVI. A sociedade futura será pós-capitalista ou não será uma sociedade complexa, e mesmo talvez, deve-se temer, sociedade alguma. Alargar esse consenso nascente foi o que motivou este livro."', '["environmental collapse","capitalism","ecosystem services","biosphere","post-capitalism","global environmental crisis"]', '10.7476/9788526815032', '9788526814684', 'https://books.scielo.org/id/s2y2y', NULL, NULL, 'https://books.scielo.org/id/s2y2y/cover/cover_thumbnail.jpeg', 736, 315, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s37rj', 's37rj', 'Cotidiano, poder e relações sociais entre a Antiguidade e a Idade Média: homenagem ao Professor Nachman Falbel', NULL, '["Ana Paula Tavares Magalhães","Marinalva Silveira Lima"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Em homenagem ao professor Nachman Falbel, titular da cadeira de História da FFLCH-USP, hoje aposentado, apresentamos um conjunto de textos, produzidos por profissionais altamente qualificados e oriundo de universidades de todo o Brasil. Por meio desta coletânea, concentrada nas áreas da História Antiga e Medieval, celebramos a extensa carreira docente e a excelência em pesquisa histórica que marcaram a trajetória de Nachman Falbel. Tendo dominado temáticas variadas e com competência teórico-metodológica observada nos grandes acadêmicos, o professor Falbel nos deixa um amplo legado - bibliográfico e quanto à formação de pesquisadores. Esta obra pretende, sobretudo, refletir tal diversidade e manifestar admiração por ela. Para além da produção propriamente acadêmica, Falbel é um erudito, feito de uma matéria que tanto nos tem admirado em nossos tradicionais mestres escolares. A opção por uma abordagem a um tempo política e cultural, institucional e social, também vem reforçar a homenagem que aqui se presta: ao transitar por seus mais variados objetivos, Falbel nos brinda com igualmente variadas metodologias do fazer História, o que nos tem permitido refletir sobre as temáticas sob perspectivas diversas, afastando preconceitos e aproximando pessoas e matrizes teóricas. Acreditamos, por fim, que Falbel, em sua grandeza acadêmica e em sua invejável erudição, dispensa títulos e denominações artificiais: por aquilo que é e sempre será, como pesquisador e educador, pode limitar-se ao simples - e significativo - denominativo de “Professor Nachman”.', '["everyday life","power","interpersonal relationships","ancient history","medieval history","historiography","political and cultural history","institutional history"]', '10.7476/9788576286967', '9788576286431', 'https://books.scielo.org/id/s37rj', NULL, NULL, 'https://books.scielo.org/id/s37rj/cover/cover_thumbnail.jpeg', 315, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s3ny4', 's3ny4', 'Iniciação científica: aspectos históricos, organizacionais e formativos da atividade no ensino superior brasileiro', NULL, '["Luciana Massi","Salete Linhares Queiroz"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'implicações e perspectivas 13 Jamile C. A.', '["undergraduate research","research organization","research training","higher education","Brazilian higher education"]', '10.7476/9788568334577', '9788568334577', 'https://books.scielo.org/id/s3ny4', 'https://books.scielo.org/id/s3ny4/pdf/massi-9788568334577.pdf', NULL, 'https://books.scielo.org/id/s3ny4/cover/cover_thumbnail.jpeg', NULL, 25, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s3sm8', 's3sm8', 'Ajeum de memórias', NULL, '["Etna Kaliane Pereira da Silva","Andrêa Jacqueline Fortes Ferreira","Gabriela dos Santos Vilasboas","Izabela Alves Gomes","Vivian Carla Honorato dos Santos de Carvalho"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra retrata as memórias alimentares de nutricionistas negras e negros em intersecção com temáticas relevantes no campo da alimentação, nutrição e saúde. A partir de suas experiências individuais nos coletivos da vivência em sociedade, as(os) autoras(es) refletem sobre os atravessamentos sociais e culturais vivenciados através da alimentação, (re)significando histórias a partir da sua comensalidade, ofertando caminhos para compreensão afetiva dos alimentos e da comida na sua vivência cotidiana no seio familiar e nas suas comunidades. A obra é um convite à reflexão sobre a comida, a alimentação e seus significados, mas também a possibilidade de elaboração de comidas, pelas receitas apresentadas, que, em algum momento, foram, são e podem ser parte do nosso viver diaspórico no presente, passado e futuro.', '["food memories","Black women","food and identity","food and health","family meals","diaspora","recipes","meaning of food","commensality"]', '10.7476/9786556309347', '9786556308104', 'https://books.scielo.org/id/s3sm8', 'https://books.scielo.org/id/s3sm8/pdf/silva-9786556309347.pdf', NULL, 'https://books.scielo.org/id/s3sm8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s3vn9', 's3vn9', 'As interfaces do direito agrário e dos direitos humanos e a segurança alimentar', NULL, '["Elisabete Maniglia"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Livro em que se trata das conexões entre o direito à alimentação adequada, conhecido também por Segurança Alimentar, o Direito Agrário e os Direitos Humanos. Parte-se do princípio de Justiça Social do Direito Agrário, firmado na ideologia da função social da propriedade, buscando-se estabelecer na atividade agrária, exercida de forma sustentável, o fundamento para se promover a diminuição da fome e da miséria. Considera-se que o direito à alimentação adequada é um direito humano fundamental e que o Estado, em parceria com a sociedade civil, deve promover as diferentes formas de apoio para proporcionar segurança alimentar e nutricional, sob pena de não se constituir em um Estado Democrático de Direito. Aponta-se que alguns países e blocos econômicos fazem desta luta sua meta de assegurar a dignidade dos cidadãos, enquanto outros, como o Brasil, ainda direcionam mecanismos por meio de políticas públicas e legislações recentes para encaminhar o apoio aos que vivem em estado preocupante de insegurança alimentar, causado pela desigualdade social. Trata-se de uma obra de inegável atualidade', '["food security","right to food","agricultural law","human rights","social function of property","sustainable agriculture","hunger alleviation","food and nutrition security","public policy","social inequality","democratic rule of law","civil society"]', '10.7476/9788579830143', '9788579830143', 'https://books.scielo.org/id/s3vn9', 'https://books.scielo.org/id/s3vn9/pdf/maniglia-9788579830143.pdf', NULL, 'https://books.scielo.org/id/s3vn9/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s4jcj', 's4jcj', 'A extinção do arco-íris: ecologia e história', NULL, '["Jozimar Paes de Almeida"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[...] Este trabalho se circunscreve ao sistema capitalista de produção. Não ignoro, no entanto, que outros sistemas como o socialista, por exemplo - incorram em processo semelhante.', '["capitalist mode of production","environmental crisis"]', '10.7476/9788599662694', '9788599662694', 'https://books.scielo.org/id/s4jcj', 'https://books.scielo.org/id/s4jcj/pdf/almeida-9788599662694.pdf', NULL, 'https://books.scielo.org/id/s4jcj/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s4n4k', 's4n4k', 'Sistematização de experiências de trabalho com grupos nos Centros de Referência em Obesidade/RJ', NULL, '["Phillipe Augusto Ferreira Rodrigues","Luciana da Silva Rodriguez","Caroline Niquini de Assis","Raquel de Lima Soeiro","Jorginete de Jesus Damião","Juliana Pereira Casemiro"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Produzido por profissionais dos Centros de Referência em Obesidade (CRO) em parceria com professores do Instituto de Nutrição da UERJ, este livro oferece um olhar interdisciplinar sobre a questão da obesidade, ampliando as possibilidades de abordagens de educação e promoção da saúde relacionadas ao excesso de peso. A publicação parte do contexto macropolítico brasileiro sobre as questões da obesidade, em relação aos dados epidemiológicos, políticas públicas e documentos e publicações norteadoras da área. Segue-se a apresentação dos Centros de Referência em Obesidade e de conceitos-chave para esse serviço, incluindo um olhar sobre as vivências, atividades e temas vitais ao cotidiano desses profissionais de saúde e daqueles que demandam os cuidados.', '["obesity","group work","health promotion","obesity education","overweight","public health policy","health professionals'' experiences","interdisciplinary approach","Rio de Janeiro"]', '10.7476/9786587949154', '9786587949154', 'https://books.scielo.org/id/s4n4k', 'https://books.scielo.org/id/s4n4k/pdf/rodrigues-9786587949154.pdf', NULL, 'https://books.scielo.org/id/s4n4k/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s597r', 's597r', 'Discriminação e saúde: perspectivas e métodos', NULL, '["João Luiz Bastos","Eduardo Faerstein"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'É possível apreender cientificamente a discriminação? Que desafios complexos devem ser enfrentados nesta iniciativa? Para responder a estas perguntas, são necessárias estratégias metodológicas capazes de identificar e medir a discriminação. Apresentar as ferramentas disponíveis e discutir suas potencialidades e limitações são os objetivos deste livro. “Há vasta literatura que documenta a influência deletéria de processos discriminatórios na relação estabelecida entre profissionais de saúde e pacientes, na prescrição de tratamentos medicamentosos ou de outros procedimentos cirúrgicos e terapêuticos, assim como na própria satisfação dos usuários com o atendimento prestado”, afirmam os autores. Eles apresentam o tema em perspectiva histórica, desde antes da década de 1920 até os dias atuais. Também descrevem os principais métodos hoje utilizados para mensurar a discriminação, como experimentos laboratoriais; experimentos de campo; análises de dados observacionais e experimentos naturais; e análise de indicadores. Sublinham as peculiaridades do contexto brasileiro e chamam atenção, por exemplo, para casos em que os tratamentos injustos estão tão internalizados que discriminadores e discriminados não identificam aquelas situações como problemáticas, considerando-as normais e naturais.', '["discrimination","health","discrimination measurement","health care discrimination","laboratory experiments","field experiments","natural experiment","observational data analysis","health indicators","Brazil"]', '10.7476/9788575415320', '9788575413845', 'https://books.scielo.org/id/s597r', NULL, NULL, 'https://books.scielo.org/id/s597r/cover/cover_thumbnail.jpeg', 112, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s59t6', 's59t6', 'Carlos Octavio Bunge e José Ingenieros: entre o científico e o político. Pensamento racial e identidade nacional na Argentina (1880-1920)', NULL, '["Camila Bueno Grejo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'escolha das fontes até a redação fi nal.', '["José Ingenieros","racial thought","national identity","Argentine intellectual history","science and politics"]', '10.7476/9788598605982', '9788598605982', 'https://books.scielo.org/id/s59t6', 'https://books.scielo.org/id/s59t6/pdf/grejo-9788598605982.pdf', NULL, 'https://books.scielo.org/id/s59t6/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s5cw9', 's5cw9', 'Transformações da política na era da comunicação de massa', NULL, '["Gomes, Wilson"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Transformações da política na era da comunicação de massa é uma obra já clássica, agora revisada e atualizada em sua 3ª edição, que se propõe a analisar a intrincada relação entre a comunicação de massa, a política e a democracia, com foco no impacto da televisão na vida pública. O livro, voltado para estudantes e pesquisadores de comunicação, ciência política e sociologia, assim como para interessados em política em geral, examina como a televisão transformou a política, impulsionou a profissionalização da comunicação política e moldou a opinião pública. A obra diferencia-se por ser pioneira no Brasil ao abordar essa temática de forma abrangente, com base em um sólido arcabouço teórico-metodológico desenvolvido a partir dos anos 1970. O livro se destaca, por sua abordagem rigorosa e fundamentada, oferecendo uma análise aprofundada da interação entre comunicação e política na era da comunicação de massa.', '[]', '10.7476/9786556309019', '9786556307640', 'https://books.scielo.org/id/s5cw9', 'https://books.scielo.org/id/s5cw9/pdf/gomes-9786556309019.pdf', 'https://books.scielo.org/id/s5cw9/epub/gomes-9786556309019.epub', 'https://books.scielo.org/id/s5cw9/cover/cover_thumbnail.jpeg', 372, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s5gx2', 's5gx2', 'Celso Furtado: a esperança militante (Interpretações): vol. 1', NULL, '["Cidoval Morais de Sousa","Ivo Marcos Theis","José Luciano Albino Barbosa"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Celso Furtado (1920-2004) foi um dos mais importantes economistas e cientistas sociais brasileiros. Demonstrou, em sua obra, o que significa a relação inseparável entre o pensar e o agir, entre o rigor acadêmico e o engajamento político. Esta Coletânea, volume 1 de um uma trilogia sobre aspectos da vida e obra deste paraibano de Pombal, reúne textos produzidos nos últimos 30 anos por intérpretes atentos e privilegiados. Atentos, porque pesquisadores, estudiosos dos problemas brasileiros, vinculados a instituições de prestígio nacional e internacional (USP, UNICAMP, UFRJ, FGV, UFMG, UFPE) e que têm a crítica como natureza de ofício; privilegiados, porque conviveram em algum momento da vida pessoal, profissional ou acadêmica com Celso Furtado. Tentamos nos guiar pela incômoda pergunta: O que deveria ser retido como última lição do mestre? O próprio Furtado responde: “Equivoca-se quem pretende que já não existe espaço para a utopia. Esse é o desafio maior que enfrenta a nova geração: convido-a a assumi-lo sem temores”', '["Celso Furtado","Brazilian economists","social scientists","political participation","utopia","intellectual legacy"]', '10.7476/9786586221695', '9786586221695', 'https://books.scielo.org/id/s5gx2', 'https://books.scielo.org/id/s5gx2/pdf/sousa-9786586221695.pdf', NULL, 'https://books.scielo.org/id/s5gx2/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s5k33', 's5k33', 'Programa de aceleração do crescimento (PAC): neodesenvolvimentismo?', NULL, '["Maria Chaves Jardim","Márcio Rogério Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Fugindo de leituras ideologizantes e abstratas, este livro aborda as novas relações entre Estado e mercado no Brasil contemporâneo, principalmente durante o governo Lula, tendo como objeto empírico o Programa de Aceleração do Crescimento (PAC) e suas diversas nuanças, como o papel do PAC durante a crise de 2008, a geração de novos postos de trabalho, a inclusão social pelas finanças e a introdução de infraestrutura e serviços por meio de parcerias entre entidades públicas e privadas.', '["Programa de Aceleração do Crescimento","neodevelopmentalism","state-market relations","Lula government","2008 financial crisis","job creation","social inclusion","public-private partnerships","infrastructure"]', '10.7476/9788579837432', '9788579837432', 'https://books.scielo.org/id/s5k33', 'https://books.scielo.org/id/s5k33/pdf/jardim-9788579837432.pdf', NULL, 'https://books.scielo.org/id/s5k33/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s6', 's6', 'Um rigor outro sobre a qualidade na pesquisa qualitativa: educação e ciências humanas', NULL, '["Roberto Sidnei Macedo","Dante Galef","Álamo Pimentel"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra trata da importância da vivência diária na pesquisa acadêmica. Sua abordagem crítica é direta e mostra de forma prática a eficiência da pesquisa a partir das experiências vividas pelo pesquisado', '["qualitative research","research rigor","lived experience","educational research","human sciences"]', '10.7476/9788523209278', '9788523209278', 'https://books.scielo.org/id/s6', 'https://books.scielo.org/id/s6/pdf/macedo-9788523209278.pdf', NULL, 'https://books.scielo.org/id/s6/cover/cover_thumbnail.jpeg', NULL, 27, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s639n', 's639n', 'Do “era uma vez…” ao “viveram felizes para sempre…!”: (re)visitando a literatura', NULL, '["Andréia Inês Hanel Cerezoli","Carla Roberta Sasset Zanette","Roselaine de Lima Cordeiro"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra, que nasceu de uma proposta didática no curso de Licenciatura em Pedagogia da Universidade Federal da Fronteira Sul (UFFS), Campus Erechim, na disciplina de Produção Textual Acadêmica, ministrada na modalidade remota, em decorrência da pandemia da COVID-19, se constitui de duas partes. Em “Espelho, espelho meu! Que reflexões teóricas tragou eu?”, estão reunidos textos teóricos que problematizam desde a apresentação de obras literárias até a formação teórica e política da formação de mediadores de leitura. Na segunda parte, “Que olhos grandes você tem! Exercícios de leitura literária”, são os discentes, como leitores e autores, que protagonizam o livro. Cada um deles apresenta exercícios de leitura, a partir de obras da literatura infantojuvenil. Uma (re)visita a obras amplamente conhecidas e lidas e outras tornadas importantes pela experiência da leitura nesse encontro entre texto e leitor. “Do ‘Era uma vez…’ ao ‘Viveram felizes para sempre…!’: (re)visitando a Literatura” é um convite ao leitor para que, ao percorrer suas páginas, (re)descubra a magia da literatura infantojuvenil e acompanhe algumas reflexões sobre a leitura. Fica a certeza das organizadoras de que a obra, sozinha, não forma leitores, mas a reunião de todos os autores, apaixonados por literatura, é um passo na direção do “Felizes para sempre!”, utopia de Eduardo Galeano.', '["children''s literature","young adult literature","reading mediation","reading exercises","reader formation","literary theory","COVID-19 remote teaching","academic writing","reader-text relationship"]', '10.7476/9786550190286', '9786550190286', 'https://books.scielo.org/id/s639n', 'https://books.scielo.org/id/s639n/pdf/cerezoli-9786550190286.pdf', NULL, 'https://books.scielo.org/id/s639n/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s64v7', 's64v7', 'Alma e festa de uma cidade: devoção e construção na Colina do Bonfim', NULL, '["Mariely Cabral de Santana"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Tendo como eixo central a festa do Senhor do Bonfim, este livro representa um mergulho na história da cidade de Salvador com o propósito de entender a relação existente entre devoção, festa e apropriação do espaço físico público para comemorações religiosas ou profanas. Procura definir o valor simbólico da festa e o seu reconhecimento como patrimônio cultural, avaliando também a sua dimensão concreta, apreendida através da cultura, no espaço da colina do Bonfim.', '["religious devotion","appropriation of public space","urban festivals","cultural heritage","urban construction"]', '10.7476/9788523209421', '9788523209421', 'https://books.scielo.org/id/s64v7', 'https://books.scielo.org/id/s64v7/pdf/santana-9788523209421.pdf', NULL, 'https://books.scielo.org/id/s64v7/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s6z2q', 's6z2q', 'Processos educativos dialógicos que conscientizam e libertam', NULL, '["Márcio Fernando Gomes"]', 'Directory of Open access Books (OAPEN Foundation)', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro é fruto de um ciclo de oficinas e atividades metodológicas de ensino-aprendizagem dialógico. Partindo da indissociabilidade entre ensino, pesquisa e extensão, Processos Educativos Dialógicos Que Conscientizam e Libertam procura contribuir para a construção de conhecimentos para a formação docente inicial e continuada. Compreendendo a diversidade como fonte de ensino-aprendizagem em contexto de multiculturalidades e multiterritorialidades, buscando à equidade entre os diferentes e à superação das desigualdades e, assim, comprometendo-se hoje com a conscientização sobre a realidade educacional e social, sonha em amanhã transformá-la e libertá-la.', '["teacher professional development","initial teacher education","continuing teacher education","educational equity","multicultural education","multiterritoriality","diversity in education","social inequality","teaching-learning methodologies"]', '10.7476/9786586768466', '9786586768466', 'https://books.scielo.org/id/s6z2q', 'https://books.scielo.org/id/s6z2q/pdf/gomes-9786586768466.pdf', NULL, 'https://books.scielo.org/id/s6z2q/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s6z76', 's6z76', 'Uma aula como ocupação: da infância da arte à arte da infância', NULL, '["Nathália Pallos Imbrizi"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, a autora pensa a sala de aula como uma ocupação que transborda a aula para a esfera pública. Para isso, a autora narra a experiência de convidar artistas contemporâneos a ocuparem o espaço da escola pública de base com suas “obras de arte” e seus desdobramentos. A partir dessas experiências, justifica a ideia de “uma aula como ocupação” e reúne as falas das crianças escutadas ao longo desse processo. Nesse sentido, propõe que o ensino de arte na escola se reinvente permanentemente e se afaste do perigo da instrumentalização da arte e da infância.', '["art education","childhood","public sphere","instrumentalization of art","children''s voices","public schools","art in education"]', '10.7476/9786559542499', '9786559542499', 'https://books.scielo.org/id/s6z76', 'https://books.scielo.org/id/s6z76/pdf/imbrizi-9786559542499.pdf', NULL, 'https://books.scielo.org/id/s6z76/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s78j9', 's78j9', 'Trabalho (imaterial), valor e classes sociais: diálogos com pesquisadores contemporâneos', NULL, '["Henrique Jose Domiciano Amorim"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro Trabalho (imaterial), valor e classes sociais: diálogos com pesquisadores contemporâneos traz à luz um debate que se estruturou em meados dos anos 1970 na Europa e nos Estados Unidos, que se difundiu no Brasil, mais fortemente, nos anos 1990 e que nos anos 2000 ainda se faz presente. No cerne desse debate está a tese da superação da sociedade industrial e, com ela, dos conceitos marxistas de trabalho, valor e classes sociais. Neste livro, entrevistamos 22 pesquisadores contemporâneos, procurando questioná-los exatamente sobre tais temas. Os questionamentos se orientaram, primeiro, no sentido de problematizarmos, para a realidade contemporânea, a tese sobre o fim da sociedade industrial e, segundo, ao destacar as particularidades da pesquisa e dos estudos de cada entrevistado, explorando temas sociais, históricos, econômicos e filosóficos centrais presentes nas sociedades contemporâneas. Assim, além de expormos um leque variado de interpretações sobre o trabalho, o trabalho imaterial, o valor e as classes sociais, há neste livro um conjunto de formulações teóricas que podem nos ajudar a compreender as relações sociais que constituem as sociedades no século XXI. Além disso, contamos com o prefácio de Alfredo Saad Filho (Soas-UK) e com o posfácio de Giovanni Alves (Unesp-Marília), que nos trouxeram apontamentos importantes, seja sobre a importância e a pertinência teórica e social das entrevistas, seja sobre a conjuntura social que dá base para nosso livro.', '["intangible work","social class","Marxist theory of labor","contemporary social theory","interpersonal relationships","post-industrial society"]', '10.7476/9786580216185', '9786580216185', 'https://books.scielo.org/id/s78j9', 'https://books.scielo.org/id/s78j9/pdf/amorim-9786580216185.pdf', NULL, 'https://books.scielo.org/id/s78j9/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s7v75', 's7v75', 'Delegados de polÍcia', NULL, '["Maria Tereza Sadek"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Quem são e o que pensam os delegados de polícia? Para responder a essas perguntas, o Idesp realizou, com o apoio da Fundação Ford e da Fapesp, a mais ampla e inédita pesquisa sobre o perfil dos delegados de polícia no Brasil.', '["police commissioner","police leadership","police administration"]', '10.7476/9788579820144', '9788579820144', 'https://books.scielo.org/id/s7v75', 'https://books.scielo.org/id/s7v75/pdf/sadek-9788579820144.pdf', NULL, 'https://books.scielo.org/id/s7v75/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s83n7', 's83n7', 'Violência dói e não é direito: a violência contra a mulher, a saúde e os direitos humanos', NULL, '["Ana Flávia Pires Lucas d’Oliveira","Maria Thereza Couto Falcão","Wagner dos Santos Figueiredo","Lilia Blima Schraiber"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O tema da violência contra a mulher é abordado neste livro de maneira franca e objetiva, analisando-o como uma questão social e de saúde pública. A violência contra a mulher pode ser verbal, física e sexual, praticada por familiares, conhecidos e até mesmo por instituições públicas. São discutidos casos reais de abusos e agressões, em especial no âmbito das relações domésticas, uma vez que sua característica familiar está na origem da dificuldade cultural em considerá-la um problema da sociedade. Os autores questionam as causas do problema, os limites dos serviços de saúde, as mudanças culturais necessárias para alterar esse quadro e o impacto da violência na saúde da mulher. Analisam os aspectos éticos e jurídicos da agressão e fornecem informações úteis a respeito da rede de assistência à mulher em situação de violência.', '["violence against women","intimate partner violence","domestic violence","sexual violence","verbal aggression","women''s health","human rights","public health","health services","cultural change","ethics of violence"]', '10.7476/9788539303472', '9788571396067', 'https://books.scielo.org/id/s83n7', NULL, NULL, 'https://books.scielo.org/id/s83n7/cover/cover_thumbnail.jpeg', 183, 34, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s8488', 's8488', 'Um porto em quatro tempos: Salvador e as dinâmicas de acumulação de capital', NULL, '["José Ricardo Moreno Pinho"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'A obra compara as dinâmicas de transformação do porto de Salvador com as mudanças das formas de acumulação de capital, seus arranjos e sua hegemonia. Trata-se de um estudo acerca das mudanças legais, da relação entre o estado e os privados, das mudanças físicas no porto e na estrutura urbana do seu entorno.', '["capital accumulation","port transformation","port law","state-private relations"]', '10.7476/9788585813369', '9786588211755', 'https://books.scielo.org/id/s8488', 'https://books.scielo.org/id/s8488/pdf/pinho-9788585813369.pdf', 'https://books.scielo.org/id/s8488/epub/pinho-9788585813369.epub', 'https://books.scielo.org/id/s8488/cover/cover_thumbnail.jpeg', 183, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s88y6', 's88y6', 'O tecido da Rede-SANS: histórico, narrativas e reflexões', NULL, '["Maria Rita Marques de Oliveira","Carla Maria Vieira","Lilian Fernanda Galesi-Pacheco"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O TECIDO DA REDE-SANS 15Cooperação: valorizar o trabalho colaborativo na divisão de tarefas, bem como incentivar a troca e a disponibilização de bens e serviços em favor do outro.Direito à informação transparente: difundir e ampliar o acesso às informações de interesse público, sem reservas, em linguagem adequada e compreensível, de forma direta e clara.Produção e socialização do conhecimento: fomentar a produção e a socialização do conhecimento pautado em evidências científicas e ao mesmo tempo reconhecendo as tradições populares.Promoção da economia solidária: valorizar e apoiar novas formas de comércio, de maneira a promover o desenvolvimento local.Bem-estar e justiça social: nas decisões de gestão dos recursos, tomar como referência os princípios de equidade, integralidade, universalidade e participação popular.', '["social and solidarity economy","cooperative networks","cooperative principles","transparency","solidarity economy","local development","social justice","citizen participation"]', '10.7476/9788579837517', '9788579837517', 'https://books.scielo.org/id/s88y6', 'https://books.scielo.org/id/s88y6/pdf/oliveira-9788579837517.pdf', NULL, 'https://books.scielo.org/id/s88y6/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s8tk4', 's8tk4', 'Povos indígenas, formação de professores e educação intercultural: diálogos com a lei nº 11.645/2008', NULL, '["Grando, Beleni Saléte","Stroher, Jonathan","Campos, Neide da Silva"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A coletânea é um diálogo intercultural com proposições para a inclusão da história e cultura indígena na escola (Lei 11.645/08). Na Parte I, são apresentados resultados da pesquisa-ação que tensionam a formação de professores e a prática pedagógica, avaliam os processos formativos e descrevem a proposta metodológica ‘formação-ação-intercultural do Coeduc’. Na Parte II são apresentadas experiências formativas e práticas pedagógicas exitosas com estudantes da educação infantil, ensino fundamental, médio e superior.', '["indigenous peoples","teacher professional development","intercultural education","Law 11.645/2008","action research","teaching practice"]', '10.7476/9786587626123', '9786587626123', 'https://books.scielo.org/id/s8tk4', NULL, NULL, 'https://books.scielo.org/id/s8tk4/cover/cover_thumbnail.jpeg', 228, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-s9vh3', 's9vh3', 'Modernização urbana na Belle Époque paulista', NULL, '["Fransérgio Follis"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O processo de modernização da cidade de Franca (SP), ocorrido entre 1890 e 1940, tratado neste livro possibilita ao leitor constatar a excelência da pesquisa desenvolvida e a riqueza de possibilidades interpretativas que a história local/regional oferece. A história das cidades pode contribuir para que se constate que o processo histórico das diversas regiões brasileiras compõe-se de casos semelhantes, com profundas particularidades. Cabe a conveniência de que essa perspectiva seja levada em conta quando se projetam políticas públicas de alcance nacional, tendo em vista que o autor aborda temas como a arrecadação pública, a paisagem urbana moderna e as conseqüências sociais das alterações urbanísticas, principalmente no que se referem à vida das camadas da população mais afastadas do centro do poder.', '["urban modernization","Belle Époque","Franca, São Paulo","urban history","public revenue collection","peripheral populations","regional history","public policy"]', '10.7476/9788539303267', '9788571395404', 'https://books.scielo.org/id/s9vh3', NULL, NULL, 'https://books.scielo.org/id/s9vh3/cover/cover_thumbnail.jpeg', 151, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sb6rs', 'sb6rs', 'Saúde e desenvolvimento humano', NULL, '["Tânia Gracy Martins do Valle","Lígia Ebner Melchiori"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro está dividido em quatro seções. Na primeira, que trata da Sexualidade e Corporeidade, os temas apresentados abordam o conceito de corporeidade, gênero e a busca por serviços de saúde, a imagem corporal em mulheres com depressão e a política de redução de danos em situações de sexualidade e vulnerabilidade. Na segunda seção, Intercorrências no desenvolvimento infantil, os temas se referem ao desenvolvimento infantil, abordando os efeitos do chumbo e da escolaridade, as habilidades sociais de crianças com irmão com transtorno de espectro autístico ou com desenvolvimento típico, e a ocorrência de estresse e bullying em crianças em condição de sobrepeso e obesidade. A terceira seção, intitulada Adolescentes: maternidade, fatores de risco e de proteção aborda o tema da gravidez e maternidade da adolescência, as interações familiares de mães adolescentes e os fatores de risco e de proteção em adolescentes com transtorno mental. A quarta seção, intitulada Manejo de estresse e outros fatores em diferentes populações adultas, aborda o estresse em universitários com desordens temporomandibulares, em motoristas de ônibus urbano ou em pacientes com líquen oral', '["sexuality","embodiment","gender","health care access","body image","depression in women","harm reduction","child development","lead exposure","school attendance","social skills","autism spectrum disorder"]', '10.7476/9788579831195', '9788579831195', 'https://books.scielo.org/id/sb6rs', 'https://static.scielo.org/scielobooks/sb6rs/pdf/valle-9788579831195.pdf', NULL, 'https://books.scielo.org/id/sb6rs/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sc2b8', 'sc2b8', 'Geografia e ensino: dimensões teóricas e práticas para a sala de aula', NULL, '["Gilmar Alves Trindade","Gilsélia Lemos Moreira","Lurdes Bertol Rocha","Maria Cristina Rangel","Rita Jaqueline Nogueira Chiapetti"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra apresenta como tema central o ensino de Geografia, com importantes discussões teóricas e reflexões sobre o papel e a importância da pesquisa escolar. Traz, ainda, experiências que se colocam como possibilidades para a melhoria da qualidade do ensino da disciplina em questão, em especial na educação básica.', '["geography education","school research","teaching quality","basic education","teaching practice"]', '10.7476/9788574555263', '9788574555263', 'https://books.scielo.org/id/sc2b8', 'https://books.scielo.org/id/sc2b8/pdf/trindade-9788574555263.pdf', NULL, 'https://books.scielo.org/id/sc2b8/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-scdms', 'scdms', 'A literatura em questão: sobre a responsabilidade da instituição literária', NULL, '["Marcos Natali"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Os nove capítulos de A literatura em questão são compostos por reflexões a respeito da relação entre literatura e ética. A preocupação de fundo do livro é com a “responsabilidade literária”, isto é, com o modo como a instituição literária responde, ou se recusa a responder, a inquirições sobre as relações entre a literatura e os direitos humanos, a sala de aula, as discursividades indígenas, o luto, o racismo, a loucura e a violência. Nesse exercício, o interesse pela literatura advém da percepção de que ela é um território privilegiado para a dramatização de fantasias associadas à democracia, em particular a crença na possibilidade infinita de inclusão da alteridade e de sua assimilação sem atrito.', '["literary responsibility","ethics in literature","literature and human rights","mourning","racism","madness","violence","democracy","otherness","inclusion"]', '10.7476/9786586253719', '9786586253443', 'https://books.scielo.org/id/scdms', NULL, NULL, 'https://books.scielo.org/id/scdms/cover/cover_thumbnail.jpeg', 280, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-scfwy', 'scfwy', 'Fronteiras e interfaces da comunicação científica', NULL, '["Cristiane de Magalhães Porto","Flávia Goulart Mota Garcia Rosa","Flávio Tonnetti"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro reúne 13 artigos produzidos por autores de diferentes universidades brasileiras e da América Latina, com o intuito de discutir as diversas formas de comunicação em ciência, com enfoque na relação dos cientistas com o público, mas considerando a relação dos cientistas com seus pares. Trata-se de uma reflexão sobre as dimensões sociais, filosóficas, culturais e políticas da comunicação científica, além de abordar os avanços tecnológicos e seus impactos nesta área.', '["science communication","scientists and the public","peer relationships","social dimensions of science","philosophy of science","science policy"]', '10.7476/9788523217327', '9788523215613', 'https://books.scielo.org/id/scfwy', NULL, NULL, 'https://books.scielo.org/id/scfwy/cover/cover_thumbnail.jpeg', 265, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-scfy6', 'scfy6', 'A saúde no Brasil em 2030: desenvolvimento produtivo e complexo da saúde - Vol. 5', NULL, '["Fundação Oswaldo Cruz"]', 'Fiocruz/Ipea/Ministério da Saúde/Secretaria de Assuntos Estratégicos da Presidência da República', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Este volume abrange os ensaios sobre Desenvolvimento Produtivo e Complexo da Saúde. Compõe-se de cinco artigos: a dinâmica de inovação e perspectiva do Complexo Econômico-Industrial da Saúde (CEIS) para a sustentabilidade estrutural do sistema de saúde; o subsistema de base química e biotecnológica; o subsistema de base mecânica, eletrônica e de materiais; o subsistema de serviços em saúde e a infraestrutura científica e tecnológica para apoio ao CEIS.', '["health system sustainability","healthcare innovation","health economic-industrial complex","biotechnology","medical devices","health services","scientific and technological infrastructure","health system development","Brazil"]', '10.7476/9788581100197', '9788581100197', 'https://books.scielo.org/id/scfy6', 'https://books.scielo.org/id/scfy6/pdf/noronha-9788581100197.pdf', NULL, 'https://books.scielo.org/id/scfy6/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-schmg', 'schmg', 'Modelos teóricos: como elaborar, utilizar e relatar em estudos epidemiológicos', 'como elaborar, utilizar e relatar em estudos epidemiológicos', '["Breno Augusto Bormann de Souza Filho","Érika Fernandes Tritany","Claudio José Struchiner"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Nursing', 'O livro Modelos Teóricos: como elaborar, utilizar e relatar em estudos epidemiológicos, de Breno Augusto Bormann de Souza Filho, Érika Fernandes Tritany e Cláudio José Struchiner, propõe caminhos para fortalecer a fundamentação teórica em pesquisas de saúde pública. Com linguagem acessível, a obra oferece orientações para construir, aplicar e relatar modelos teóricos, incluindo ferramentas como o Checklist para Relato Teórico em Estudos Epidemiológicos (CRT-EE), registrado na Rede EQUATOR. Voltado a pesquisadores, estudantes e avaliadores científicos, o livro discute desafios contemporâneos, valoriza o raciocínio crítico-científico e contribui para a produção de conhecimento sólido, transparente e reprodutível, capaz de orientar decisões e políticas em saúde coletiva.', '["theoretical model","EQUATOR Network","public health research","reproducibility","health policy"]', '10.7476/9786557082911', '9786557082096', 'https://books.scielo.org/id/schmg', NULL, NULL, 'https://books.scielo.org/id/schmg/cover/cover_thumbnail.jpeg', 162, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sckpj', 'sckpj', 'Música e autismo: ideias em contraponto', NULL, '["Gleisson do Carmo Oliveira","Marina Horta Freire","Betânia Parizzi","Renato Tocantins Sampaio"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro apresenta uma temática recente que tem despertado, cada vez mais, o interesse do público em geral: as profundas relações entre música e autismo. Considerada uma das principais ferramentas das neurociências para a compreensão do cérebro humano, a música tem se configurado como uma forma singular e eficaz de intervenção no enfrentamento dos desafios advindos do autismo, tanto pelo viés terapêutico (Musicoterapia) quanto pelo viés pedagógico (Educação Musical). Música e Autismo dialogam, aqui, de modo transdisciplinar com a Ciência, com a Musicoterapia e com a Educação Musical, o que permite amplo acesso ao livro por profissionais das mais diversas áreas. Assim, esse diálogo a 5 vozes busca desvendar o fascínio que a música exerce em todos nós, principalmente nos autistas.', '["autism spectrum disorder","music therapy","music education","music and the brain","transdisciplinary dialogue"]', '10.7476/9786558581116', '9786558580782', 'https://books.scielo.org/id/sckpj', NULL, NULL, 'https://books.scielo.org/id/sckpj/cover/cover_thumbnail.jpeg', 246, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-scxkb', 'scxkb', 'Ensino de ofícios artesanais e manufatureiros no Brasil escravocrata', NULL, '["Luiz Antônio Cuñha"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra demonstra como a escravidão determinou o desprezo pelos "ofícios mecânicos" no Brasil na época do Brasil Colônia e Império, quando, após a abolição da escravatura, ninguém queria exercer atividades consideradas "coisas de escravos". Assim, a aprendizagem de ofícios acabou sendo imposta a quem não tinha meios de resistir, reforçando esse desvalor. Apresenta uma análise das instituições dedicadas ao ensino de ofícios: liceus de artes e ofícios, arsenais militares, asilos, propiciando ao leitor conhecer as propostas dos intelectuais do Império a respeito da aprendizagem profissional e seus esperados efeitos moralizantes. Juntamente com os títulos O ENSINO DE OFÍCIOS NOS PRIMÓRDIOS DA INDUSTRIALIZAÇÃO e O ENSINO PROFISSIONAL NA IRRADIAÇÃO DO INDUSTRIALISMO, integra a trilogia do mesmo autor, Luiz Antônio Cunha, professor titular de Educação Brasileira da UFRJ, que trata de minucioso levantamento histórico da educação profissional no Brasil desde o período escravocrata até o ensino profissional na virada do século. (Co-edição: Flacso)', '["slavery","colonial Brazil","Brazilian Empire","military arsenals","professional education","abolition of slavery","moral education","history of education in Brazil"]', '10.7476/9788539303007', '9788571396319', 'https://books.scielo.org/id/scxkb', NULL, NULL, 'https://books.scielo.org/id/scxkb/cover/cover_thumbnail.jpeg', 190, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sd', 'sd', 'Caminhos da saúde pública no Brasil', NULL, '["Jacobo Finkelman"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2002, '2002-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'É com emoção e alegria que introduzo os leitores a este belo documento que registra as relações da Organização Pan-Americana de Saúde (OPAS) com nosso país nos últimos cem anos.Criada em 1902, contemporânea, portanto, à Fundação Oswaldo Cruz, a OPAS tem sua trajetória profundamente vinculada às vicissitudes, erros, acertos, esperanças e, também, aos fracassos e problemas dos sistemas de saúde do continente americano.É importante salientar que a documentação que nos traz Caminhos da Saúde Pública no Brasil mostra que a contribuição da OPAS com o país e deste com a Organização foi algo que modernamente se denomina "um caso de sucesso".', '["Pan American Health Organization","history of public health","Brazil","international health cooperation","health care system","Latin America"]', '10.7476/9788575412848', '9788575412848', 'https://books.scielo.org/id/sd', 'https://books.scielo.org/id/sd/pdf/finkelman-9788575412848.pdf', NULL, 'https://books.scielo.org/id/sd/cover/cover_thumbnail.jpeg', NULL, 41, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sdtvs', 'sdtvs', 'O programa Minha Casa Minha Vida: habitação e produção do espaço urbano em diferentes escalas e perspectivas', NULL, '["Maia, Doralice Sátyro","Marafon, Glaucio José"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] O Programa Minha Casa Minha Vida foi criado pelo Governo Federal em 2009, como política voltada para a habitação. Este livro investiga o impacto dessa política pública em diferentes recortes urbanos, observando as consequências na produção, expansão e consumo das cidades. As análises reunidas referem-se primordialmente a Campina Grande e Patos, na Paraíba; Caruaru, em Pernambuco; Campos, no Norte Fluminense, e Marília e Presidente Prudente, no Estado de São Paulo. O livro é resultado de pesquisa realizada com recursos da Capes e do Ministério da Integração, entre 2013 e 2018. Os autores são professores dos cursos de Geografia e de Programas de Pós- Graduação em Geografia da UERJ, UNESP e UFPB associados a essa iniciativa. O livro inclui também textos de pesquisadores convidados que trabalham com a mesma temática em outras realidades, ampliando o leque de cidades estudadas e enriquecendo o conteúdo.', '["Minha Casa Minha Vida program","housing policy","urban space production","urban expansion","public policy impact","urban geography","Campina Grande","Patos","Caruaru","Campos","Marília","Presidente Prudente"]', '10.7476/9786500030297', '9786500030297', 'https://books.scielo.org/id/sdtvs', 'https://books.scielo.org/id/sdtvs/pdf/maia-9786500030297.pdf', NULL, 'https://books.scielo.org/id/sdtvs/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sdytq', 'sdytq', 'Estudos de saúde, ambiente e trabalho: aspectos socioculturais', NULL, '["Mônica Angelim Gomes de Lima","Maria do Carmo Soares de Freitas","Paulo Gilvane Lopes Pena","Sérgio Trad"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra reúne alguns estudos, distribuídos em dez capítulos, sobre saúde, ambiente e trabalho, numa perspectiva qualitativa, trazendo para o centro da investigação a análise de narrativas dos sujeitos implicados no processo de trabalho. Os capítulos articulam a práxis social com a lógica causal das ciências biológicas, humanizadas pelos sentidos dos sujeitos envolvidos, além do diálogo com a análise ergonômica do trabalho, que adquire destaque no processo de adoecimento.', '["occupational health","occupational diseases","human factors","social praxis"]', '10.7476/9788523218645', '9788523218645', 'https://books.scielo.org/id/sdytq', 'https://books.scielo.org/id/sdytq/pdf/lima-9788523218645.pdf', NULL, 'https://books.scielo.org/id/sdytq/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sdzvw', 'sdzvw', 'Desenvolvimento, mineração, mudanças climáticas: reflexões socioantropológicas', 'reflexões socioantropológicas', '["Jalcione Almeida"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro contém resultados de pesquisa, e os capítulos que o integram representam uma significativa amostra de enfoques e questões relacionadas às Ciências Sociais, em que os projetos de desenvolvimento e seus conflitos têm caráter determinante nas análises, estas realizadas no campo de uma socioantropologia. Os artigos apresentados são, em sua maioria, inéditos, e delineiam abordagens de vanguarda, originais, com um diapasão que busca intercalar, de forma harmônica, teoria e empiria acerca de questões que envolvem o “desenvolvimento” e sua relação com o ambiente nas sociedades contemporâneas. Os eixos centrais desta coletânea giram em torno da mineração, das questões sociopolíticas sobre o desenvolvimento, ruralidades, formas alternativas de produção, novas maneiras de sociabilidade, impactos ambientais de grandes empreendimentos energéticos e produtivos, alimentação, desastres ambientais e mudanças climáticas.', '["development projects","mining","climate change","rural society","sociability","food","environmental disasters","development conflicts","environment and society"]', '10.7476/9786557252260', '9786557250907', 'https://books.scielo.org/id/sdzvw', NULL, NULL, 'https://books.scielo.org/id/sdzvw/cover/cover_thumbnail.jpeg', 477, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sf4xd', 'sf4xd', 'Ordem imperial e aldeamento indígena: Camacãns, Gueréns e Pataxós do Sul da Bahia', NULL, '["Ayalla Oliveira Silva"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'ORDEM IMPERIAL E ALDEAMENTO INDÍGENA: Camacãs, Gueréns e Pataxós no Sul da Bahia é uma pesquisa histórica de fôlego, baseada em rica documentação primária e em um diálogo firme com várias questões importantes levantadas pela historiografia contemporânea.O foco do olhar e da pesquisa de Ayalla Oliveira Silva se dirige aos povos do sul da Bahia: camacãs, pataxós, guerens e inúmeros outros grupos indígenas que, depois de aldeados e ressocializados no mundo colonial e imperial, passaram a ser reconhecidos como índios, índios aldeados ou ainda índios de Ferradas.A autora não poupou esforços para expor, analisar e problematizar seu tema de pesquisa, desenvolvendo-o em cinco capítulos densos e bem estruturados.Com erudição, começa a reflexão se debruçando sobre os memorialistas que escreveram a história de Itabuna.Demonstra que lembrar e esquecer são típicos da memória e que tais operações não são aleatórias.Lembrase e esquece-se ao sabor de conjunturas históricas específicas e em função de necessidades e projetos políticos e sociais.De acordo com ela: "A leitura feita sobre as populações indígenas do sul da Bahia na escrita memorialista era extremamente pejorativa.Os índios eram descritos como os selvagens que percebendo a inutilidade de suas flechas diante das armas de fogo dos colonizadores, se aprofundavam nas matas."Waly Salomão disse, com simplicidade e profundidade poética, que "a memória é uma ilha de edição". 1 Quando se trata de memória pessoal, a questão é, naturalmente, de foro íntimo.O mesmo não se pode dizer da memória social que afeta a todos: incluídos e excluídos dela.Tratar povos, comunidades e indivíduos indígenas como "selvagens" e deixá-los fora da narrativa histórica não é, contudo, uma característica particular dos memorialistas do sul da Bahia.Como argumentou o saudoso historiador John Monteiro, desde a constituição do Instituto Histórico e Geográfico Brasileiro, em 1838, estabeleceu-se a firme convicção de que os índios eram objeto da etnografia, não da disciplina história, justamente por serem considerados povos "primitivos" e "selvagens".2 Além disso, vários profissionais e leigos começaram a acreditar que os índios estavam fora da historiografia por motivos bem concretos, notadamente a ausência de fontes históricas para estudálos.De modo ainda mais dramático, os índios estariam fora da narrativa histórica em razão do precoce e rápido desaparecimento físico deles do cenário social, após o contato com os colonizadores.Ayalla Oliveira Silva não fechou os olhos para as evidências do tempo presente.No sul da Bahia, os conflitos de terra entre índios e não índios são renhidos e representam um vívido testemunho de que os índios fazem parte do presente, como antes fizeram parte do passado.Foi aos Os agradecimentos ocupam a última parte a ser escrita neste trabalho, uma versão um pouco modificada da minha dissertação de mestrado.A sensação é essa: cheguei ao fim, acabou!A alegria sentida não é porque o trabalho acabou, concluo apenas uma etapa, mas o trabalho continua e a paixão pelo que faço me move, ela é indescritível.O sentimento de alegria fica a cargo da concretização de um sonho, do qual muitas pessoas fizeram parte, de forma indireta e direta.Eu agradeço carinhosamente àquelas que me ajudaram a tornar possível a conclusão de mais uma etapa.Ao programa de Pós-Graduação em História da UFRRJ, à professora Rebeca Gontijo, coordenadora do programa, e ao secretário Paulo Longarini, pela atenção e disponibilidade de sempre.Aos meus colegas da pósgraduação e aos professores, com quem muito aprendi nas disciplinas cursadas.Aos funcionários do Arquivo Público do Estado da Bahia (APEB) que, nas minhas intensivas visitas, invariavelmente correndo contra o tempo, no afã de dar conta de uma documentação superior à que o tempo me permitia, compreensivamente me auxiliavam de forma muito gentil; em especial, agradeço a Pedro, Elza e Reinaldo.A Urano, o pesquisador que mais conhece aquele Arquivo e seus acervos.Salvou-me muitas vezes, me dando dicas e, inclusive, emprestando-me seu material de trabalho.A Frei Ulisses Pinto, arquivista do Arquivo Histórico Nossa Senhora da Piedade, da Ordem dos Frades Menores Capuchinhos (OFMCap.),da Província da Bahia, agradeço AGRADECIMENTOS pela recepção sempre alegre e prestativa, e também à sua secretária Vanice, pelos cafezinhos e pela companhia na sala de consulta.Ao Centro de Documentação e Memória da UESC, na pessoa da amiga e grande profissional Stela Teixeira.O CE-DOC é especial, foi lá que os primeiros passos foram dados.Além da consulta ao acervo hemerográfico, naquele espaço, eu tive muitas e produtivas conversas com o professor Marcelo Henrique Dias e com os queridos amigos da graduação: Angélica, Victor e João, amigos e parceiros de estudo.Agradeço à Fundação Marimbeta, pelo apoio dado aos meus estudos desde a graduação.Aos amigos queridos de trabalho: dona Vera (uma mãezona), Carlos, Lucas, Jacque e Rai, incentivadores e colaboradores incondicionais, agradeço de forma muito especial.Além dos amigos já mencionados, agradeço aos demais amigos antigos e aos novos: Norma, Graci, Michele, Adê, Angélica, Marcelo, Antônio, Natália e Maylin.A cada uma e cada um, de forma particular e especial.Agradeço à querida Ir.Emídia pelo cuidado e pelas orações a mim dedicadas.À Bruna e Everton, quero levar nossa amizade, construída nesses dois anos, para toda a vida.Com Everton dividi muitos momentos difíceis nos primeiros tempos no Rio, mas dividimos também muitas aventuras pela "Cidade Maravilhosa"; como ríamos de nossas distrações!Transformamo-nos em amigos-irmãos.Meus agradecimentos à amiga Sarah, com carinho e saudade.Dividimos as dificuldades, os desafios e as alegrias do primeiro ano do mestrado.Agradeço à Talita, amiga de outros tempos, com quem tenho estreitado os laços e dividido as experiências diárias.Agradeço às professoras Fabiane Popinigis e Maria Regina Celestino de Almeida e ao professor Marcelo Henrique Dias, por aceitarem o convite para participar da banca de defesa.', '["indigenous settlements","Pataxó","imperial order","colonial Brazil","southern Bahia","indigenous memory","memorialists","indigenous identity","Itabuna","social memory"]', '10.7476/9788574555287', '9788574555287', 'https://books.scielo.org/id/sf4xd', 'https://books.scielo.org/id/sf4xd/pdf/silva-9788574555287.pdf', NULL, 'https://books.scielo.org/id/sf4xd/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sfttr', 'sfttr', 'Foucault, a arqueologia e As palavras e as coisas – 50 anos depois', NULL, '["Domingues, Ivan"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2023, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Tendo frequentado os cursos de Foucault no Collège de France entre os anos de 1981 e 1983, em quem vê o interlocutor oculto de sua tese de doutorado defendida mais tarde na Sorbonne, Ivan Domingues faz neste livro uma análise extensa e acurada da obra que o inspirou, As palavras e as coisas – uma arqueologia das ciências humanas. Ao mesmo tempo, realiza uma ansiada homenagem ao eminente filósofo, na ocasião dos 50 anos da obra, lançada em 1966 com grande repercussão na França e pelo mundo afora, inclusive no Brasil.', '[]', '10.7476/9786558581239', '9786558580966', 'https://books.scielo.org/id/sfttr', NULL, NULL, 'https://books.scielo.org/id/sfttr/cover/cover_thumbnail.jpeg', 411, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sfwtj', 'sfwtj', 'Animais de Laboratório: criação e experimentação', NULL, '["Antenor Andrade","Sergio Correia Pinto","Rosilene Santos de Oliveira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Veterinary', 'O livro proporciona o conhecimento das técnicas e das necessidades básicas no manejo de animais de laboratório, enfocando, principalmente, a questão da ética, do bem-estar do animal e da biossegurança. Dessa forma, o manual, resultado da compilação das aulas de 22 qualificados profissionais de diversas instituições brasileiras, oferece uma contribuição de grande relevância, apresentando ao leitor os diversos aspectos do bioterismo no momento em que se verifica uma profunda mudança nos padrões das pesquisas realizadas no Brasil. Literatura essencial para profissionais da área, incluindo os de nível técnico.', '["laboratory animals","animal husbandry","animal welfare","animal ethics","biosafety","bioterrorism","laboratory animal management"]', '10.7476/9788575413869', '9788575413869', 'https://books.scielo.org/id/sfwtj', 'https://books.scielo.org/id/sfwtj/pdf/andrade-9788575413869.pdf', NULL, 'https://books.scielo.org/id/sfwtj/cover/cover_thumbnail.jpeg', NULL, 74, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sg3mt', 'sg3mt', 'É veneno ou é remédio? Agrotóxicos, saúde e ambiente', NULL, '["Frederico Peres","Josino Costa Moreira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Pharmacology, Toxicology and Pharmaceutics', 'exposição humana a agrotóxicos 347Frederico Peres & Josino Costa Moreira 17. Reflexões sobre a educação relacionada aos agrotóxicos em comunidades rurais 367Com o lançamento desta obra, o mercado editorial brasileiro ganha mais uma importante contribuição de cientistas de diferentes instituições de pesquisa sobre os riscos do uso indiscriminado de agrotóxicos nas lavouras.Trata-se de uma abordagem interdisciplinar, tendo como foco os efeitos perniciosos desses produtos à saúde humana, ocasionados tanto pela ingestão de alimentos contaminados quanto pela exposição ocupacional a que estão sujeitos milhares de trabalhadores rurais.Também são destacados os impactos ambientais negativos resultantes da contaminação do solo, da água e do ar, cujos efeitos se manifestam em forma e intensidade variáveis, afetando seriamente o equilíbrio dos sistemas biológicos.Outros aspectos inerentes ao problema central são pontificados ao longo dos artigos.Neste particular, ressaltam-se as contribuições metodológicas referentes a técnicas de avaliação e gerenciamento de riscos, aplicadas a populações expostas a agrotóxicos, bem como diagnósticos de percepção desses riscos e as determinações socioambientais que tornam ainda mais complexa a abordagem do tema.Somam-se a essas considerações os desafios inerentes à capacidade de articulação institucional e de gerenciamento de projetos integrados de pesquisa.Os trabalhos aqui relatados resultam, em boa parte, de um esforço de pesquisadores do Centro de Estudos da Saúde do Trabalhador e Eco-PREFÁCIO 1 3 Estão de parabéns os articulistas, organizadores e editores deste livro, pela oportunidade e qualidade dos textos apresentados.O aprofundamento das questões aqui levantadas servirão de alerta e estímulo à necessária mudança de hábitos e comportamento de produtores, consumidores e até mesmo de formuladores de políticas públicas com vistas ao ideal de produção e incorporação aos sistemas produtivos agropecuários de tecnologias ''limpas'' que preservem a qualidade dos alimentos e o meio ambiente.', '["pesticides","pesticide exposure","food contamination","environmental contamination","risk assessment","risk management","risk perception","public policy","human health"]', '10.7476/9788575413173', '9788575413173', 'https://books.scielo.org/id/sg3mt', 'https://books.scielo.org/id/sg3mt/pdf/peres-9788575413173.pdf', NULL, 'https://books.scielo.org/id/sg3mt/cover/cover_thumbnail.jpeg', NULL, 110, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sgdgv', 'sgdgv', 'Processos de alcoolização Indígena no Brasil: perspectivas plurais', NULL, '["Maximiliano Loiola Ponte de Souza"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Processos de Alcoolização Indígena no Brasil de alcoolização são conceitos estreitamente relacionados, mas não intercambiáveis.A diferenciação e a contextualização desses conceitos evitariam alguns dos mais frequentes ''mal-entendidos'' que ocorrem ao serem utilizados.O álcool é uma substância química caracterizada por uma série de propriedades, cujas consequências e funções operam basicamente a partir dos usos sociais, econômicos e obviamente psicológicos produzidos pelos diferentes grupos.Isso significa dizer que o uso de álcool per se pode gerar algumas consequências patológicas no nível físico e/ou psíquico, em função das características de seu consumo e da vulnerabilidade dos sujeitos (cirrose hepática, intoxicação ou delirium tremens).Mas a maioria dos efeitos negativos não seria produto do consumo do álcool em si.Os homicídios, as agressões intrafamiliares e os acidentes não são consequências necessárias do consumo de álcool, mas sim comportamentos possíveis, considerados mais ou menos estimulados e/ou aceitos por diferentes sociedades, realizados por sujeitos específicos.A identificação e a autoidentificação de grupos étnicos ou de classes sociais com o ''alcoolismo'', assim como as estigmatizações ou relações de hegemonia/ subalternidade desenvolvidas em torno do álcool e do alcoolismo, são construções sociais geradas por meio de processos econômicos e políticos e/ou ideológicos/ culturais.Assim, a descrição das condições que caracterizam o consumo de álcool permitiria entender tanto determinadas consequências patológicas como a funcionalidade sociocultural desse mesmo uso.São essas condições -e não o ato de ingestão -que possibilitarão compreender a agressividade ou a estigmatização, tanto em nível individual como coletivo.Destaca-se que não é o caso de se negar o papel do sujeito, mas sim de alertar para necessidade de pensá-lo em articulação com processos socioculturais e/ou político-econômicos.No nosso entendimento, o álcool é, em determinados contextos, basicamente um instrumento, um meio, aparentemente imprescindível, para a concretização de relações e rituais sociais.Além disso, a pesquisa socioantropológica vem mostrando a quantidade e a variedade de funções que o álcool adquire em diferentes grupos sociais (Cortes, 1988).É desse ponto de vista que é possível compreender que o álcool pode cumprir em grupos étnicos mexicanos e brasileiros funções psicotrópicas, terapêuticas, alimentares, de sociabilidade, de coesão e integração cultural, de identificação e pertencimento social, de transgressão ou de ''válvula de escape'', tomando parte em rituais religiosos, profissionais e/ou familiares.Mas também pode funcionar como instrumento de controle social, de exploração econômica, de justificativas racistas, ou de legitimador de violências intrafamiliares.Além disso, o álcool pode ter, simultaneamente, efeitos negativos e positivos tanto para os sujeitos como para os grupos sociais.E é justamente nessa complexidade, devidamente explorada por vários autores deste livro, que se ancora o conceito de processo de alcoolização.13 Este conceito não apenas destaca as funções positivas dos usos do álcool, mas também reconhece que seu consumo, direta ou indiretamente, relaciona-se a um conjunto de agravos que constituem as principais causas de morbimortalidade tanto para a população em geral, como para grupos étnicos em particular.Em países como os Estados Unidos e o Canadá são os grupos étnicos o segmento populacional que apresenta as taxas mais altas de mortalidade por cirrose hepática.No caso dos povos indígenas dos Estados Unidos, quatro de suas dez principais causas de morte -acidentes, cirrose hepática, homicídio e suicídioestão associadas ao consumo de álcool.O ''abuso'' de álcool está relacionado com 38% de mortes entre eles, enquanto para o restante da população dos Estados Unidos representa somente 7,8% (NIAAA, 1985).Contudo, tanto os aspectos positivos como os negativos devem ser relacionados aos usos sociais das bebidas alcoólicas.E são esses usos pensados simultaneamente em termos contraditórios e complementares, que nos permitirão entender porque uma substancia produzida e disseminada pelos grupos dominantes foi apropriada pela maioria dos grupos étnicos até constituir-se em parte substantiva de suas identidades culturais mais profundas.A necessária articulação de perspectivas diferentes Meu interesse pelo estudo do ''alcoolismo'' e do processo de alcoolização se relaciona em grande medida às minhas preocupações com a estrutura e as funções do saber médico, que deu lugar a vários estudos nos quais descrevi e analisei determinadas limitações do que é denominado, desde os fins da década de 1970, de ''modelo médico hegemônico'' (Menéndez, 1990; Menéndez & Di Pardo, 1996).Ressalto que minhas análises, embora críticas em relação à biomedicina buscam impulsionar a necessária complementaridade entre as perspectivas biomédicas e aquelas desenvolvidas a partir da antropologia social.De acordo com dois dos mais importantes especialistas em adições, os estudos epidemiológicos sobre alcoolismo raramente têm, abordado as verdadeiras dificuldades teóricas desta problemática [uma vez que] predomina um tipo de investigação mecânica e reiterativa que trata o usuário de drogas como um objeto de estudo totalmente dissociado das condições culturais e das instituições sociais dentro das quais vive e consome drogas.(Edwards & Ariff, 1981: 291) Essas ''antigas'' conclusões continuam válidas para a maior parte das pesquisas epidemiológicas que se realizam, pelo menos no México, sobre o consumo de álcool e suas consequências.Entretanto, é este o ponto que agora me interessa destacar, grande parte dessa produção epidemiológica apresenta ainda sérias hepática se configura como uma das cinco principais causas de morte entre mulheres de 35 a 64 anos.Há mais de trinta anos fazem-se críticas consistentes a respeito das construções mais ou menos imaginárias que são produzidas por várias disciplinas a respeito do alcoolismo (Room & Collins, 1983).Mas a maioria de nossos especialistas continua sem levar em consideração essas críticas, e continuam estabelecendo medições que não apenas não são válidas em múltiplos aspectos, mas que distorcem gravemente a realidade.Essas críticas ao manejo de dados estatísticos a respeito do alcoolismo não negam a importância da produção epidemiológica, mas buscam evidenciar a necessidade de desenvolver estudos do tipo qualitativo que complementem e reorientem os estudos de tipo estatístico.Considero que o conjunto de trabalhos que integram este livro se caracterizam não só pela sua complementaridade, por pensar o alcoolismo como processo de alcoolização e por aplicar enfoques qualitativos, mas, sobretudo, por apresentar aportes descritivos e teóricos com base em diferentes disciplinas e experiências profissionais, o que possibilita ter um panorama abrangente do processo de alcoolização em, pelo menos, certos povos indígenas do Brasil.É por meio desses tipos de estudos, articulados a trabalhos estatísticos orientados teoricamente pelo conceito de processo de alcoolização, que poderemos desenhar estratégias de ação específicas que reduzam as consequências negativas do consumo de álcool e recuperem suas funções positivas.', '["alcohol consumption","alcoholism","alcohol-related violence","alcohol-related accidents","indigenous peoples of Brazil","alcohol policy"]', '10.7476/9788575415818', '9788575415818', 'https://books.scielo.org/id/sgdgv', 'https://books.scielo.org/id/sgdgv/pdf/souza-9788575415818.pdf', NULL, 'https://books.scielo.org/id/sgdgv/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sgdzk', 'sgdzk', 'O discurso do Supremo Tribunal Federal na Ditadura Militar', NULL, '["Mateus Gamba Torres"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '“Este livro tem como grande mérito mostrar, a partir de rigorosa pesquisa documental e histórica, o papel cumprido pelo Poder Judiciário na repressão estatal ocorrida durante a ditadura iniciada com o golpe de 1964. A obra também mostra o quanto não havia neutralidade nas suas decisões do Judiciário, absorvendo uma mistura ideológica marcada pelo anticomunismo, pela doutrina militar e pelos interesses da burguesia. Embora se refira a questões ocorridas décadas atrás, o debate colocado pelo livro remete o leitor à História do Tempo Presente, na medida em que permanecem os muitos dos elementos estruturantes do conservadorismo jurídico. Concretamente, temos visto em anos recentes leis sendo relativizadas de acordo com interesses políticos e econômicos, prisões arbitrárias e sem provas conclusivas, a intensificação da perseguição a movimentos sociais e até mesmo a manipulação de resultados eleitorais. A presente obra, portanto, ao refletir acerca da ditadura, permite também compreender o processo de crise da chamada Nova República, construída a partir do pacto entre ditadores e setores da oposição em nome da manutenção da ordem burguesa, materializado na Constituição de 1988.”', '["Brazilian military dictatorship","Supreme Federal Court","state repression","anti-communism","military doctrine","legal conservatism","arbitrary detention","New Republic","1964 coup","Brazilian Constitution of 1988","bourgeois order","judicial impartiality"]', '10.7476/9786558460541', '9786558460091', 'https://books.scielo.org/id/sgdzk', NULL, NULL, 'https://books.scielo.org/id/sgdzk/cover/cover_thumbnail.jpeg', 228, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sgprn', 'sgprn', 'Em busca da boa morte: antropologia dos cuidados paliativos', NULL, '["Rachel Aisengart Menezes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Fruto de um trabalho etnográfico, o livro Em Busca da Boa Morte, de Rachel Aisengart Menezes, aborda o novo ideário, conhecido como paliativista, que coloca em questão a morte fria e desprotegida no hospital – desse modo, o que se procura aqui é refletir acerca de um processo de mudança cultural, de contornos ainda pouco precisos, mas que, inegavelmente, procura humanizar o momento da morte, encarando a relação médico-paciente sob um outro ponto de vista . Trata-se de uma obra que traz à tona questões sobre a Ética no mundo contemporâneo, que banaliza a morte ou simplesmente não fala dela. Desse modo, o novo ideário constitui-se como uma resposta possível, mesmo que ainda ligada, à onisciência e onipresença da Medicina, quando o discurso médico já não possui respostas, conscientizando-se das suas limitações.', '["palliative care","good death","humanization of death","medical ethics","physician-patient relationship","limits of medicine"]', '10.7476/9786557081129', '9786557081129', 'https://books.scielo.org/id/sgprn', 'https://books.scielo.org/id/sgprn/pdf/menezes-9786557081129.pdf', NULL, 'https://books.scielo.org/id/sgprn/cover/cover_thumbnail.jpeg', NULL, 190, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sgvky', 'sgvky', 'Dramaturgia, ainda: reconfigurações e rasuras', NULL, '["Cleise Furtado Mendes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Os textos presentes neste livro abordam novas indagações que se colocam a partir da relação da dramaturgia com as mídias emergentes, analisando a sua convivência com noções fundamentais da teoria do drama, revisitadas sob nova perspectiva, em face da produção contemporânea.', '["dramatic theory","emerging media","contemporary drama","digital theatre"]', '10.7476/9788523211868', '9788523208318', 'https://books.scielo.org/id/sgvky', NULL, NULL, 'https://books.scielo.org/id/sgvky/cover/cover_thumbnail.jpeg', 239, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sj9xk', 'sj9xk', 'Tabagismo abordagem prevenção e tratamento', NULL, '["Sandra Odebrecht Vargas Nunes"]', 'EDUEL', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'tabagismo e ConDições méDiCas assoCiaDas o tabagismo é uma das maiores causas de doenças e mortes.A mortalidade geral é duas vezes maior nos fumantes quando comparados aos não fumantes.Fumar cigarro pode provocar: câncer, doença cardiovascular, doenças pulmonares, úlcera péptica e outras patologias.Esse hábito é considerado a mais importante causa de morbidade e mortalidade prematura no mundo.É responsável por cerca de 90% de câncer de pulmão em homens e 70% de câncer de pulmão em mulheres.Entre outros fatores de risco do tabagismo, estão 56-80% para doença pulmonar obstrutiva crônica (DPoC) e 22% para doenças cardiovasculares.o tabaco também é uma das principais causas de câncer de orofaringe, bexiga, pâncreas, laringe, esôfago, cólon e colo do útero.o tabagismo passivo, ou seja, a exposição à fumaça ambiental, é uma das causas de câncer de pulmão.(WORLD HEALTH ORGANIZATION, 2002).Estima-se que, em todo o mundo, por ano, ocorram cinco milhões de mortes relacionadas ao hábito de fumar, sendo ele responsável por 10 mil mortes por dia, ou seja, uma pessoa a cada seis segundos, reduzindo a expectativa de vida em 15 anos.(WORLD HEALTH ORGANIZATION, 2008).Se não ocorrerem mudanças no atual padrão de consumo de tabaco, a organização Mundial da Saúde (oMS) estima que o número de fumantes passará, do ano 2000 a 2030, de 1,2 bilhões para 1,6 bilhões, e que o número de mortes atribuíveis ao tabagismo passará para 10 milhões, sendo 1 tabagismo: Prevenção, aborDagem e tratamento tabagismo:', '["smoking","tobacco use","smoking prevention","smoking cessation","smoking-related diseases","lung cancer","chronic obstructive pulmonary disease","cardiovascular disease","passive smoking","smoking-related mortality"]', '10.7476/9788572166751', '9788572166751', 'https://books.scielo.org/id/sj9xk', 'https://books.scielo.org/id/sj9xk/pdf/nunes-9788572166751.pdf', NULL, 'https://books.scielo.org/id/sj9xk/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sknf2', 'sknf2', 'Gênero e saúde: uma articulação necessária', NULL, '["Elaine Reis Brandão"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-08-15', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O objetivo das autoras com este livro é gerar reflexão e diálogo – entre pesquisadores/as e estudantes de graduação e pós-graduação das áreas de ciências da saúde, ciências sociais e humanas, profissionais da saúde, gestores públicos, integrantes de instâncias de controle social do SUS e ativistas de movimentos sociais organizados – sobre a importância da compreensão da problemática de gênero como modo de organização da vida social, focando, especialmente, em seu impacto na configuração dos processos de saúde e doença em diversos grupos sociais. Para tanto, apresentam os íntimos entrelaçamentos entre os estudos históricos, sociológicos e antropológicos sobre gênero, os estudos sociais da ciência e tecnologia e o campo da saúde, que foram se consolidando ao longo da segunda metade do século XX até o presente, com implicações teóricas, éticas e políticas que incidem tanto na compreensão dos fenômenos de saúde-doença, nas práticas de atenção à saúde e de cuidados com o corpo, quanto na formulação de políticas públicas de saúde.', '["gender and health","health-disease process","health care practices","body care","health policy","social movements","social control in health","Unified Health System (SUS)","gender studies","health sciences"]', '10.7476/9786557081655', '9786557081358', 'https://books.scielo.org/id/sknf2', NULL, NULL, 'https://books.scielo.org/id/sknf2/cover/cover_thumbnail.jpeg', 136, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-skzcd', 'skzcd', 'Sífilis e Reforma da Saúde na Bahia (1920-1945)', NULL, '["Ricardo dos Santos Batista"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Resultado da pesquisa doutoral de Ricardo Batista, o livro situa-se na confluência das áreas de história da saúde pública, da medicina e das doenças, representando importante contribuição para a compreensão da trajetória político-sanitária da Bahia de 1920 até 1945, com atenção para o universo social, os vínculos e as diferenças entre o contexto local e os de outras regiões do país. Livro essencial para interessados em história da saúde pública na Bahia e no Brasil.', '["syphilis","health care reform","history of public health","Bahia","history of medicine","social history of health","Vargas era","regional health policy"]', '10.7476/9786588211076', '9788578873288', 'https://books.scielo.org/id/skzcd', 'https://books.scielo.org/id/skzcd/pdf/batista-9786588211076.pdf', 'https://books.scielo.org/id/skzcd/epub/batista-9786588211076.epub', 'https://books.scielo.org/id/skzcd/cover/cover_thumbnail.jpeg', 280, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sm7jd', 'sm7jd', 'As doenças e os medos sociais', NULL, '["Yara Nogueira Monteiro","Maria Luiza Tucci Carneiro"]', 'Editora Fap-Unifesp', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '[RETIRADO/WITHDRAWN] A coletânea reflete a produção de um dos segmentos de pesquisa do Laboratório de Estudos sobre Etnicidade, Racismo e Discriminação da Universidade de São Paulo(LEER-USP). Os ensaios aqui reunidos inserem-se em um campo do conhecimento ainda pouco explorado: o da história das doenças, dos medos, da discriminação e de sua repercussão no meio social.', '["disease history","social fear","discrimination","racism","ethnicity","social impact of illness","epidemics"]', '10.7476/9788561673826', '9788561673826', 'https://books.scielo.org/id/sm7jd', NULL, NULL, 'https://books.scielo.org/id/sm7jd/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-smcb9', 'smcb9', 'O cotidiano escolar de crianças, jovens e adultos em rodas de conversas', NULL, '["Fernandes, Andrea da Paixão","Lopes, Paula Cid"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro nasce das vivências do projeto de extensão universitária “Roda de Conversas – Cotidiano e Escola”, cujas atividades se apresentam como possibilidade de formação continuada de professores e de ampliação acadêmica para licenciandos em formação. Os artigos se baseiam nessas experiências, que remetem a fundamentos teóricos de Paulo Freire, e oferecem uma proposta de reflexão sobre temas caros à educação e à escola pública. Os autores são estudiosos dos contextos escolares e educativos, que atuam na educação regular e na modalidade educação de jovens e adultos (EJA), com pesquisas e práticas verdadeiramente inclusivas, autorais e contextuais. Com isso, trata-se de leitura que proporcionará um olhar aprofundado sobre as complexidades da aprendizagem humana bem como sobre os mais diferentes modos de ensinar aprender ensinar construídos no cotidiano das práticas pedagógicas.', '["school everyday life","university extension project","continuing teacher education","pre-service teachers","youth and adult education","Paulo Freire","public schools","inclusive education","teaching practice","learning and teaching"]', '10.7476/9786587949024', '9786587949024', 'https://books.scielo.org/id/smcb9', 'https://books.scielo.org/id/smcb9/pdf/fernandes-9786587949024.pdf', NULL, 'https://books.scielo.org/id/smcb9/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sn23w', 'sn23w', 'Peixes do baixo rio Iguaçu', NULL, '["Gilmar Baumgartner","Carla Simone Pavanelli","Dirceu Baumgartner","Alessandro Gasparetto Bifi","Tiago Debona","Vitor André Frana"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'O rio Iguaçu nasce na confluência dos rios Atuba e Irai, e desemboca no rio Paraná, em Foz do Iguaçu. A ictiofauna deste rio, desde os primeiros trabalhos realizados, sempre foi considerada pobre e de pequeno porte, entretanto, apresenta um elevado grau de endemismo favorecido pelo surgimento das Cataratas do Iguaçu, que exerceram um papel fundamental neste processo. Esta obra busca uma fonte aglutinadora, mas sintetizada, sistematizada, especializada e atualizada das informações publicadas, até o momento, sobre a ictiofauna do baixo rio Iguaçu, fornecendo chaves de identificação, caracterizações morfológicas, fotos, dados sobre a biologia e distribuição geográfica das espécies registradas na região, além de um glossário com termos técnicos.', '["ichthyofauna","Iguazu Falls","endemism","identification key","fish morphology","fish biology","geographic distribution","freshwater fish"]', '10.7476/9788576285861', '9788576285861', 'https://books.scielo.org/id/sn23w', 'https://books.scielo.org/id/sn23w/pdf/baumgartner-9788576285861.pdf', NULL, 'https://books.scielo.org/id/sn23w/cover/cover_thumbnail.jpeg', NULL, 116, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-snw6c', 'snw6c', 'Epistemologias da história: verdade, linguagem, realidade, interpretação e sentido na pós-modernidade', NULL, '["Gabriel Giannattasio","Rogério Ivano"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '[RETIRADO/WITHDRAWN] Este livro aborda o fazer historiográfico produzido pelos próprios historiadores e os desdobramentos mais recentes da história. O objetivo principal é promover reflexões sobre ideias e métodos da história, colocando em primeiro plano os fundamentos que sustentam o valor do conhecimento histórico.', '["epistemology of history","historiography","truth","language","reality","historical interpretation","meaning","postmodernity","historical method"]', '10.7476/9788572166744', '9788572166744', 'https://books.scielo.org/id/snw6c', NULL, NULL, 'https://books.scielo.org/id/snw6c/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-snxnr', 'snxnr', 'Poética oral do samba de roda das margens do Velho Chico', NULL, '["Nerivaldo Alves Araújo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Realizando uma viagem pelas águas poéticas do Velho Chico, a obra apresenta um estudo sobre as narrativas orais em prosa e verso e as canções do samba ribeirinho, que retratam a experiência cotidiana desse lugar e os sentidos diários que se configuram como as formas que as sambadeiras e sambadores veem o mundo. Sendo assim, o livro foca nas representações e simbologias presentes nas cantigas do grupo de samba de roda “É na pisada ê”, assim como os aspectos estruturais da lírica de sua poética, tais como: estrofe, rima, versificação, musicalidade, dentre outros.', '["samba de roda","oral narrative","song lyrics","riverbank communities","everyday life","poetic symbolism","versification","rhyme","musicality"]', '10.7476/9788523220310', '9788523220310', 'https://books.scielo.org/id/snxnr', 'https://books.scielo.org/id/snxnr/pdf/araujo-9788523220310.pdf', NULL, 'https://books.scielo.org/id/snxnr/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sny5t', 'sny5t', 'Políticas da diversidade: (in)visibilidades, pluralidade e cidadania em uma perspectiva antropológica', NULL, '["Denise Fagundes Jardim","Laura Cecília López"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A antropologia e as políticas da diversidade Nessa coletânea propomos uma aproximação com as políticas da diversidade a partir de uma abordagem antropológica.Temas como multiculturalismo, multiculturalidade, interculturalidade, diversidade cultural e pluralidade vêm sendo debatidos como noções chaves para políticas públicas nacionais e, por vezes, parecem apenas sinônimos, ocultando a densidade de seus usos e escolhas conceituais e políticas.A partir das décadas de 1980 e 1990, em especial na experiência sul-americana, o debate público tem se transformado no que tange à compreensão da experiência nacional com as "minorias".Novos sentidos, limites e desejos contidos nas noções de promoção de cidadania são consignados nas novas cartas constitucionais.Nelas, são contempladas políticas públicas relativas à promoção de equidade, que se encontram ligadas ao respeito e reconhecimento da pluralidade.Vislumbram-se efeitos (renovadores e contraditórios) dos processos políticos e esses reverberam nos debates sobre os ideais de nação e no tratamento de direitos até então vistos como formas de proteção a direitos minoritários.O ingresso de novos sujeitos políticos no diálogo com as políticas públicas tem chamado os antropólogos a examinar as práticas de justiça que vêm sendo elaboradas em um horizonte de política de Estado.Além de refletir, como é habitual para os antropólogos, sobre os usos da noção de diversidade e seus desafios atuais, nessa coletânea tomamos como objetivo a necessidade de dar a conhecer os modos como a antropologia e antropólogos têm sido conclamados a posicionar-se e frequentar espaços em que as noções de pluralidade e diversidade se tornam constitutivas das agendas públicas 1 .sociedades de origem, Venezuela, Uruguai, Argentina e Brasil durante sua formação acadêmica como antropólogos.Essa coletânea está organizada em duas partes.Na primeira parte, nomeada como "Cenários", reunimos artigos sobre o campo conceitual que orienta os debates sobre "minorias", políticas raciais, imigrações, e racismo institucional, destacando sua historicidade e ampliações decorrentes de processos de visibilização de protagonistas e "problemas sociais".Mostramos que os processos de (in)visibilização são um campo discursivo no qual agentes e narrativas científicas impõem limites e fazem emergir ou invisibilizar o vigor das alteridades.Apresentamos os cenários conceituais e as dificuldades em visibilizar determinadas problemáticas sociais referentes a sujeitos "às margens" dos debates nacionais.Indagamos como a invisibilização se transforma num espaço afirmativo, de identificações e pleitos na esfera pública, que reformulam as políticas de alteridades.Tal desafio nos coloca diante de uma questão fundamental.Como ampliar nosso horizonte conceitual para dar conta desses processos?Em "Alteridades e (in)visibilidades: uma perspectiva antropológica sobre direitos humanos e acesso a dignidade", Denise Jardim refere ao cenário de transformações dos olhares antropológicos contemporâneos, saindo das análises puramente normativas sobre direitos humanos para um alargamento de nossa compreensão sobre as dinâmicas que dotam de novos significados expressões envolvidas no debate sobre a dignidade humana e, em especial, a relação entre direitos humanos evidenciando normatividades situadas.Os debates sobre direitos humanos e de minorias étnicas e raciais se reformulam, ao passo que se ampliam horizontes conceituais e convergem preocupações de aprimoramento das noções de justiça social e equidade.É, segundo a autora, em relação à necessidade de uma hipervisibilidade de sujeitos e pleitos coletivos, contrapondo-se às políticas de alteridade calcadas no conforto da invisibilização das diferenças sob o manto da mistura e do amalgamento, que as noções de raça aparecem na cena política brasileira e vêm contribuindo na construção de um Estado plural.Em "Políticas raciais, diáspora e transnacionalismo para compreender as mobilizações negras e as ações afirmativas no Cone Sul", Laura C. López reflete sobre a configuração e as perspectivas das mobilizações negras contemporâneas em face aos pleitos por políticas públicas com enfoque étnico-racial e ações afirmativas no Brasil, no Uruguai e na Argentina.No cenário apresentado, o olhar antropológico amplia-se do', '["diversity policy","multiculturalism","multiculturality","interculturality","cultural diversity","plurality","citizenship","minority rights","public policy","state justice","nation-building","Latin America"]', '10.7476/9788538603856', '9788538603856', 'https://books.scielo.org/id/sny5t', 'https://books.scielo.org/id/sny5t/pdf/jardim-9788538603856.pdf', NULL, 'https://books.scielo.org/id/sny5t/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sp', 'sp', 'Cenários possíveis: experiências e desafios do mestrado profissional na saúde coletiva', NULL, '["Maria do Carmo Leal","Carlos Machado de Freitas"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Naquele ato regularizador foi feita também uma clara distinção entre cursos de especialização (destinados a treinamento, formação de atitudes e habilidades, sem abranger o campo total do saber em que se insere a especialidade) e cursos de mestrado, que podem também implicar especialização e operar no setor técnico-profissional, mas sempre no contexto de uma área completa de conhecimento, ou dando ampla fundamentação à aplicação de uma técnica ou ao exercício de uma profissão.Pode-se, portanto, identificar, na norma regularizadora, dois tipos de mestrado, diferenciados pelos seus objetivos centrais.Um deles tem como objetivo a realização de estudos avançados em uma disciplina específica, sem preocupação com suas aplicações.Corresponderia, na nomenclatura norte-americana, aos graus de Master of Arts (MA) e Master of Sciences (MS), sem designação específica da disciplina correspondente.Outro tipo visa à aplicação e extensão de conhecimentos a finalidades profissionais ou vocacionais.Diz respeito a graus como Master of Business Administration, Master of Arts in Education, Master of Engineering e Master of Arts in Teaching, nos Estados Unidos.O desenvolvimento da pós-graduação no Brasil nos últimos trinta anos deu origem a cursos de mestrado que, com raras exceções, caracterizam-se predominantemente como o primeiro degrau para a qualificação acadêmico-científica necessária à carreira universitária.À época, a justificativa para essa ênfase acadêmica, com a exclusão da vertente profissional, era de que ela seria suficiente para assegurar também a formação de pessoal de alta qualificação para atuar nas áreas profissionais, nos institutos tecnológicos e nos laboratórios industriais.Tal situação, dominante até os anos 80, não conseguiu se sustentar diante da intensidade, urgência e variedade das demandas que a sociedade brasileira passa a fazer, desde então, ao sistema universitário.A rápida evolução do conhecimento passou a exigir, dos graduados, formação avançada e atualizada; em paralelo, as organizações governamentais e não-governamentais passaram a exigir constante elevação da qualidade e produtividade dos seus serviços.Em complemento, a abertura de mercado passa a demandar das empresas um nível de competitividade que as leva a buscar profissionais com formação pós-graduada, de preferência mestrado.A evolução do conhecimento, a melhoria do padrão de desempenho e a abertura do mercado induzem, então, à busca de recursos humanos que permitam uma transferência mais rápida dos conhecimentos gerados na universidade e nos institutos de pesquisa para a sociedade.Buscam-se em todo o mundo formas mais diretas de vinculação do aparelho formador com empresas, agências não-governamentais e governo.Para atender a essas novas exigências e, de certa forma, complementar o espectro previsto para a pós-graduação no decreto supramencionado, a Capes lança, em 1995, as bases para a 20 regulamentação do mestrado profissional.Segundo a portaria da Capes, esse modelo de mestrado estará voltado para a formação profissional, a fim de melhorar a qualificação de técnicos do governo e de empresas públicas e privadas.Além das atividades de ensino, ele prevê a aplicação das pesquisas e o repasse de tecnologia à sociedade.Com duração mínima de', '["professional master''s degree","public health education","specialization courses","professional competence","public health workforce","United States comparison"]', '10.7476/9788575412855', '9788575412855', 'https://books.scielo.org/id/sp', 'https://books.scielo.org/id/sp/pdf/leal-9788575412855.pdf', NULL, 'https://books.scielo.org/id/sp/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-spd6r', 'spd6r', 'Reflexões e práticas na formação de educadores', NULL, '["César De David","Janete Webler Cancelier"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'na formação de professores: o GPET-UFSM........', '["teacher professional development","professional practice"]', '10.7476/9788575114759', '9788575114759', 'https://books.scielo.org/id/spd6r', 'https://books.scielo.org/id/spd6r/pdf/david-9788575114759.pdf', NULL, 'https://books.scielo.org/id/spd6r/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-spt2m', 'spt2m', 'Transformations in international politics, conflicts, regionalism, and Latin America', NULL, '["Milani, Lívia Peres","Mariano, Karina Lilia Pasquariello","Soares, Samuel Alves"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'en', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'An analysis of the main challenges standing between Latin America and equitable development. Nine years after the adoption of the 2030 Agenda by the United Nations General Assembly, international politics faces abundant challenges that pose a risk to the implementation of the 17 Sustainable Development Goals. This period has been defined by structural obstacles to development, rising inequality, threats to democracy, obstructions to international cooperation, a global pandemic, armed conflicts, and interstate wars. Latin America is profoundly affected by these dynamics, but also encounters specific challenges. In this context, the selection of articles collected in this volume analyzes these issues through the lens of international relations, especially security and regionalism, considering the interaction between local and global factors.', '["Latin America","sustainable development","Sustainable Development Goals","2030 Agenda for Sustainable Development","regionalism","security","armed conflict","international cooperation","inequality","democracy","COVID-19 pandemic","interstate war"]', '10.7476/9786559545599', '9786559543885', 'https://books.scielo.org/id/spt2m', 'https://books.scielo.org/id/spt2m/pdf/milani-9786559545599.pdf', NULL, 'https://books.scielo.org/id/spt2m/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sq6d8', 'sq6d8', 'Humanização dos cuidados em saúde: conceitos, dilemas e práticas', NULL, '["Suely Ferreira Deslandes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'A humanização tem sido associada a distintas e complexas categorias relacionadas à produção e gestão de cuidados em saúde, tais como: integralidade, satisfação do usuário, necessidades de saúde, qualidade da assistência, gestão participativa, protagonismo dos sujeitos e a intersubjetividade envolvida no processo de atenção. Esta obra busca apresentar um balanço crítico dos conceitos e perspectivas que atravessam tal ideário, e analisar os limites e possibilidades das iniciativas autodenominadas ‘de humanização’. Leitura destinada a todos os profissionais da saúde em suas distintas especialidades e formações, gestores, estudantes de graduação e pós-graduação, bem como aos pesquisadores dessa área temática.', '["humanization of health care","comprehensive care","patient satisfaction","health needs","quality of care","participatory management","protagonism","intersubjectivity","health management","healthcare workers"]', '10.7476/9788575413296', '9788575410790', 'https://books.scielo.org/id/sq6d8', 'https://books.scielo.org/id/sq6d8/pdf/deslandes-9788575413296.pdf', 'https://books.scielo.org/id/sq6d8/epub/deslandes-9788575413296.epub', 'https://books.scielo.org/id/sq6d8/cover/cover_thumbnail.jpeg', 416, 54, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sq8kx', 'sq8kx', 'Derecho del trabajo en el posfordismo: el proyecto de regulación universal en la globalización económica', NULL, '["Iván Daniel Jaramillo Jassir"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La construcción de la dogmática iuslaboral latinoamericana y particularmente colombiana ha estado desprovista de la inclusión de elementos de incidencia del gobierno global financiero en la producción normativa post-fordista. La adecuación de la disciplina laboral al nuevo contexto ha determinado el paso de derecho del trabajo al derecho del empleo, en el que el sistema de regulación laboral se subordina al sistema económico de la globalización neoliberal erosionando el principio protector y los contenidos democráticos de construcción de las normas que informan el trabajo. La presente investigación se ocupa, como hipótesis central, de la verificación de la demanda de universalización del derecho del trabajo que deriva de la ineficiencia de la construcción nacional para atemperar los efectos de la globalización económica. Así, las categorías nacionales fordistas de origen, resultan incapaces de asegurar estándares mínimos de dignidad (decencia) del trabajo en el sistema productivo deslocalizado del siglo XXI. El rediseño de la disciplina laboral comporta la identificación y estudio de nuevos instrumentos de regulación, nuevos sujetos y nuevas formas de justiciabilidad que se imponen para la regulación de las fugas que derivan de la movilidad del capital. Este libro reúne la propuesta de adaptación de la disciplina laboral al contexto de desaparición de fronteras nacionales contenida en la tesis doctoral defendida en junio de 2014 en la Universidad de Castilla-La Mancha la cual obtuvo calificación cum laude por unanimidad.', '["labor law","post-Fordism","globalization","neoliberalism","labor regulation","capital mobility","deindustrialization","labor standards","Colombian labor law"]', '10.7476/9789587385724', '9789587385717', 'https://books.scielo.org/id/sq8kx', NULL, NULL, 'https://books.scielo.org/id/sq8kx/cover/cover_thumbnail.jpeg', 340, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sqc8f', 'sqc8f', 'Los estudios organizacionales (‘organization studies’): fundamentos, evolución y estado actual del campo', 'fundamentos, evolución y estado actual del campo', '["Mauricio Sanabria","Juan Javier Saavedra Mayorga","Alí Smida"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2013, '2013-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', '“El objetivo de este texto es establecer una cartografía del campo de los estudios organizacionales (EO), más conocido internacionalmente como organization studies (OS). Presenta, en ocho capítulos, un panorama amplio de este campo, atendiendo a consideraciones históricas, teóricas, epistemológicas, metodológicas, institucionales, sociales, políticas, culturales y geográficas. La obra surge en el marco del núcleo de trabajo académico e investigativo en estudios organizacionales de la Escuela de Administración de la Universidad del Rosario, con la cooperación de la Universidad de París XIII – Sorbonne Paris Cité y la Association Internationale et Interdisciplinaire de la Décision (A2ID). Está dirigido a practicantes, consultores, asesores, estudiantes, investigadores y profesores en gestión, y a personas vinculadas a las ciencias sociales interesadas en conocer el origen, el estado actual y los principales desarrollos del campo de los estudios organizacionales”', '["organization studies","organizational policy"]', '10.7476/9789585005334', '9789587384383', 'https://books.scielo.org/id/sqc8f', 'https://books.scielo.org/id/sqc8f/pdf/sanabria-9789585005334.pdf', NULL, 'https://books.scielo.org/id/sqc8f/cover/cover_thumbnail.jpeg', NULL, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sqhks', 'sqhks', 'Geografias da noite: exemplos de pesquisa no Brasil', NULL, '["Turra Neto, Nécio"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A noite na cidade ainda é um objeto de estudo em construção para a geografia brasileira. Pesquisas sobre as práticas espaciais que são próprias da vida noturna, das tensões e dos conflitos que à noite se tornam explícitos ou que aparecem de forma latente, podem nos revelar, por um outro viés, os modos como se relacionam (e são constantemente reproduzidas) as desigualdades e as diferenças nas cidades brasileiras, as maneiras como identidades socioculturais são acionadas, performadas, instituídas e negociadas. O conjunto de textos que compõem este livro traz um pequeno panorama das possibilidades de incorporação do tema da noite na cidade ou da cidade à noite. Ao mesmo tempo, evidencia um campo em aberto, seja para considerarmos velhos temas em sua especificidade de acontecer durante a noite, seja para abordarmos aquilo que de fato só ganha condições de possibilidade neste tempo social.', '["night","urban night","nightlife","spatial practices","urban inequality","sociocultural identity","Brazilian cities","urban geography"]', '10.7476/9786557140550', '9786557140550', 'https://books.scielo.org/id/sqhks', 'https://books.scielo.org/id/sqhks/pdf/turra-9786557140550.pdf', NULL, 'https://books.scielo.org/id/sqhks/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sqj2s', 'sqj2s', 'Manual básico para atendimento ambulatorial em nutrição', NULL, '["Nilze Barreto Villela","Raquel Rocha"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Nursing', 'Trabalho educativo e esclarecedor acerca das mais variadas distorções alimentares que levam o indivíduo ao desequilíbrio nutricional. Foi elaborado com a finalidade de proporcionar melhoria no atendimento dos ambulatórios de nutrição, auxiliando não somente o entendimento das instruções fornecidas aos pacientes ou a seu cuidador, mas aos discentes (profissionais em formação) e outros profissionais da área da saúde. Obra de amplo interesse para a sociedade em gera', '["nutrition counseling","eating disorders","nutrient imbalance","patient education","caregiver education"]', '10.7476/9788523208998', '9788523208998', 'https://books.scielo.org/id/sqj2s', 'https://books.scielo.org/id/sqj2s/pdf/villela-9788523208998.pdf', NULL, 'https://books.scielo.org/id/sqj2s/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
