E WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-srfgc', 'srfgc', 'Peregrinação de Egéria: uma narrativa de viagem aos Lugares Santos', NULL, '["Maria Cristina da Silva Martins"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Para os estudiosos da Filologia Românica, uma tradução para o português, em edição crítica e bilíngue, da narrativa de peregrinação de Egéria – a Peregrinatio Egeriae –, com elaborado glossário e anotações filológicas, é motivo de comemoração. Não se trata apenas de mais uma edição do conhecido documento latino, mas o resultado de um paciente trabalho de anos. Em busca das indispensáveis fontes bibliográficas, a autora permaneceu um ano em Paris, junto à Sorbonne. [...] Estamos diante de um documento desafiador, na medida em que levanta muitas questões filológicas, históricas e factuais, que especialistas tentaram e ainda tentam responder. O leitor verificará que a presente obra traz algumas contribuições importantes para uma melhor compreensão desse documento. (Bruno Fregni Basseto)', '["Egeria","pilgrimage narratives","Portuguese translation","critical edition","bilingual edition","glossary","philological annotation","hagiography","sanctuaries","medieval Latin texts"]', '10.7476/9788570785190', NULL, 'https://books.scielo.org/id/srfgc', 'https://books.scielo.org/id/srfgc/pdf/martins-9788570785190.pdf', NULL, 'https://books.scielo.org/id/srfgc/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ssshp', 'ssshp', 'Industrialização e atitudes operárias: estudo de um grupo de trabalhadores', NULL, '["Leôncio Martins Rodrigues"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Nossa pesquisa tem uma pretensão modesta: nada mais anseia do que poder oferecer novos dados e quiçá algumas hipóteses para a análise sociológica da classe operária brasileira. Deve ser entendida como um trabalho exploratório, que visa levantar informações e possibilitar elementos para futuras e mais completas investigações científicas neste campo.', '["industrialization","Brazilian working class","sociology of work","employee attitudes","industrial workers"]', '10.7476/9788579820229', '9788579820229', 'https://books.scielo.org/id/ssshp', 'https://books.scielo.org/id/ssshp/pdf/rodrigues-9788579820229.pdf', NULL, 'https://books.scielo.org/id/ssshp/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-stjy4', 'stjy4', 'Mal-estar e moralidade: situação humana, ética e procriação responsável', NULL, '["Júlio Cabrera"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Mal-estar e Moralidade continua a linha ético-negativa de reflexão moral iniciada por Julio Cabrera no Projeto de ética negativa e continuada em Crítica de la moral afirmativa e em numerosos artigos. A ideia central da obra é que os humanos são colocados pelos seus progenitores numa situação atritada e perigosa, sempre ameaçados pela dor e pelo desânimo, situação impossível de resolver com categorias puramente morais. Esse fenômeno é chamado de “inabilitação moral”. A partir desse “mal-estar” estrutural, os humanos reagem de maneiras agressivas diante dos outros humanos, dos animais, das coisas e do meio ambiente, numa busca incessante de sobrevivência e de autovalorização. Ataca-se, assim, a tese corriqueira de uma “maldade” intrínseca dos humanos; sua infelicidade e agressividade não provêm de um “interior perverso” (como nos esquemas religiosos, nos quais um mundo bom foi estragado pelas ações dos humanos), mas dos atritos da situação estrutural em que foram colocados. Ações moralmente boas acontecem, mas nunca o são totalmente, e sempre como mérito pessoal dos agentes. Nesse sentido, os humanos não estragam o mundo, pelo contrário, tentam melhorá-lo, fracassando pelos limites da sua finitude. Tudo isso fornece as bases filosóficas para uma ética e uma bioética negativas que partem da “inviolabilidade negativa” de cada ser humano, do respeito ao outro colocado na mesma situação de mal-estar que nós, ética essa que se manifesta numa vida minimalista e disposta para a morte ética em benefício dos outros. Nesse minimalismo baseia-se uma atitude antinatalista de não procriar, pelo fato de a procriação – tanto a intencional quanto a acidental – manipular e prejudicar outros humanos colocando-os na situação estrutural de mal-estar para o nosso próprio benefício. Toda moralidade surge de uma atitude minimalista – austera, heroica e não procriativa – diante da situação estrutural. Além do problema crucial da procriação, o livro aborda também temas correlatos, como aborto, sexualidade, educação e suicídio, tal como interpretados dentro do escopo de uma (bio)ética negativa.', '["antinatalism","responsible procreation","abortion","sexuality","moral education","minimalism","ethics of death","finitude"]', '10.7476/9788523013516', '9788523012182', 'https://books.scielo.org/id/stjy4', NULL, NULL, 'https://books.scielo.org/id/stjy4/cover/cover_thumbnail.jpeg', 720, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-stqxp', 'stqxp', 'Vozes indígenas na saúde: trajetórias, memórias e protagonismos', NULL, '["Ana Lúcia de Moura Pontes","Vanessa De Souza Hacon","Luiz Eloy Terena","Ricardo Ventura Santos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O principal objetivo de Vozes indígenas na saúde é evidenciar o protagonismo indígena na elaboração, estruturação e implementação da política de saúde indígena no Brasil. O livro se baseia nos relatos de diversas lideranças indígenas acerca de suas trajetórias de vida e de atuação no movimento social indígena, com ênfase no campo da saúde. Ao conjugar distintas realidades culturais, regionais e, ainda, refletir sobre questões de gênero, Vozes indígenas na saúde apresenta um panorama diversificado de narrativas individuais que percorrem experiências pessoais e memórias coletivas sobre a construção da política de saúde indígena no Brasil, ressituando o lugar desses atores no processo, ao explicitar suas múltiplas lutas, debates e embates.', '["Indigenous health","Indigenous health policy","indigenous leadership","indigenous movements","indigenous protagonism","collective memory","life trajectories","gender","health activism","Brazil"]', '10.7476/9786557081709', '9786557081310', 'https://books.scielo.org/id/stqxp', 'https://books.scielo.org/id/stqxp/pdf/pontes-9786557081709.pdf', 'https://books.scielo.org/id/stqxp/epub/pontes-9786557081709.epub', 'https://books.scielo.org/id/stqxp/cover/cover_thumbnail.jpeg', 383, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-styg9', 'styg9', 'Prefácio', NULL, '["Renato da Gama-Rosa Costa","Alexandre Jose de Souza Pessoa"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Importante contribuição à cultura e à historiografia da arquitetura, oferece um panorama de como se deu a formação e a ocupação do campus de Manguinhos durante o primeiro século de existência da Fundação Oswaldo Cruz – maior instituição de pesquisa biomédica da América Latina e uma das mais respeitadas do mundo -, resgatando a história de seus construtores. Teve como ponto de partida um levantamento histórico dos edifícios da Fiocruz, enviado em 1999 ao Iphan para o tombamento definitivo da área de entorno do conjunto arquitetônico de Manguinhos, delimitada em 1986 e que agora cumpre uma significativa etapa na edição deste livro.', '["Fiocruz","architectural history","historic building inventory","medical research institutions","campus architecture"]', '10.7476/9786557081136', '9786557081136', 'https://books.scielo.org/id/styg9', 'https://books.scielo.org/id/styg9/pdf/costa-9786557081136.pdf', NULL, 'https://books.scielo.org/id/styg9/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sv74c', 'sv74c', 'A erradicação do Aedes aegypti: febre amarela, Fred Soper e saúde pública nas Américas (1918-1968)', NULL, '["Rodrigo Cesar da Silva Magalhães"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro analisa a Campanha Continental para a Erradicação do Aedes aegypti, o primeiro e mais duradouro programa internacional de erradicação já implementado. Lançada em 1947 sob os auspícios da Organização Sanitária Pan-Americana (OSP), então dirigida pelo médico norte-americano Frederick Soper, ela dava continuidade à Campanha Mundial de Erradicação da Febre Amarela, oficialmente iniciada em 1918, após o término da Primeira Guerra Mundial, pela Fundação Rockefeller. A Campanha Continental sintetizava importantes transformações do pós-Segunda Guerra Mundial e sinalizava um novo padrão de relacionamento das organizações internacionais e do governo norte-americano com os países da América Latina, especialmente o Brasil, com maior preponderância destes. O livro nos oferece uma análise original dos esforços envidados no passado recente e subsídios para realizarmos com sucesso este enfrentamento no presente - a recente epidemia causada pelo vírus Zika coloca novamente na ordem do dia o combate sem tréguas ao mosquito Aedes aegypti, também responsável pela transmissão da dengue e da febre chikungunya.', '["yellow fever","Pan American Health Organization","World Health Organization","history of public health","Latin America","Brazil","Rockefeller Foundation","Zika virus epidemic","dengue","chikungunya","mosquito control","US-Latin American relations"]', '10.7476/9788575414798', '9788575414798', 'https://books.scielo.org/id/sv74c', 'https://books.scielo.org/id/sv74c/pdf/magalhaes-9788575414798.pdf', NULL, 'https://books.scielo.org/id/sv74c/cover/cover_thumbnail.jpeg', NULL, 24, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-svc94', 'svc94', 'Direitos humanos e saúde: reflexões e possibilidades de intervenção', NULL, '["Maria Helena Barros de Oliveira","Nair Teles","Rubens Roberto Rebello Casara"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-09-03', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro inscreve-se no contexto em que se busca, no campo teórico e prático, pensar a saúde como um direito fundamental da pessoa humana, tendo na dignidade e na justiça socialsua base de concretização. Tem-se, ainda, como objetivo estimular e colaborar para fortalecer uma cultura de respeito aos direitos humanos e organizar ideias e ações que construam competênciasrelacionadas aos processos de realização do direito à saúde. A proposta não é rever toda a produção teórica que envolve a relação entre saúde e direitos humanos, mas tão somente apontaralgumas linhas sobre a emergência, a evolução e a necessidade da compreensão do binômio saúde e direitos humanos, em especial da dimensão da saúde como um direito resultante deuma conquista civilizatória a ponto de integrar a dimensão normativa do comum, portanto, um direito e um valor da esfera do inegociável. Pretende-se, assim, contribuir para a tomada deconsciência, a discussão teórico-prática e a modificação de posturas na busca da ampliação da dignidade de cada pessoa concreta a partir do significante saúde.', '["right to health","human rights","human dignity","social justice","health interventions","value of health"]', '10.7476/9786557081105', '9786557080412', 'https://books.scielo.org/id/svc94', NULL, NULL, 'https://books.scielo.org/id/svc94/cover/cover_thumbnail.jpeg', 133, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sw26r', 'sw26r', 'A vigilância punitiva: a postura dos educadores no processo de patologização e medicalização da infância', NULL, '["Fabiola Colombani Luengo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'deficit de atenção com hiperatividade.2. Crianças hiperativas.3. Disciplina escolar.4. Professores e alunos.I. Título.', '["teacher attitudes","pathologization of childhood","medicalization of childhood","attention deficit hyperactivity disorder","hyperactive children","student discipline","teachers and students"]', '10.7476/9788579830877', '9788579830877', 'https://books.scielo.org/id/sw26r', 'https://books.scielo.org/id/sw26r/pdf/luengo-9788579830877.pdf', NULL, 'https://books.scielo.org/id/sw26r/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sw5k7', 'sw5k7', 'La influencia de León Duguit en la reforma social de 1936 en Colombia: el sistema jurídico, la función social de la propiedad y la teoría de los servicios públicos', NULL, '["Ana Carolina Mercado Gazabón"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este texto muestra la sólida influencia de la corriente doctrinal del profesor francés León Duguit (1859–1928), en la reforma constitucional colombiana de 1936, desde tres perspectivas: el sistema jurídico, la función social de la propiedad y los servicios públicos. Para el primer tercio del siglo XX, en Colombia, al igual que sucedía en Norteamérica y los países europeos que encauzaban nuestra tradición jurídica, las tesis individualistas sobre el modelo de Estado y el derecho, habían envejecido y se planteaban nuevas interpretaciones del sistema jurídico imperante y del papel del Estado en la sociedad. En Colombia León Duguit secundaría de manera decisiva, aunque no exclusiva, tal proceso. Así las cosas la relevancia del documento radica en que logra demostrar como las teorías del autor francés fueron determinantes en la renovación del derecho público colombiano a partir de la década de los años treinta.', '["Léon Duguit","social function of property","legal system","role of the state","public law"]', '10.7476/9789587386387', '9789587386387', 'https://books.scielo.org/id/sw5k7', 'https://books.scielo.org/id/sw5k7/pdf/mercado-9789587386387.pdf', NULL, 'https://books.scielo.org/id/sw5k7/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-swr8b', 'swr8b', 'Celso Furtado: a esperança militante (Desafios): vol. 3', NULL, '["Cidoval Morais de Sousa","Ivo Marcos Theis","José Luciano Albino Barbosa"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O tema deste último volume da trilogia Celso Furtado: a esperança militante é Desafios. A palavra diz muito do espírito furtadiano. Ele próprio refletiu sobre o tema e escreveu, por exemplo, que o desafio do século XXI é mudar o curso da civilização, deslocar o seu eixo da lógica dos meios a serviço da acumulação para uma lógica dos fins, em função do bem-estar social, do exercício da liberdade e da cooperação entre os povos. E tudo isso num curto horizonte de tempo. As contribuições deste volume buscam refletir, estimular leituras, fazer proposições, recuperar os estudos regionais a partir do pilares que lhes deram identidade: o estudo do Brasil profundo e a interdisciplinaridade como elemento aglutinador das energias que mobilizam a produção de conhecimento para a transformação social. E onde estaria o pensamento regional hoje? As leituras que oferecemos neste volume sinalizam que ele se encontra, com maior ênfase, no interior do país, e em ‘universidades periféricas’, a maioria públicas (federais mais jovens, estaduais, comunitárias). Apesar de já significativa a diversidade de abordagens, há elementos transversais que possibilitam aproximações e compartilhamentos de experiências teóricas e práticas. O desenvolvimento regional já não constitui apenas o ponto de chegada de um projeto político, mas, também, um ponto de partida por meio do qual é possível compreender a realidade de uma nova forma.', '["Celso Furtado","regional studies","regional development","peripheral universities","interdisciplinarity","social change","social welfare"]', '10.7476/9786586221688', '9786586221688', 'https://books.scielo.org/id/swr8b', 'https://books.scielo.org/id/swr8b/pdf/sousa-9786586221688.pdf', NULL, 'https://books.scielo.org/id/swr8b/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-swrsv', 'swrsv', 'Como nos tornamos os professores que somos: uma problematização da herança estruturalista nas práticas de ensinar e aprender filosofia', NULL, '["Augusto Rodrigues"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A proposta deste livro é reconstruir as heranças formativas que, hegemonicamente, modelam a formação do professor de filosofia e sustentam as diretrizes da disciplina no ensino médio brasileiro. Para demonstrar os pressupostos e as práticas que marcam essa herança, o autor nos conduz à tradição de pesquisa e ensino do curso de Filosofia da Universidade de São Paulo, enunciando a figura do professor-explicador: professor formado para explicar os textos clássicos da filosofia à luz da metodologia estruturalista, cujo rigor interpretativo se consolidou a partir da distância entre a explicação e a discussão, debate e avaliação do texto. Problematiza, assim, as condições desse professor para ministrar na educação básica e, mais especificamente, para operar com a filosofia na construção de um pensamento do contemporâneo junto com os estudantes.', '["philosophy teacher training","structuralism","philosophy education","philosophy learning","secondary education","contemporary thought"]', '10.7476/9786586546200', '9786586546200', 'https://books.scielo.org/id/swrsv', 'https://books.scielo.org/id/swrsv/pdf/rodrigues-9786586546200.pdf', NULL, 'https://books.scielo.org/id/swrsv/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sx48d', 'sx48d', 'Monteiro Lobato nas páginas do jornal: um estudo dos artigos publicados em O Estado de S. Paulo (1913-1923)', NULL, '["Thiago Alves Leite"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'IN T R O D U Ç Ã OA fase compreendida pelos historiadores como de consolidação ou profissionalização da imprensa, início da República até a década de 1930, corresponde a um período relevante da atuação do escritor Monteiro Lobato (1882-1948) como jornalista.O intuito de se abordar os artigos publicados no jornal O Estado de S. Paulo, periódico fundado em 1875 como baluarte das questões ideológicas republicanas, permite situar o início da produção de Lobato, em 1913.O limite de 1930 justifica-se pelo momento histórico, ou seja, a transição de um país rural para um Estado em franca urbanização com o advento da era Vargas.Como veículo fugaz, o jornal apresenta-se como oportunidade para se rever uma faceta menos "literária" do escritor.A observação do conjunto de textos produzidos como artigos para O Estado entre os anos de 1913 e 1923 revela um escritor em fina sintonia com o veículo do qual participava e ajudava a construir, fosse na esfera dos ideais, fosse no círculo das atividades exercidas dentro do jornal.Lobato é, com efeito, um jornalista participando ativamente dos ideais políticos e sociais de um grupo cuja influência extrapolava a tão autoproclamada neutralidade do jornal.Havia um projeto de país em boa parte comum a escritor e jornal, ou melhor, entre o publicista atento e o periódico bem-sucedido."Uma velha praga", "Urupês" ou o quase não lembrado "Entre duas', '["Monteiro Lobato","O Estado de S. Paulo","journalism","newspaper articles","early Brazilian Republic","republican ideology","Brazilian press history"]', '10.7476/9788579831072', '9788579831072', 'https://books.scielo.org/id/sx48d', 'https://books.scielo.org/id/sx48d/pdf/leite-9788579831072.pdf', NULL, 'https://books.scielo.org/id/sx48d/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sx4bj', 'sx4bj', 'O rio e a casa: imagens do tempo na ficção de Mia Couto', NULL, '["Ana Cláudia da Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este estudo constitui-se de três momentos principais: a reflexão sobre a historiografia literária de Moçambique (apresentada no capítulo um), as considerações a respeito da fortuna crítica acadêmica monográfica de Mia Couto produzida no Brasil (que abordamos no segundo capítulo) e a análise da autointertextualidade na obra ficcional de Mia Couto (matéria que ocupa os capítulos três e quatro)', '["Mia Couto","Mozambican literature","literary historiography","river imagery","house imagery","time in fiction","Mozambique"]', '10.7476/9788579831126', '9788579831126', 'https://books.scielo.org/id/sx4bj', 'https://books.scielo.org/id/sx4bj/pdf/silva-9788579831126.pdf', NULL, 'https://books.scielo.org/id/sx4bj/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sxg7f', 'sxg7f', 'Funcionalismo e cognitismo na sintaxe do português: uma proposta de descrição e análise de orações subordinadas substantivas para o ensino', NULL, '["Ana Carolina Sperança-Criscuolo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Ana Carolina Sperança-Criscuolo.', '["functionalism","cognitivism","Portuguese syntax","subordinate clauses","syntax teaching","language teaching"]', '10.7476/9788568334454', '9788568334454', 'https://books.scielo.org/id/sxg7f', 'https://books.scielo.org/id/sxg7f/pdf/speranca-9788568334454.pdf', NULL, 'https://books.scielo.org/id/sxg7f/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-synhw', 'synhw', 'A literatura juvenil na escola', NULL, '["Benedito Antunes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne ensaios escritos em diferentes momentos, mas que têm como eixo comum a literatura juvenil produzida no Brasil do final do século XX ao início do XXI e duas preocupações explícitas: de um lado, a discussão da possível especificidade da chamada literatura juvenil; de outro, o estudo das implicações de sua utilização no ensino. Como os textos procuram demonstrar, enquanto a produção literária voltada exclusivamente para o público infantil parece bem caracterizada e ocupa lugar definido na atividade leitora das crianças, a literatura juvenil é frequentemente associada a finalidades didáticas e encontra certa resistência por parte da comunidade acadêmica, que tende a considerá-la menor ou mesmo um mero produto de consumo. Nestes ensaios, o autor oferece uma contribuição para o aprofundamento dos estudos da literatura juvenil e apresenta propostas de seu uso na sala de aula, às vezes sob a forma de roteiros de leitura, para que tanto o professor como o aluno possam tirar o melhor proveito da leitura dos livros analisados.', '["young adult literature","Brazilian literature","late 20th century","early 21st century","literature in education","reading instruction","reading guide","children''s reading","literary canon"]', '10.7476/9788595463318', '9788595463318', 'https://books.scielo.org/id/synhw', 'https://books.scielo.org/id/synhw/pdf/antunes-9788595463318.pdf', NULL, 'https://books.scielo.org/id/synhw/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-syqd9', 'syqd9', 'De "menor" a presidiário: a trajetória inevitável?', NULL, '["Sônia Altoé"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Nesta pesquisa optei por estudar especificamente egressos de estabelecimentos de assistência que se encontram nos presídios. Quem são eles? A proposta é fornecer dados sobre a trajetória dos jovens egressos e trazer à luz algumas das indagações que existem sobre as consequências da internação, tanto no que se refere ao jovem “carente”, como ao jovem “infrator”.', '["juvenile offenders","juvenile detention","youth trajectories","juvenile delinquency","social reintegration"]', '10.7476/9788599662977', '9788599662977', 'https://books.scielo.org/id/syqd9', 'https://static.scielo.org/scielobooks/syqd9/pdf/altoe-9788599662977.pdf', NULL, 'https://books.scielo.org/id/syqd9/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-syrjg', 'syrjg', 'A técnica como potência do humano: conexão de saberes em saúde e educação', 'conexão de saberes em saúde e educação', '["Francisco Milton Mendes Neto","Nize Maria Campos Pellanda","Maria de Fátima de Lima das Chagas"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esse livro tece considerações de fundo sobre a ciência e a técnica como agenciamentos sociais, pessoais e espirituais. Assim como adotamos uma atitude de breakdown em relação a um paradigma fragmentador na ciência, adotamos em relação à técnica a mesma postura de rompimento. Não existe ciência sem técnica, técnica sem ciência, humano sem técnica e assim por diante. À ciência triste do racionalismo absoluto negadora da vida e dos desejos, Nietzsche contrapunha a alegre GAIA ciência. Assim, o que procuramos fazer em relação à técnica é assumir a potência alegre da GAIA técnica, afirmadora de vida e da arte.', '["technology","science and technology","breakdown","Friedrich Nietzsche","Gaia","rationalism","affirmation of life","art","education and health"]', '10.7476/9788557571570', '9786587108773', 'https://books.scielo.org/id/syrjg', 'https://books.scielo.org/id/syrjg/pdf/mendes-9788557571570.pdf', NULL, 'https://books.scielo.org/id/syrjg/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-sysng', 'sysng', 'Individualização, cidadania e inclusão na sociedade contemporânea: uma análise teórica', NULL, '["Maria Izabel Sanches Costa","Áurea Maria Zöllner Ianni"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"Em uma época de transformações dos paradigmas modernos que guiaram a sociedade por mais de um século, as autoras analisam três conceitos: a individualização, a cidadania e o processo de inclusão-exclusão social. Tais conceitos são historicamente situados e sofrem alterações conforme seu contexto sócio político. Ao se debruçarem sobre eles, buscam situá-los segundo os paradigmas atuais.A individualização é conceituada como um processo transversal, que impacta sobremaneira as relações sociais na atualidade. Por sua vez, a cidadania é analisada segundo a ideia de pertencimento, participação política, bem como aquisição da consciência de ser portador de direitos e deveres. Vista como conceito complementar à cidadania, a inclusão é compreendida segundo os processos de vulnerabilidade social, impulsionada pela precarização do trabalho, corrosão da sociabilidade primária e a expansão dos estigmas, o que vem a impactar na exclusão/inclusão social.Este livro permite que o leitor compreenda melhor o momento em que estamos, suas contradições e desafios na busca de uma sociedade mais inclusiva e democrática."', '["individualization","citizenship","social inclusion","social exclusion","social vulnerability","precarious employment","stigma","political participation","contemporary society","democracy"]', '10.7476/9788568576953', '9788568576953', 'https://books.scielo.org/id/sysng', 'https://books.scielo.org/id/sysng/pdf/costa-9788568576953.pdf', NULL, 'https://books.scielo.org/id/sysng/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-szgxv', 'szgxv', 'Genealogia do Direito à Saúde: uma reconstrução de saberes e práticas na modernidade', NULL, '["Marconi do Ó Catão"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro apresenta uma abordagem sobre como foram construídos os saberes inerentes à medicina e ao hospital na Sociedade Moderna. Mostra, historicamente, como foi estabelecido o poder e as práticas médico-hospitalares. A obra apresenta o discurso das instituições dominantes sobre o modelo assistencial, como também revela a realidade pragmática do acesso efetivo ao direito social à saúde, que, formalmente, foi expresso como uma necessidade básica traduzida em mínimos sociais, como condição legítima de dignidade da pessoa humana. A relevância desse estudo é em virtude de sua especial significação nas diversas áreas das Ciências Humanas e Sociais, ao nutrir o debate sobre a temática do Direito à Saúde nas instâncias do Poder Público, bem como ao introduzi-la na agenda das profissões relacionadas com o campo da saúde, aprofundando suas dimensões de transdisciplinariedade e transversalidade.', '["right to health","history of medicine","hospitals","medical power","health care access","social rights","human dignity","modernity","public power","health professions"]', '10.7476/9788578791919', '9788578791919', 'https://books.scielo.org/id/szgxv', 'https://books.scielo.org/id/szgxv/pdf/catao-9788578791919.pdf', NULL, 'https://books.scielo.org/id/szgxv/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-szv5t', 'szv5t', 'Impactos da violência na escola: um diálogo com professores', NULL, '["Simone Gonçalves de Assis","Patrícia Constantino","Joviana Quintes Avanci"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'A ''violência'' é o nome que se dá a um ato, uma palavra, uma situação, etc., onde um ser humano é tratado como um objeto, isto é, onde são negados seus direitos à dignidade de ser humano, de membro de uma sociedade, de sujeito insubstituível.Assim definida, a violência é o exato contrário da educação, que ajuda a advir o ser humano, o membro de uma sociedade, o sujeito singular.', '["school violence","teacher perceptions","human dignity","education and violence","human rights"]', '10.7476/9788575413302', '9788575413302', 'https://books.scielo.org/id/szv5t', 'https://books.scielo.org/id/szv5t/pdf/assis-9788575413302.pdf', NULL, 'https://books.scielo.org/id/szv5t/cover/cover_thumbnail.jpeg', NULL, 27, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t23t6', 't23t6', 'Pesquisa em educação escolar: percursos e perspectivas', NULL, '["José Milton de Lima","Divino José da Silva","Paulo César de Almeida Raboni"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A coletânea tem como eixo central a Educação Escolar e este tema conduz e confere unidade às reflexões, abordado a partir de diferentes perspectivas. A preocupação que perpassa todos os textos pode ser expressa na seguinte pergunta: como enfrentar os problemas vividos pela escola, num momento em que a ela se atribui uma gama enorme de responsabilidades? Cada autor, circunscrito à sua temática de pesquisa, nos instiga a pensar essa questão. O que move cada um é o desejo de que a escola acolha aqueles que lá chegam e que se responsabilize por eles, mas sem perder de vista o quanto é complexa e delicada essa atividade de inserção dos novos neste mundo. Talvez, a ideia de responsabilidade seja mesmo a que melhor defina os propósitos gerais desta coletânea, a qual se manifesta no compromisso político com a educação de crianças e de adolescentes, portanto, no compromisso com o mundo em que vivemos. A resposta a essa pergunta poderá ter como parâmetro os textos aqui presentes que estão assim organizados: na primeira parte da coletânea, os autores lidam com aspectos relacionados às Políticas Públicas e Educação; na segunda abordam a Formação de Professores; na terceira parte, focam Valores e Educação e, na quarta parte, voltam-se para as Práticas Educativas. Concluímos, destacando que esta coletânea explicita o quanto é complexa a tarefa de investigar a educação escolar, pois ela comporta uma série de nuances que precisa ser analisada por diferentes saberes que são complementares.', '["educational research","research methodology","research training","new researchers","school education","research lines","graduate education in education","school responsibility","inclusive education","education policy","teacher professional development","educational values","teaching practice","children and adolescents"]', '10.7476/9788579831294', '9788579830945', 'https://books.scielo.org/id/t23t6', 'https://books.scielo.org/id/t23t6/pdf/lima-9788579830945.pdf', NULL, 'https://books.scielo.org/id/t23t6/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t267z', 't267z', 'Gastronomía y turismo: una reflexión cultural', NULL, '["Alvelayis Nieto Mejía"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'A través de cuatro (4) experiencias en el contexto latinoamericano, esta obra de-rivada de investigación evidencia cómo la gastronomía es un elemento de valor en los procesos locales. Incluso, es un recurso identitario que contribuye al desarrollo cultural y afianza las representaciones sociales de una comunidad. Por tanto, es importante trans-mitir estos conocimientos a las presentes y futuras generaciones, de forma que se gene-ren procesos de apropiación cultural. Además, la gastronomía es un recurso que con una correcta planificación y gestión puede consolidarse como un atractivo turístico cultural, debido a que hay turistas que buscan deleitarse con platos originales.', '["gastronomy","cultural tourism","culinary heritage","cultural identity","social representations","cultural appropriation","cultural development","tourism planning and management","Latin America","intergenerational knowledge transmission"]', '10.7476/9786289558210', '9786289558210', 'https://books.scielo.org/id/t267z', 'https://books.scielo.org/id/t267z/pdf/nieto-9786289558210.pdf', NULL, 'https://books.scielo.org/id/t267z/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t2xxr', 't2xxr', 'Leituras de Norbert Elias: processo civilizador, educação e fronteiras', NULL, '["Ademir Gebara","Célio Juvenal Costa","Magda Sarat"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A coletânea Leituras de Norbert Elias: processo civilizador, educação e fronteiras é representativa do esforço de um grupo de pesquisa que, individual e coletivamente, vem trabalhando com as teorias de Norbert Elias, num processo longo, se considerarmos as diferentes gerações e a diversidade dos trabalhos produzidos, conforme este livro o demonstra. Resultado de investigações que pautam nas teorias de Elias ou que com elas dialogam desde a década de 60 do século XX, a coletânea apresenta uma trajetória de pesquisadores que se debruçaram e se debruçam sobre o pensamento do sociólogo alemão, apresentando esforços de gerações que se constituíram, academicamente, ao longo do século XX até a atualidade.', '["Norbert Elias","civilizing process","education","borders","sociological theory","history of sociology"]', '10.7476/9788576286523', '9788576286189', 'https://books.scielo.org/id/t2xxr', NULL, NULL, 'https://books.scielo.org/id/t2xxr/cover/cover_thumbnail.jpeg', 263, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t387x', 't387x', 'Construção social da aprendizagem em saúde mental e saúde da família', NULL, '["Débora Cristiane Silva Flores Lino","Erika Antunes Vasconcellos","George Amaral Santos","João Mendes de Lima Júnior","Laura Regia Oliveira Cordeiro","Luís Fernando Tófoli","Nairan Morais Caldas","Viviane dos Santos Souza"]', 'Editus - Editora da UESC', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'O livro apresenta os múltiplos sentidos relacionados aos temas que envolvem o ensino/aprendizagem em saúde mental no cenário da Estratégia de Saúde da Família e também da formação nas instituições de ensino superior.', '["mental health education","Family Health Strategy","social construction of learning","higher education","health professions education"]', '10.7476/9788574554471', '9788574553504', 'https://books.scielo.org/id/t387x', 'https://books.scielo.org/id/t387x/pdf/lino-9788574554471.pdf', NULL, 'https://books.scielo.org/id/t387x/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t3q4b', 't3q4b', 'Cidade e campo: olhares de Brasil e Portugal', NULL, '["Eduarda Marques da Costa"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As designações cidade e campo têm desde sempre inspirado múltiplas leituras em geografia e sociologia, passando-se de uma abordagem centrada na caracterização e na evolução do campo e da cidade para novas abordagens que, nas últimas três décadas, consideram a emergência de espaços marcados pela urbanização estruturada em torno da acessibilidade. Este livro apresenta um conjunto de onze contribuições centradas em temas da geografia, retratados nas realidades de Brasil e Portugal, destacando abordagens sobre conceitos e dicotomias que remetem à relação entre cidade e campo, assim como análises de aspectos diversos, como agricultura, turismo, transporte e mobilidade, segurança, políticas públicas e desafios para o desenvolvimento dos territórios em ambos países. Os capítulos permitem entender panoramas que decorrem de trajetórias distintas no que tange à relação entre campo e cidade. No caso da realidade europeia, em que a revolução industrial incentivou o maciço êxodo dos campos para as cidades; e no contexto brasileiro, cujos processos de urbanização assumiram uma natureza política muito forte, a industrialização como motor de crescimento das cidades constituiu-se um fator mais tardio.', '["urbanization","accessibility (transport and spatial geography)","urban-rural dichotomy","agriculture","tourism","transport and mobility","security","public policy","territorial development","industrialization","rural exodus","Brazil"]', '10.7476/9786587949055', '9786587949055', 'https://books.scielo.org/id/t3q4b', 'https://books.scielo.org/id/t3q4b/pdf/marafon-9786587949055.pdf', NULL, 'https://books.scielo.org/id/t3q4b/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t42fm', 't42fm', 'Invernada dos Negros: história e luta de uma comunidade negra rural', NULL, '["Lidiane Taffarel"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra apresenta o estudo realizado na primeira comunidade quilombola reconhecida em Santa Catarina, Invernada dos Negros, que se localiza nos municípios de Campos Novos e Abdon Batista, no Meio Oeste catarinense. Para a municipalidade, as localidades que compõe o território denominam-se Manuel Cândido, Espigão Branco, Arroio Bonito e Corredeira, mas para os moradores é a Invernada dos Negros em que estão presentes laços de parentesco, sociabilidade e religiosidade, descendência de africanos escravizados, além do acesso à terra transmitido através de testamento. “Invernada dos Negros: história e luta de uma comunidade negra rural” apresenta o protagonismo dos negros e, para tal, descreve o contexto, o cenário em que viviam/vivem. Trata-se de um histórico de invisibilidade da comunidade, sem acesso a condições dignas de sobrevivência, e como os moradores, ao longo dos anos, foram perdendo seu território, desde 1928, quando um advogado e alguns legatários entraram com uma ação de divisão de terras. Através do laudo, de documentários e atas da associação, fica claro como alguns costumes dos antepassados não foram preservados, entretanto, nem por isso os moradores deixaram de ser/se identificar como negros. Ao relatar a falta de políticas públicas e condições a que os negros foram submetidos pós-1888 ou as dificuldades dos moradores da comunidade Invernada dos Negros, a autora busca contextualizar os pontos de partida dessas pessoas que lutaram por seus direitos, resistiram a esse cenário inicial, sem vitimizá-los.', '["quilombola communities","Santa Catarina","land tenure","land inheritance","descendants of enslaved Africans","racial identity","social movements"]', '10.7476/9786550190347', '9786550190347', 'https://books.scielo.org/id/t42fm', 'https://books.scielo.org/id/t42fm/pdf/taffarel-9786550190347.pdf', NULL, 'https://books.scielo.org/id/t42fm/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t4ksj', 't4ksj', 'Front Matter / Elementos Pré-textuais / Páginas Iniciales', NULL, '["Machado, Maria Helena"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1995, NULL, 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', '', '[]', '10.7476/9788575416075', '9788585676179', 'https://books.scielo.org/id/t4ksj', 'https://books.scielo.org/id/t4ksj/pdf/machado-9788575416075.pdf', 'https://books.scielo.org/id/t4ksj/epub/machado-9788575416075.epub', 'https://books.scielo.org/id/t4ksj/cover/cover_thumbnail.jpeg', 226, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t4r56', 't4r56', 'Pragmática menor em Gilles Deleuze', NULL, '["Hélio Rebello Cardoso Júnior"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Gilles Deleuze estabeleceu uma metáfora que mostra bem o desafio de comentar a obra de um pensador. Ela consiste em pensar esse processo como o arremesso de um dardo em que uma geração recebe o objeto de um lançador e, para valorizar esse esforço, é necessário enviá-lo cada vez mais longe, onde alguém dará seguimento ao processo. O autor busca seguir o conselho de Deleuze para que esta ação tenha sucesso, ou seja, aumentar as distinções que o pensador prévio, o que significa, na pragmática da atividade crítica, abrir no campo das idéias do intelectual que se está estudando uma fresta que permita retirar algum elemento novo. Surge, assim, um problema filosófico presente em um pensamento, mas que não havia sido antes formulado explicitamente. Ele é visto como “menor”, segundo o filósofo, por se desvincular das grandes linhas de senso comum, consideradas majoritárias, que nutrem uma opinião em torno de certa centralidade reconhecida como evidente. A partir dessa perspectiva, o livro percorre um plano conceitual que circunscreva, por meio de noções e conceitos apropriados, o que efetivaria essa pragmática segundo as coordenadas filosóficas do pensamento de Gilles Deleuze. A vinculação, nesses termos, entre filosofia da imanência e empirismo é a aposta ontológica maior.', '["Gilles Deleuze","immanence","empiricism","ontology","common sense"]', '10.7476/9786557145371', '9786557145371', 'https://books.scielo.org/id/t4r56', 'https://books.scielo.org/id/t4r56/pdf/rodrigues-9786557145371.pdf', NULL, 'https://books.scielo.org/id/t4r56/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t4s9t', 't4s9t', 'Questões da saúde reprodutiva', NULL, '["Karen Giffin","Sarah Hawker Costa"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Coletânea cujo tema central é a saúde reprodutiva, abordada com enfoques diferentes do tradicional. Contendo um panorama atualizado do conhecimento adquirido até o momento sobre a saúde reprodutiva da mulher brasileira, responde a uma demanda crescente por informações de qualidade. Fornece subsídios para tratar, de maneira integrada, saúde, sexualidade e direitos reprodutivos. Assim, torna-se instrumento para a organização e a sistematização da reflexão analítica relativa a resultados de investigação e a balanço de experiências de implementação de políticas sociais. Somatório de olhares de autores de áreas diversas que certamente estimulará o diálogo interdisciplinar.', '["reproductive health","Brazilian women","sexuality","reproductive rights","social policy implementation","interdisciplinary perspectives"]', '10.7476/9788575412916', '9788575412916', 'https://books.scielo.org/id/t4s9t', 'https://books.scielo.org/id/t4s9t/pdf/giffin-9788575412916.pdf', NULL, 'https://books.scielo.org/id/t4s9t/cover/cover_thumbnail.jpeg', NULL, 23, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t545j', 't545j', 'A herança simbólica na azulejaria barroca: os painéis do claustro da Igreja de São Francisco da Bahia', NULL, '["Patrício Dugnani"]', 'Editora Mackenzie', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '[RETIRADO/WITHDRAWN] De forma surpreendente e inédita, esta obra analisa os 37 painéis de azulejos do claustro da Igreja de São Francisco da Bahia, e, assim, preenche a lacuna existente na vasta bibliografia a respeito da azulejaria portuguesa no Brasil. Os enigmáticos painéis com temas mitológicos e herméticos seduzem pela plasticidade barroca e pelos segredos neles contidos – que agora são revelados. O leitor é conduzido por meio dos mistérios da criação das cenas “traduzidas” por Otto van Veen. O método iconográfico de Erwin Panofsky auxilia na interpretação desse presente de D. João V aos franciscanos baianos. O ocultamento da verdade aguça o esclarecimento daquele período interpolado pelos poderes da Igreja, do Estado e dos filósofos na busca de conjugação entre paganismo, cristianismo e hermetismo.', '["symbolic heritage","Hermeticism","mythological imagery","Otto van Veen","Erwin Panofsky","iconography","John V of Portugal","Franciscan Order","occultism"]', '10.7476/9788582930502', '9788582930502', 'https://books.scielo.org/id/t545j', NULL, NULL, 'https://books.scielo.org/id/t545j/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t5qq6', 't5qq6', 'Leia-me negras: insurgências afroafetivas na prática pedagógica', NULL, '["Fátima Santana Santos"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro é resultado de processo de pesquisa realizada junto ao Programa de Mestrado em Ensino e Relações Étnico-Raciais da Universidade Federal do Sul da Bahia. A autora desenvolveu uma série de narrativas teórico-críticas a partir de itinerâncias formativas construídas, de 2015 a 2018, no Centro Municipal de Educação Infantil Dr. Djalma Ramos, em Lauro de Freitas/BA. A pesquisa realizada visou elaborar e debater, de forma epistemologicamente afrocentrada, narrativas docentes e escritas de si, auto/biografias de formação, que pudessem contribuir para uma educação antirracista para crianças pequenas. A primeira parte do livro traz um relato de formação descritivo e interpretativo, com traços do método etnográfico em educação, colocando em evidência experiências vividas pela autora, durante sua prática profissional como coordenadora pedagógica, em uma instituição escolar de ensino público. A segunda parte do livro traz reflexões e propostas educacionais, ao descrever e analisar práticas curriculares e projetos pedagógicos escolares. Ao longo do livro, são destacados, formulados e sistematizados princípios metodológicos para uma educação antirracista para crianças pequenas. Tais princípios foram identificados na materialidade das experiências pedagógicas do coletivo de professoras atuantes no CMEI Dr. Djalma Ramos. A base teórico-metodológica deste trabalho se fez, principalmente, com (ANZALDÚA, 2000; CAVALEIRO, 2001; 2017; MACEDO, 2013; 2015; JOSSO, 2004; RIBEIRO, 2017; HOOKS, 2005, 2006; ABRAMOWICZ, RODRIGUES, CONSENTINO, 2009; EVARISTO, 2007; JESUS, 2016).', '["Afrocentric education","anti-racist education","early childhood education","teacher professional development","teaching practice","teacher narratives","curriculum practice","educational project","racial relations in education","Lauro de Freitas"]', '10.7476/9788574555485', '9788574555485', 'https://books.scielo.org/id/t5qq6', 'https://books.scielo.org/id/t5qq6/pdf/santos-9788574555485.pdf', NULL, 'https://books.scielo.org/id/t5qq6/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t65ct', 't65ct', 'Avaliação nutricional: escolares, adultos, idosos e hospitalizados', NULL, '["Lílian Barbosa Ramos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A fim de reconhecer a importância de identificar e compreender a situação nutricional de indivíduos dos diferentes grupos etários, considerando suas especificidades, são apresentados e discutidos os critérios para seleção e interpretação dos principais indicadores para avaliação nutricional de indivíduos escolares, adultos, idosos e hospitalizados e disponibilizada uma proposta para a elaboração do diagnóstico nutricional. São descritas as avaliações semiológica, antropométrica, bioquímica, funcional e alimentar, conduzindo a reflexões sobre suas aplicações e limitações em cada grupo.', '["nutritional assessment","nutritional status","elementary school students","adults","older adults","hospitalized patients","anthropometry","biochemical markers","functional assessment","dietary assessment","nutritional diagnosis"]', '10.7476/9786556303864', '9786556301679', 'https://books.scielo.org/id/t65ct', NULL, NULL, 'https://books.scielo.org/id/t65ct/cover/cover_thumbnail.jpeg', 149, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t67zr', 't67zr', 'Políticas e sistemas de saúde em tempos de pandemia: nove países, muitas lições', NULL, '["Cristiani Vieira Machado","Adelyne Maria Mendes Pereira","Freitas Carlos Machado de"]', 'Série Informação para ação na Covid-19 | Fiocruz', 'Brasil', 'SciELO Books', 'books', 2022, '2022-04-06', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Uma crise multidimensional, cujas consequências para a saúde das populações a médio e longo prazos são potencializadas pelas desigualdades e pelas situações de alta vulnerabilidade social. É dessa forma que três pesquisadores da Fiocruz, organizadores do e-book, classificam uma pandemia, com foco especial na emergência da Covid-19. A coletânea apresenta estudos de casos de nove países de três regiões do mundo. Da Ásia foram incluídas a China e a Coreia do Sul. Da Europa, foram analisados os casos de Alemanha, Espanha e Reino Unido. Na região das Américas, quatro países foram estudados: Argentina, Brasil, Canadá e México. Foram pesquisadas as políticas de enfrentamento da doença em cada uma dessas nações, considerando seus contextos e características prévias de seus sistemas e coberturas de saúde, além das estratégias adotadas no âmbito da atenção e da vigilância. Este é o quinto e último livro da série "Informação para Ação na Covid-19", que tem como objetivo reunir o conjunto de respostas, pesquisas e ações técnicas produzidas pela Fiocruz durante a pandemia. Com apoio da rede SciELO Livros, a iniciativa disponibiliza as obras exclusivamente em formato digital e acesso aberto.', '["COVID-19 pandemic","health policy","health care system","pandemic response","health insurance coverage","health surveillance","health care delivery","health disparities","social vulnerability","comparative case study"]', '10.7476/9786557081594', '9786557081594', 'https://books.scielo.org/id/t67zr', 'https://books.scielo.org/id/t67zr/pdf/machado-9786557081594.pdf', NULL, 'https://books.scielo.org/id/t67zr/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
