nt), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t6zhg', 't6zhg', 'Lenin: capitalismo de estado e burocracia', NULL, '["Leôncio Martins Rodrigues","Ottaviano De Fiore"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este trabalho trata dos escritos de Lenin sobre a sociedade soviética, mais especificamente sobre os problemas relacionados ao que se convencionou chamar de “construção do socialismo” na Rússia. Entre os dirigentes do Partido Bolchevique, Lenin foi um dos primeiros a se preocupar com a caracterização do tipo de sociedade que resultara da Revolução de Outubro. [...]', '["Lenin","state capitalism","bureaucracy","Soviet society","Bolsheviks","Russian Revolution","Soviet Union"]', '10.7476/9788579820212', '9788579820212', 'https://books.scielo.org/id/t6zhg', 'https://books.scielo.org/id/t6zhg/pdf/rodrigues-9788579820212.pdf', NULL, 'https://books.scielo.org/id/t6zhg/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t7', 't7', 'Oswaldo Cruz: a construção de um mito na ciência brasileira', NULL, '["Nara Pinheiro Reis Ayres de Britto"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1995, '1995-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'recorrente, da vida social, da construção ideológica do mito.Em o fazendo, ajuda-nos a entender os conflitos, as angústias e as utopias de uma época, projetados no esforço de fabricação de nosso primeiro e único herói da ciência.', '["Oswaldo Cruz","history of science","Brazilian science","social construction of science","scientific utopia"]', '10.7476/9788575412893', '9788575412893', 'https://books.scielo.org/id/t7', 'https://books.scielo.org/id/t7/pdf/britto-9788575412893.pdf', NULL, 'https://books.scielo.org/id/t7/cover/cover_thumbnail.jpeg', NULL, 39, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t8gjz', 't8gjz', 'Discurso imagético: significados na transposição do conhecimento científico no ensino de física', 'significados na transposição do conhecimento científico no ensino de física', '["Alan Santos dos Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Como as imagens ensinam física? Neste instigante livro, Alan Santos dos Santos nos convida a refletir sobre o papel das imagens no ensino de ciências, especialmente da física. A partir de conceitos da semiótica peirceana e da teoria da transposição didática, o autor apresenta o “discurso imagético” como uma poderosa ferramenta de mediação do conhecimento científico em sala de aula. A obra combina teoria, prática docente e crítica contemporânea, oferecendo uma leitura acessível e essencial para professores, pesquisadores e entusiastas da educação. Uma contribuição inovadora para pensar a linguagem visual na formação docente e no processo de aprendizagem.', '["physics education","didactic transposition","Peircean semiotics","visual language","teacher professional development","knowledge mediation"]', '10.7476/9786556309064', '9786556307503', 'https://books.scielo.org/id/t8gjz', 'https://books.scielo.org/id/t8gjz/pdf/santos-9786556309064.pdf', NULL, 'https://books.scielo.org/id/t8gjz/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-t9bbv', 't9bbv', 'La reforma al proceso ejecutivo: estudio del impacto que sobre este tiene el análisis económico del derecho', NULL, '["Gabriel Hernández Villarreal"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Múltiples y de antaño han sido las propuestas encaminadas a reformar el proceso ejecutivo, mas todas ellas han tenido que afrontar el hecho de que en éste se entroncan dos procedimientos que son de naturaleza diversa, lo que ha generado un desplazamiento hacia un tipo de proceso que ya no tiene como objeto único la ejecución, sino que también persigue la declaración del derecho. Adicionalmente, tales propuestas de cambio se han centrado en los aspectos normativos, dejando de lado —por lo menos en forma explícita— cualquier consideración acerca de la escuela de pensamiento más influyente en los últimos 30 años, como es la del análisis económico del derecho. Bajo ese contexto y desde una perspectiva liberal, propia de la corriente del denominado garantismo procesal, la presente obra no solo se ocupa de diferenciar las distintas clases de títulos ejecutivos y las variadas ejecuciones que podrían adelantarse con base en ellos, así como de proponer unos cambios en el diseño del procedimiento empleado para lograr el cumplimiento de las obligaciones que se reclaman por esta vía; sino además de exponer el impacto directo que sobre tales modificaciones tiene en una economía de mercado el análisis económico del derecho.', '["enforcement proceedings","law and economics","procedural reform","enforcement title","liberal legal thought","market economy","enforcement of obligations"]', '10.7476/9789587385083', '9789587385076', 'https://books.scielo.org/id/t9bbv', NULL, NULL, 'https://books.scielo.org/id/t9bbv/cover/cover_thumbnail.jpeg', 105, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tb94w', 'tb94w', 'Práticas investigativas em atividade física e saúde', NULL, '["Helio José Bastos Carneiro de Campos","Francisco José Gondim Pitanga"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A coletânea abrange diversos temas, entre eles: as concepções da imagem corporal entre praticantes e instrutores de musculação, fisiculturistas e estudantes de Educação Física na região metropolitana de Salvador; a atividade física como fator de proteção para co-morbidades cardiovasculares em mulheres obesas; prevalência e fatores associados à inatividade física em adultos na cidade de Lauro de Freitas-BA, entre outros.', '["physical activity","health","body image","weightlifting","bodybuilders","physical education students","cardiovascular comorbidity","obesity","women","physical inactivity","prevalence","risk factors"]', '10.7476/9788523212209', '9788523212209', 'https://books.scielo.org/id/tb94w', 'https://books.scielo.org/id/tb94w/pdf/campos-9788523212209.pdf', NULL, 'https://books.scielo.org/id/tb94w/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tcxf3', 'tcxf3', 'Entre o Brasil e os Estados Unidos: intelectuais, ideias e projetos de educação (1927-1935)', NULL, '["Ana Cristina Santos Matos Rocha"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Vencedora do prêmio Capes de melhor tese de história de 2017, Ana Rocha traz, agora em livro, a trajetória de quatro educadores brasileiros – Noemy Rudolfer, Isaías Alves, Lourenço Filho e Anísio Teixeira – entre as décadas de 1920 e 1930, tendo como ponto principal as viagens que realizaram ao Teachers College, na Universidade de Columbia, em Nova York. A partir desses deslocamentos institucionais, mas também culturais, econômicos e políticos, cada intelectual desenvolveu um papel importante na educação brasileira: Anísio Teixeira e Lourenço Filho articularam um projeto nacional de formação de professores; Noemy Rudolfer e Isaías Alves trabalharam em serviços ligados à psicologia, com testes de inteligência, trazendo a psicologia educacional para o debate brasileiro. Essas diferentes atuações sinalizaram uma busca por um discurso científico que estivesse alinhado com o projeto de modernidade pelo qual passava o Brasil na década de 1930, época em que o país ainda lutava contra o alto grau de analfabetismo de sua população. Mais do que uma troca de ideias entre países, esses intelectuais representam um quadro de problemas e soluções da educação no Brasil, iniciadas no século XX, e que até hoje constituem um grande desafio para o sistema educacional brasileiro.', '["history of education in Brazil","Teachers College, Columbia University","Lourenço Filho","Anísio Teixeira","teacher professional development","educational psychology","intelligence tests","modernity","illiteracy","1920s-1930s"]', '10.7476/9786557080832', '9786557080214', 'https://books.scielo.org/id/tcxf3', NULL, NULL, 'https://books.scielo.org/id/tcxf3/cover/cover_thumbnail.jpeg', 308, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tczd9', 'tczd9', 'A violência das letras: amizades e inimizades na literatura brasileira Rio de Janeiro (1888-1940)', NULL, '["César Braga-Pinto"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Estudo da sociedade brasileira do fim do século XIX e começo do século XX, delineado a partir das evidências de como os escritores interagiam e da maneira como retratavam os mecanismos das relações cotidianas. O autor debate as vivências de fraternidade, como reflexo dos valores da época, observando os paradigmas de inclusão (ou exclusão) racial, social ou sexual. Como base para essa análise, aponta episódios que marcaram a trajetória de literatos como Raul Pompeia, Adolfo Caminha, Cruz e Souza, Nestor Vitor, José Lins do Rego, Gilberto Freyre, entre outros.', '["Brazilian literature","Rio de Janeiro","literary friendship","literary rivalry","social exclusion","racial inclusion","fraternities","late 19th century","early 20th century","Raul Pompeia","Adolfo Caminha","José Lins do Rego"]', '10.7476/9788575115008', '9788575114605', 'https://books.scielo.org/id/tczd9', NULL, NULL, 'https://books.scielo.org/id/tczd9/cover/cover_thumbnail.jpeg', 496, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-td3ky', 'td3ky', 'La democracia inesperada', NULL, '["Bernardo Sorj"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este es un libro refrescante: no tiene nada trillado, rechaza con fundamento diversos convencionalismos y modas académicas, y no vacila en tomar clara posición en temas espinosos. Con este libro Bernardo Sorj muestra una vez más lo que ya sabíamos los que hemos seguido su trayectoria: no es sólo un excelente sociólogo profesional, es también y sobre todo un verdadero intelectual, un pensador crítico de las grandes cuestiones de nuestro mundo — especialmente el Latinoamericano.', '["democracy","Latin American democracy","political thought","critical thinking","Latin American politics"]', '10.7476/9788599662564', '9788599662564', 'https://books.scielo.org/id/td3ky', 'https://books.scielo.org/id/td3ky/pdf/sorj-9788599662564.pdf', NULL, 'https://books.scielo.org/id/td3ky/cover/cover_thumbnail.jpeg', NULL, 17, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tdj4g', 'tdj4g', 'Saúde e Doença: um olhar antropológico', NULL, '["Paulo César Alves","Maria Cecília de Souza Minayo"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1994, '1994-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'sobre o campo de prestação de serviços de saúde em Paulínea Marcos S. Queiroz Capítulo 13 167 Terapeutas corporais no Rio de Janeiro: relações entre trajetória social e ideário terapêutico Jane A. Russo Todos os textos convergem para questionar o modelo que se fundamenta apenas na técnica, desconhecendo ou menosprezando o conteúdo de totalidade e abrangência que contorna os problemas de saúde.Os artigos foram elaborados por pesquisadores que participaram do I Encontro Nacional de Antropologia Médica, realizado em Salvador entre os dias três e seis de novembro de 1993.A proposta desse evento partiu justamente da premissa de que já era tempo de reunir pesquisadores, professores e alunos que pudessem discutir as diversas tendências da Antropologia da Saúde no Brasil, maximizando o intercâmbio entre múltiplas perspectivas e tradições intelectuais dentro desse campo do saber.O I Encontro Nacional em Antropologia Médica foi inicialmente idealizado durante a realização da II Conferência Brasileira de Epidemiologia, em Belo Horizonte (1992),', '["medical anthropology","Paulínia","social trajectories","holistic health"]', '10.7476/9788575412763', '9788575412763', 'https://books.scielo.org/id/tdj4g', 'https://books.scielo.org/id/tdj4g/pdf/alves-9788575412763.pdf', NULL, 'https://books.scielo.org/id/tdj4g/cover/cover_thumbnail.jpeg', NULL, 58, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tdr4k', 'tdr4k', 'Os dilemas da gestão escolar: nova gestão pública no nordeste', 'nova gestão pública no nordeste', '["Rodrigo da Silva Pereira","Catarina Cerqueira de Freitas Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea busca refletir coletivamente sobre a educação pública e os dilemas que atravessam o trabalho das(os) diretoras(es) escolares de redes estaduais do Nordeste, tendo em vista a introdução dos princípios da Nova Gestão Pública (NPG) na gestão educacional e escolar - no Brasil, introduzidos a partir da Reforma do Estado da década de 1990. Além de contribuir com a defesa da democracia na educação pública escolar e com o debate sobre o avanço dos parâmetros da NGP na gestão escolar, o livro tenciona as contradições existentes no campo ao questionar a prevalência da pauta neoliberal nas instituições educativas e disputar a formulação de outras políticas.', '["school management","New Public Management","public education","school principals","educational management","Reforma do Estado","neoliberalism in education","democratization of education","Northeast Brazil","state education network"]', '10.7476/9786556309330', '9786556308050', 'https://books.scielo.org/id/tdr4k', 'https://books.scielo.org/id/tdr4k/pdf/pereira-9786556309330.pdf', NULL, 'https://books.scielo.org/id/tdr4k/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tfgbq', 'tfgbq', 'Agadá: dinâmica da civilização africano-brasileira', NULL, '["Marco Aurélio Luz"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Movido por profundas questões existenciais, Marco Aurélio Luz aborda o processo civilizatório que sofreram os africanos no Brasil, mostra a importância da presença histórica, social e cultural do negro na constituição da identidade nacional brasileira. Para tanto o livro é dividido em quatro partes, nas quais: demonstra os valores e a linguagem da civilização e cultura da África pré-colonial; caracteriza os valores do colonialismo, do mercantilismo e do escravismo e seus desdobramentos na atualidade; aborda o real significado histórico da insurgência negra na África e no Brasil, caracterizado como uma luta pela afirmação existencial própria, e procura demonstrar a dinâmica da reposição dos valores e linguagem do processo civilizatório negro africano na formação social brasileira.', '["Afro-Brazilian identity","colonialism","mercantilism","slavery","African diaspora","national identity formation"]', '10.7476/9788523211561', '9788523210748', 'https://books.scielo.org/id/tfgbq', NULL, NULL, 'https://books.scielo.org/id/tfgbq/cover/cover_thumbnail.jpeg', 501, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
